window.__D("text/torat-chaim/c022",{"p":[[2300540221,"התגלות שלו בלבד, כמו מאותיות הרצון נמשך אור השכל ומאותיות השכל נמשך המדות וכמ\"כ מאותיות המדות נמשך המחשבה ומאותיות המח' נמשך הדיבור ומן האותיות הדבור נמשך למעשה. וכך הוא למעלה בהשתלשלות דעו\"ע<sup data-n=\"7953\">49</sup> כשלשלת<sup data-n=\"7954\">50</sup> שטבעת התחתונה קשורה בקצה העליונה כמו משלשלי' פירות<sup data-n=\"7955\">51</sup> כו' כמשלשלי' בחבל<sup data-n=\"7956\">52</sup> כו' שהוא ענין הירידה מגבוה לנמוך נק' השתלשלו' כידוע, כך הוא בירידת האור האלקי שנק' [כח] הפב\"נ כנ\"ל בכלל ובפרט כמ\"ש ואתה מחיה<sup data-n=\"7957\">53</sup> כו' א\"ת כללות האותיות<sup data-n=\"7958\">54</sup> דבחי' מל' דאצי' שמחי' כל העולמות מאין ליש ונמשך ויורד בהשתלשלו' מעילה לעילה באופן זה שבחי' אותיות שבעליון נעשה מקור לתחתון עד התהוות הברואי' היותר תחתונים בגלגלי' וד' יסודות הגשמיי' ארמ\"ע<sup data-n=\"7959\">55</sup> וד' מדרגות דצח\"מ דעשי' שזהו הנק' השתלשלו' דעו\"ע עד שנתהווה מרוחניות לגשמיות ממש כד\"י הגשמיי', וכידוע דד\"י הגשמיי' ודצח\"מ מקבלי' מחיצוניות השפע הנמשך מן המזלות וגלגלי' דעשי' כמו שא' דאין לך עשב למטה<sup data-n=\"7960\">56</sup> שאין לו מזל שאומר לו גדל כו' שהוא מקור בחי' רוחניות דצומח שיגדל מכח הצומח שבארץ תלוי במזל הרוחני דגלגל, וכן גידול ההר ג\"כ מן המזל כמו גדא דהר<sup data-n=\"7961\">57</sup>, וכן יש מזל לחי ומדבר ופרטי כל הברואי' שבארץ בכל אקלים ובכל מקום בפרט שמזה יבא השינוי באופן טבעם בכאו\"א, וגם ההשגחה להשפיל ולהרים בזמני' ידועים לפי הילוך וסיבוב הגלגלים וכוכבי' ומזלות הקבועי' בהם (כמ\"ש אשר חלק ה' אותם לכל<sup data-n=\"7962\">58</sup> כו'), רק אין מזל לישראל<sup data-n=\"7963\">59</sup> כו', ויש לכל אדם מזל שלו בעת תולדתו אם יהי' עני או עשיר חלש או גבור<sup data-n=\"7964\">60</sup> כו', והן היו החוזי' בכו\"מ<sup data-n=\"7965\">61</sup> בימים הקדמוני' ככשדי' וכלדיי'<sup data-n=\"7966\">62</sup> רק שנק' ע\"ז<sup data-n=\"7967\">63</sup> שאסור לישראל להאמין <span data-k=\"pg\">רלב</span> ּ בהם ולעבד[ם] וזה הי' חטא הדורות דב\"ר שהי' עובדי' לכו\"מ וכמ\"ש הנשים ומאז חדלנו לקטר<sup data-n=\"7968\">64</sup> למלכת השמים כו', וגם ב\"נ נצטוו ע\"ז<sup data-n=\"7969\">65</sup> כידוע (וגם הפלסופי' מקצתם יודו בזה שהן ממוצעי' בין סיבה הראשונה שמסבב הגלגלי' לד\"י שעל ידם יומשך כל שפעם אך באמת הן כגרזן ביד החוצב<sup data-n=\"7970\">66</sup> כו'<sup data-n=\"7971\">67</sup> וכמו שאו' ומסדר הכוכבי' כרצונו<sup data-n=\"7972\">68</sup> דוקא) (ועיי' באג' הרמב\"ם ובס' המדע שקורא לנפש הגלגלי' דעשי' בשם שכליי' נבדלים<sup data-n=\"7973\">69</sup> כו' ובאמת הן רק מקבלים מן בחי' חיצוניות הכלים דאופני'<sup data-n=\"7974\">70</sup> כמ\"ש בע\"ח בסופו)",[["7953","49","<b>בהשתלשלות דעו\"ע</b>: ראה גם מאמרי אדה\"א במדבר ח\"א ע' לג ואילך. דברים ח\"ג ע' תתעו ואילך."],["7954","50","<b>בהשתלשלות. . כשלשלת</b>: ראה גם לעיל פ' שמות כד, ב. וש\"נ."],["7955","51","<b>משלשלי' פירות</b>: נסמן לעיל כט, ג."],["7956","52","<b>כמשלשלי' בחבל</b>: ראה ביצה לו, א. תוספתא מכשירין ספ\"ב."],["7957","53","<b>ואתה מחיה</b>: נחמי' ט, ו."],["7958","54","<b>א\"ת כללות האותיות</b>: ראה גם שער היחוה\"א פ\"ב."],["7959","55","<b>וד' יסודות הגשמיי' ארמ\"ע</b>: נסמן לעיל ה, ד."],["7960","56","<b>דאין לך עשב למטה</b>: נסמן לעיל ס, ב."],["7961","57","<b>גדא דהר</b>: חולין מ, א."],["7962","58","<b>אשר חלק ה' אותם לכל</b>: ואתחנן ד, יט [ושם: ה\"א]."],["7963","59","<b>אין מזל לישראל</b>: נסמן לעיל פ' שמות ב, א."],["7964","60","<b>עני או עשיר חלש או גבור</b>: ראה נדה טז, ב."],["7965","61","<b>החוזי' בכו\"מ</b>: ראה גם מאמרי אדה\"א במדבר ח\"א ע' לד."],["7966","62","<b>וכלדיי'</b>: ראה פסחים קיג, ב וברש\"י ורשב\"ם בם. ובהנסמן עה\"ג שם. ברכות סד, א. סנהדרין צה, א."],["7967","63","<b>שנק' ע\"ז</b>: ראה רמב\"ם הל' ע\"ז בתחלתן."],["7968","64","<b>ומאז חדלנו לקטר</b>: ירמי' מד, יח [ושם: ומן אז — ראה מאמרי אדה\"ז הנחות הר\"פ ר\"ע יז [ושם: מאז]. לקמן פ' יתרו ער, ג. ערב, ב. שע\"ת ה, א הערה 8]."],["7969","65","<b>ב\"נ נצטוו ע\"ז</b>: סנהדרין נו, סע\"א ואילך."],["7970","66","<b>כגרזן ביד החוצב</b>: מו\"נ ח\"ג פכ\"ט. ישעי' י, טו."],["7971","67","<b>כו'</b>: א: בו. בו: ליתא."],["7972","68","<b>ומסדר הכוכבי' כרצונו</b>: תפלת ערבית [בדילוג]. ראה גם מאמרי אדה\"א בראשית ע' סה ואילך. במדבר ח\"א ע' לג."],["7973","69","<b>באג' הרמב\"ם ובס' המדע.. לנפש. . שכליי' נבדלים</b>: הל' יסוה\"ת פ\"ג, ה\"ט ובפי' שם. מו\"נ ח\"ב פ\"ב-פ\"ו. וראה ע\"ח (שער קיצור אבי\"ע) ש\"נ, פ\"ח. מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תקנח. ענינים ע' קסז. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8158830010\" data-slug=\"or-hatorah-hb\" data-id=\"8158830010\">אוה\"ת מסעי ע' א'שצח</a>. ס' החקירה ע' יג. מאמרי אדה\"א שמות (כאן) ע' קט. במדבר ח\"א ע' לג."],["7974","70","<b>הגלגלים. . מקבלים. . דאופני'</b>: ראה פרדס (שער אבי\"ע) שט\"ז, פ\"ח. וראה גם ע\"ח (שער קיצור אבי\"ע) ש\"נ, פ\"ח. (שער ציור עולמות) שמ\"ג, פ\"ב. לעיל פ' וארא ס, ג הערה 38."]]],[2300540253,"וגבוהים עליהם כו' שמחיצוניות האופני' נמשך למזלות וכמו גשם ממש יחשבו המזלו' והגלגלים לגבי האופני' וחיות הקדש כידוע. ועד\"ז ממש יש לכל עולם לעולם שלמטה ממנו ירידת השפע מעילה לעלול גם בעולמות העליונים יותר שהן מלאכי' דעולם היצי' שלמעלה הרבה ממלאכי' דעשי' כאופני' עד צבא השמים [כגלגלים] דעשי', שגם הם בערך גשמיות לגבי רוחניות לגבי מעלת המלאכי' דבריאה מצד שיר[י]ד[ת] האור האלקי שנמשך [ה]כל בצמצומי' דעו\"ע דחיצוניות שבעליון לתחתון (שזהו מבחי' מל' שבעליון נעשה כתר לתחתון<sup data-n=\"7975\">71</sup> ) ובדרך כלל הן ג' עולמות דבי\"ע כידוע, משום דבחי' כח האלקי שהן ע\"ס דמל' דאצי'<sup data-n=\"7976\">72</sup> שיורד [ומתצ'] ומשתלשל מעילה לעלול דמל'<sup data-n=\"7977\">73</sup> דמל' דאצי' נעשה מקור לבריאה ומל' דבריאה נעשה כתר ליצי' וכן מיצי' לעשי' וע\"כ גם העולמות המתהוי' מן ע\"ס דבי\"ע הן באי' בסדר השתלשלות עד\"ז והן ג' מיני מלאכי' דבי\"ע שהוא מ\"ש ג\"פ הבו<sup data-n=\"7978\">75</sup> כו' כידוע והן ג' מדרגות דמודו\"מ<sup data-n=\"7979\">74</sup> דמאותיות המח' דבריאה נמשך לדבור דיצי' ומדיבור עד סוף העשי' וד\"ל.\n<b>והנה</b> ידוע שבסדר [ה]השתלשלו' של כל העולמות מאצי' לבי\"ע שנק' ממכ\"ע הוא ג\"כ בבחי' ציור אדם נפש בגוף<sup data-n=\"7980\">76</sup> עד\"מ כמו ציור אברי האדם לגבי נפשו כמו שא' מה הנשמה ממלא<sup data-n=\"7981\">77</sup> כו' כך הקב\"ה ממלא כל העולמות ונק' נשמת כ\"ח<sup data-n=\"7982\">78</sup> כו', וכמו שהאברים הם בחי' כלים מוגבלים ומצומצמי' שמקבלים האור והחיות הרוחני דנפש יש בהן חילוקי מדרגות מזה לזה בריבוי אופנים שונים כמו כח הראי' בכלי העין לראות ובידים לפעול מלאכה וברגל להילוך, וכן בכל פעולת אברים הפנימי' מתחלקי' כחות הנפש הרוחניות בכאו\"א לפי מזגו ופעולתו בסדר והדרגה ובהילוך השפע וחיות מזה לזה שכולם מקושרים ואחוזים זע\"ז וזעג\"ז<sup data-n=\"7983\">79</sup> עד שבאמצעו' כולם יפעלו פעולתם ע\"פ הרצון ושכל ומדות בתנועה א' לא ישנו תפקידם לעולם כו'. וכך הוא הדוגמא בבחי' ציור אדם העליון שמתלבש בעולמות הגם שאין לו גוף<sup data-n=\"7984\">80</sup> ולא דמות הגוף וכמ\"ש כי לא ראיתם כל תמונה<sup data-n=\"7985\">81</sup> כו', מ\"מ נזכר בכתובי' תוארי אדם כמו עיני ה'<sup data-n=\"7986\">82</sup> אזני ה'<sup data-n=\"7987\">83</sup> כו' וישב ה'<sup data-n=\"7988\">84</sup> הנה ה' עומד<sup data-n=\"7989\">85</sup> וכה\"ג [וידוע] שזהו מצד התלבשות כח האלקי בעולמות להחיותם מאין ליש כמלאכים שנק' אברי' דשכינתא<sup data-n=\"7990\">86</sup> [כ]עיני ה' מלאכי' דבריאה",[["7975","71","<b>מל' שבעליון נעשה כתר לתחתון</b>: נסמן לעיל קסג, ב הערה 84."],["7976","72","<b>דאצי'</b>: א: דא\"ס."],["7977","73","<b>דמל'</b>: א: ליתא. ו: הנ\"ל."],["7978","75","<b>דבי\"ע. . ג\"פ הבו</b>: ראה פע\"ח (שער השבת) שי\"ח, פ\"ב. פ\"ו. פ\"ח. מאמרי אדה\"א בראשית ע' מו. וש\"נ."],["7979","74","<b>דבי\"ע. . דמודו\"מ</b>: נסמן לעיל קמד, ב."],["7980","76","<b>[ה]השתלשלו'. . ציור אדם נפש בגוף</b>: ראה מו\"נ ח\"א פע\"ב. <a class=\"ft-cite\" href=\"#/read/tanya/3401310056\" data-slug=\"tanya\" data-id=\"3401310056\">תניא</a> רפנ\"א. מאמרים שנסמנו בהערה 1. לעיל פ' וארא נז, ד. וש\"נ."],["7981","77","<b>מה הנשמה ממלא</b>: ראה ברכות י, א. מאמרי אדה\"א הנחות תקע\"ז ע' לה. וש\"נ."],["7982","78","<b>נשמת כ\"ח</b>: שחרית לשבת. ראה גם לקמן פ' תצוה שיט, ד."],["7983","79","<b>וזעג\"ז</b>: וזה על גב זה. בו: וזע\"ז."],["7984","80","<b>שאין לו גוף</b>: ע\"ד פיוט יגדל. רמב\"ם פיה\"מ סנהדרין פ\"י היסוד הג'."],["7985","81","<b>כי לא ראיתם כל תמונה</b>: ואתחנן ד, טו."],["7986","82","<b>עיני ה'</b>: עקב יא, יב."],["7987","83","<b>אזני ה'</b>: בהעלותך יא, א. יח."],["7988","84","<b>וישב ה'</b>: תהלים כט, י. ו: ליתא. אב: כבפנים."],["7989","85","<b>הנה ה' עומד</b>: יחזקאל ג, כג [ושם: והנה שם כבוד ה' עומד]. ראה שה\"א עה, א הערה 7."],["7990","86","<b>כמלאכים שנק' אברי' דשכינתא</b>: ראה פרדס (שער ההיכלות) שכ\"ד, פי\"א."]]],[2300540284,"שנק' מארי דאשגחותא<sup data-n=\"7991\">87</sup> כו' וכן יש מארי דאודנין<sup data-n=\"7992\">88</sup> כו' וכמ\"ש היוצר עין<sup data-n=\"7993\">89</sup> כו' כמ\"ש במ\"א בענין ההשגחה פרטי'<sup data-n=\"7994\">90</sup> וא\"כ הרי לפ\"ז המשל ודוגמא הולך האור האלקי בירידות המדרגו' מעליון לתחתון ע\"ד הנ\"ל, והיינו כמו באדם שראשית גילוי <span data-k=\"pg\">466</span> ּ האור וחיות הנפש בגוף הוא בכלי המוח דחו\"ב, כך למעלה ראשית גילוי האור האלקי במוחי' דחו\"ב דמל' בג\"ע דבריאה דאימא מקננא<sup data-n=\"7995\">91</sup> כו' ויורד ומשתלשל ממוחי' למדות בלב וכן לבחי' חיצוניות האברי' דשכינה יורד השפע כמו מראש עד הרגל כך יורד [כ]דמיון אברי אדם במלאכי' דבי\"ע עד בחי' רגל בעולם העשי' שא' הארץ הדום רגלי<sup data-n=\"7996\">92</sup> ונק' רגלי השכינה<sup data-n=\"7997\">93</sup> כידוע, וכל העולמות כולם מקושרים ואחוזי' זע\"ז יחד בהתכללו' אברי' דנפש אדם יחד בפעולתו וכל תנועה הכל כא' עפ\"י רצון ה' בחכ' ומדות ומודומ\"ע שבא בהתלבשות בג' עולמות דבי\"ע כמו כל אשר חפץ ה'<sup data-n=\"7998\">94</sup> כו' ומסדר הכו\"מ כרצונו דוקא כנ\"ל וד\"ל.\n<b>והנה</b> עדיין יש להבין למה נק' התהוות הבריאה מן הבורא ית' בשם חידוש גמור שנק' מאין ליש כידוע, דלכאורה לפי כל הנ\"ל בב' המשלים בענין ההשתל' דעו\"ע בין בבחי' אותיות שבעליון לתחתון ובין בדוגמא דחיות [הנפש] בגוף בירידות המדרגות מראש לסוף הכל אין כל חדש בזה [כלל] מאחר שמבחי' מהות ועצמות העילה העליון נמשך לעלול כשלשלת כו', א\"כ זהו שנק' יש מיש שאין בו חידוש מעיקרו ולא יש מאין רק מה שהי' תחלה במשפיע יצא לגילוי מן ההעלם בלבד כו' עד מקורם הראשון שהוא בחי' מל' דאצי' שנק' עילת כל העילות<sup data-n=\"7999\">95</sup> (או כח כל הכחות כמ\"ש ורב כח<sup data-n=\"8000\">96</sup> דהיינו שמאמתת המצאו<sup data-n=\"8001\">97</sup> נמצאו כל הנבראי'<sup data-n=\"8002\">98</sup> בכח הפב\"נ כנ\"ל וכמ\"ש כי ממך הכל<sup data-n=\"8003\">99</sup> כו') ול[מ]ה או' המחדש בטובו<sup data-n=\"8004\">100</sup> כו' (וגם המשכת הרצון וחכ' ומדות עד מודו\"מ בעולמות דבי\"ע אין זה חדש מעיקרו רק שיצא מן ההעלם לגילוי לבד כידוע). אך הענין הוא כידוע דבתחלת ההשתל' הי' ע\"י בחי'<sup data-n=\"8005\">101</sup> צמצום אור העצמו' שצמצם א\"ע והאיר רק דרך מסך שנק' הארה דהארה לבד וכמא' כברייתו ש\"ע<sup data-n=\"8006\">102</sup> ברישא חשוכא והדר נהורא וכמ\"ש ישת חשך סתרו<sup data-n=\"8007\">103</sup> וכן מגלה עמוקות מני חשך<sup data-n=\"8008\">104</sup> כו' שהוא בחי' העלם דאור העצמו', וכך הוא בענין ב' משלים הנ\"ל שיורד האור מעילה לעלול הרי אין העלול מקבל מעצמו' דעילה אלא רק מהארה דהארה שלו והוא",[["7991","87","<b>מארי דאשגחותא</b>: נסמן לעיל נ, א."],["7992","88","<b>מארי דאודנין</b>: ראה זהר ויקהל רב, א. ת\"ז ת\"ל (עה, א). ת\"מ (פ, א). ת\"ע (קלא, א). <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316490133\" data-slug=\"or-hatorah-hb\" data-id=\"8316490133\">אוה\"ת וירא כרך ד ע' תשלו</a> ואילך."],["7993","89","<b>היוצר עין</b>: תהלים צד, ט [ושם: אם יוצר — ראה לקמן פ' יתרו רסה, א. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670066\" data-slug=\"torat-chaim\" data-id=\"2300670066\">תו\"ח וירא צז, ג</a> הערה 26]."],["7994","90","<b>בענין ההשגחה פרטי'</b>: ראה תו\"ח שם ובהערה 25. אוה\"ת שם."],["7995","91","<b>דאימא מקננא</b>: נסמן לעיל פ' שמות ה, ד."],["7996","92","<b>הארץ הדום רגלי</b>: נסמן לעיל קסב, ב."],["7997","93","<b>רגלי השכינה</b>: ברכות מג, ב. ת\"ז ת\"ע (קלא, א). ראה מאמרי אדה\"א שמות כאן (ע' קט). וש\"נ."],["7998","94","<b>כל אשר חפץ ה'</b>: תהלים קלה, ו."],["7999","95","<b>עילת כל העילות</b>: ראה הנסמן לעיל פ' וארא עט, ג."],["8000","96","<b>ורב כח</b>: תהלים קמז, ה."],["8001","97","<b>שמאמתת המצאו</b>: ראה רמב\"ם ריש הל' יסוה\"ת."],["8002","98","<b>הנבראי'</b>: או: הנמצאים."],["8003","99","<b>כי ממך הכל</b>: דהי\"א כט, יד."],["8004","100","<b>המחדש בטובו</b>: ברכת יוצר."],["8005","101","<b>בחי'</b>: בו: ליתא."],["8006","102","<b>כברייתו ש\"ע</b>: שבת עז, ב (כגי' רש\"י)."],["8007","103","<b>ישת חשך סתרו</b>: תהלים יח, יב."],["8008","104","<b>מגלה עמוקות מני חשך</b>: איוב יב, כב."]]],[2300540312,"כמו גילוי האותיות דשכל שבא למדות בשינוי המהות להיות מקור למדות וכן מרצון לשכל (שזהו בחי' קרומא דאוירא<sup data-n=\"8009\">105</sup> המפסיק בין כתר לחכ' כידוע וכן מיצר הגרון<sup data-n=\"8010\">106</sup> בין שכל שבמוח למדות שבלב וכן חצר הכבד<sup data-n=\"8011\">107</sup> כו'). וכך גם [ב]כללות חיות הנפש בגוף בא בשינוי המהות שנק' הארה דהארה לבד והוא מה שמחיצוניות וגשמיות דרוחניות עצם הנפש הוא שנעשה מקור לחיות האברי' בהתלבשותו בדם הוא הנפש בחי[ות] גשמי (וכמו\"כ מגשמיות דכח הצומח<sup data-n=\"8012\">108</sup> הרוחני נעשה רוחניות הצמיחה בעשב כמ\"ש במ\"א), שזה א\"א להיות כ\"א ע\"י צמצום דוקא, וצמצום זה אע\"פ שהוא מבחי' הגבורות להעלים ולהסתיר העצמו' מ\"מ אדרבה זהו עיקר בחי' החסד והטוב, והוא שמצד טבע הטוב להטיב<sup data-n=\"8013\">109</sup> למקבלי' ע\"כ מצמצם ומשפיל א\"ע להמשיך השפע בשינוי המהות כפי ערך המקבלים כידוע. וכך הוא למעלה זהו ענין בחי' החסד וטוב האלקי שבעצמו' כי חפץ חסד הוא<sup data-n=\"8014\">110</sup> וטוב ה' וצדיק ע\"כ מצמצם א\"ע בבחי' ירידה גדולה כזו להיות מקור לעולמות להחיותם מאין ליש בבחי' הארה דהארה מריש כל דרגין שלפני האצי' עד סוף עולם העשי' בהתהוות דצח\"מ וד\"י הגשמי' כנ\"ל, וכמו שהנפש בעצמה למעלה הרבה מבחי' חיות גשמי דגוף ואברים <span data-k=\"pg\">רלג</span> ּ ועכ\"ז יורדת ומתצמצמת להתלבש בדם הוא הנפש הטבעיות שמחי' חיות גשמי לכל אבר כטבעו (ואמנם למעלה אע\"פ שנק' חי העולמים<sup data-n=\"8015\">111</sup> וכן או' צור חיינו<sup data-n=\"8016\">112</sup> כו' לחיי הנשמות הוא רק שם המושאל כמו שנק' כהפב\"נ שאין זה [כ]כח פועל האדם שיש לו יחוס וערך עם הפעולה כו', דא\"כ הרי יש שינוי בין קודם הבריאה לאח\"כ וגם יש התפעלות כו', וגם הי' ראוי שיהי' גם הפעולה בלתי גבול ככח הפועל האלקי כו' וכידוע קושי' הפלוסופי'<sup data-n=\"8017\">113</sup> בכל זה. אך באמת אין שינוי ולא התפעלות כמו אם צדקת<sup data-n=\"8018\">114</sup> כו' כי אין השפע האלקי' באה רק דרך צמצום כנ\"ל וז\"ש חי ולא בחיים<sup data-n=\"8019\">115</sup> וד\"ל). וזהו המחדש בטובו דוקא שלפי כל הנ\"ל הרי יש כאן חידוש גמור מאין ליש ממש ולא יש מיש אחר שאין השפע באה ממהות ועצמות אלקות רק בחי' זיו והארה דהארה כו', וגם זה הנה בא רק ע\"י מדת טובו ית' כמו שמטבע הטוב להטיב כנ\"ל שעי\"ז מצמצם א\"ע כו', וע\"כ או' המחדש בטובו דוקא מע\"ב בכ\"י כמו שמטבע הטוב להחיות רוח שפלים<sup data-n=\"8020\">116</sup> כך כל התחדשות הבריאה בתמידות מעולם היותר עליון עד עולם היותר תחתון בדרך ריבוי ההשתלשלו' דעו\"ע [כ]נ\"ל שהוא ע\"י ריבוי הצמצומי' דוקא כנ\"ל זהו הכל רק מצד",[["8009","105","<b>קרומא דאוירא</b>: ראה זהר (אד\"ר) נשא קכח, ב. מאמרי אדה\"א בראשית ע' ח. וש\"נ."],["8010","106","<b>מיצר הגרון</b>: ראה מאמרי אדה\"א ויקרא ח\"א ע' פג. וש\"נ. נ\"ך ס\"ע לז ואילך. וש\"נ."],["8011","107","<b>חצר הכבד</b>: ראה מאמרי אדה\"ז תקס\"ב ח\"א ע' רמה. ח\"ב ע' תקטז. אמ\"ב (שער הק\"ש) טו, ד. מאמרי אדה\"א בראשית ע' קיג ואילך."],["8012","108","<b>מגשמיות דכח הצומח</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670098\" data-slug=\"torat-chaim\" data-id=\"2300670098\">תו\"ח וירא צח, א</a> ואילך. ובהערה 4 שם. לקמן פ' תרומה שיג, ג."],["8013","109","<b>טבע הטוב להטיב</b>: נסמן לעיל פ' שמות לד, ג."],["8014","110","<b>כי חפץ חסד הוא</b>: מיכה ז, יח."],["8015","111","<b>חי העולמים</b>: ראה תויו\"ט סוף תמיד."],["8016","112","<b>צור חיינו</b>: נוסח תפלת מודים."],["8017","113","<b>קושי' הפלוסופי'</b>: ראה גם מאמרי אדה\"א דברים ח\"ב ע' תרל. וש\"נ. דרושי חתונה ח\"א ע' קצב. וש\"נ."],["8018","114","<b>אם צדקת</b>: איוב לה, ז."],["8019","115","<b>חי ולא בחיים</b>: ראה לקמן פ' תצוה שכו, ד בפייט. מו\"נ ח\"א פנ\"ז. הנסמן במאמרי אדה\"א דברים ח\"ד ע' א'תקד."],["8020","116","<b>להחיות רוח שפלים</b>: ישעי' נז, טו."]]],[2300540337,"טובו וחסדו העצמי כמ\"ש טוב ה' לכל<sup data-n=\"8021\">117</sup> וכתיב אמרו לצדיק כי טוב<sup data-n=\"8022\">118</sup> כו' וד\"ל.\n<b>ומעתה</b> הנה יש להבין מה שייכות יש לזה שא' המחדש בטובו כו' למ\"ש בסמוך [לו] אדון הנפלאות דמשמע דמפני שהוא אדון הנפלאות ע\"כ הוא מחדש בטובו כו'. אך יש להקדים תחלה ביאור ענין [בחי'] סוכ\"ע שלמעלה מבחי' ממכ\"ע כנ\"ל שהוא שם הוי' שלמעלה משם אלקים כנ\"ל והוא הנק' אדון הנפלאות ולזה הטעם הוא מחדש בטובו כו' כי הא בהא תליא דוקא כמ\"ש כי ה' הוא האלקי'<sup data-n=\"8023\">119</sup> כו'. וביאור הדברים הנה ידוע בפי' שם הוי' שהוא הי' הוה ויהי'<sup data-n=\"8024\">120</sup> כא' שזהו להיותו למעלה מבחי' זמן דעבר הוה ועתיד, כי הזמן בא בבחי' השתלשלו' בבחי' ממכ\"ע הנ\"ל שהוא בחי' המל' מ‘לך מ לך ימלוך כו' שזהו בחי' עש\"נ<sup data-n=\"8025\">121</sup> כנ\"ל במשל האותיות ומשל חיות הנפש בגוף שיש בזה בחי' זמן לפי שהאור מצומצם בכלי כו' בבחי' או\"פ ואינו רק מבחי' הארה דהארה מעצמו' אלקו' שבא בשינוי המהות כנ\"ל, והיינו ו\"א שני דהוי עלמא<sup data-n=\"8026\">122</sup> מריש כל דרגין כו' שהן ו' יומי' דאצי' שמקבלי' מחו\"ב ורצה\"ע שיורדי' למטה בבי\"ע שהוא ע\"י צמצום דשם אלקים בכלל כי\"מ דמע\"ב כידוע, אבל בחי' שם הוי' הוא בבחי' מדות וחו\"ב דאצי' עצמן שלמעלה מבחי' צמצום דשם אלקי' שמובדל ומרומם לגמרי מבחי' ההשתלשלו' דזמן ומקום בג' מדרגות דעש\"נ הנ\"ל, וע\"כ כל בחי' [ה]השתלשלו' דבחי' ממלא כ\"ע הנ\"ל כלא ממש חשיב לגבי' וכערך הצמצום דהאר' חיות הנפש בגוף לגבי עצמו' חיות הנפש קודם שתתפשט בדם הוא הנפש דכלא חשיבא ממש וז\"ש כי עמך מקור חיים<sup data-n=\"8027\">123</sup> כו' ונק' חיי החיים<sup data-n=\"8028\">124</sup> (וכערך צמצום אותיות הדבור לגבי עצמו' הנפש שנק' רוח ממללא<sup data-n=\"8029\">125</sup> כו'). וז\"ש בזהר ע\"פ אלקי' אל דמי לך<sup data-n=\"8030\">126</sup> כו' דשם אלקי' שבבחי' ממכ\"ע שנק' נה\"ת קארי תדיר לנהורא עילא' <span data-k=\"pg\">468</span> ּ שהוא שם הוי' בחי' סוכ\"ע כידוע, ועכ\"ז הרי נק' בשם סובב כ\"ע עכ\"פ שזהו בחי' מקיף וסובב לכל ההשתלשלו' דבחי' ממכ\"ע הנ\"ל ונק' חיי החיים וכמ\"ש כי הוי' הוא האלקי' שמשם הוי' נמשך בבחי' מקיף עכ\"פ לשם אלקי' וכולא חד. והענין הוא כמו עד\"מ עיגול השמים שמקיף וסובב לארץ [ו]משפיע מרוחניות לגשמיות בכל חלקי הארץ בהעלם וכמו העלם עצמות הנפש שממנה מתצמצם ומתלבש בחיות הגוף שהכל א' כידוע וד\"ל, וכמו העיגול המקיף מכל צד בשוה למעלה ו[ל]מטה וכמו\"כ חיות העצמו' דנפש מאיר בהעלם במוח",[["8021","117","<b>טוב ה' לכל</b>: תהלים קמה, ט."],["8022","118","<b>אמרו לצדיק כי טוב</b>: ישעי' ג, י [ושם: צדיק — ראה לקמן קע, ב. קעב, ד. מאמרי אדה\"א בראשית ע' רצא. וש\"נ. שמות ח\"ב ע' תקנו]."],["8023","119","<b>כי ה' הוא האלקי'</b>: ואתחנן ד, לה. לט."],["8024","120","<b>הוי'. . הוה ויהי'</b>: נסמן לעיל פ' וארא מט, ד."],["8025","121","<b>עש\"נ</b>: עולם שנה נפש — נסמן לעיל פ' וארא נג, ב."],["8026","122","<b>ו\"א שני דהוי עלמא</b>: ר\"ה לא, א. ראה הנסמן במאמרי אדה\"א בראשית ע' נג."],["8027","123","<b>כי עמך מקור חיים</b>: תהלים לו, י."],["8028","124","<b>חיי החיים</b>: ראה יומא עא, א."],["8029","125","<b>רוח ממללא</b>: ת\"א לבראשית ב, ז."],["8030","126","<b>אלקי' אל דמי לך</b>: נסמן לעיל פ' וארא מט, ג."]]],[2300540360,"שבראש כמו בצפורן הרגל בהשוואה א' ממש מאחר שמקיף לראש ורגל כא', והוא מצד שמרומם ומושלל מכל בחי' גילוי אור החיות הבא בבחי' או\"פ בכלי ששם יש חילוקי מדרגות בין עליון לתחתון אבל בחי' עצמו' החיות הרוחני שבנפש אין בהארתה הפרש בין החכ' שבראש לחיות הרגל (וכמו בחי' ההרגשה שאדם מרגיש א\"ע מראש לרגל בבת א'<sup data-n=\"8031\">127</sup> שזהו הארה אחת פשוטה שלמעלה מחיות המורכב באברי' ממוח שבראש כו' כמ\"ש במ\"א) וכמו בחי' הרצון השולט בכל האברים בשוה<sup data-n=\"8032\">128</sup> כמשי\"ת<sup data-n=\"8033\">129</sup> ).\n<b>וכך</b> יובן למעלה בבחי' סוכ\"ע הכללי שהוא הנק' מחשבה אחת הכללי' שצופה ומביט<sup data-n=\"8034\">130</sup> עד סוף כל הדורות בסקירה אחת שזהו שם הוי' שכולל עבר הוה ועתיד כא' כנ\"ל הרי נק' בשם מקיף וסובב עכ\"פ להיותו בבחי' כלל אל הפרט עכ\"פ, ואמנם שוה ומשוה עליון ותחתון כמ\"ש וגם חשך<sup data-n=\"8035\">131</sup> כו' קמי' כחשיכה כאורה<sup data-n=\"8036\">132</sup> דהיינו שאין הפרש בין האור היותר עליון כמו בגעה\"ע דבריאה שמאיר שם מחו\"ב דמל' דאצי' עד סוף ותחתית העוה\"ז למטה שנק' חשך גמור כמו בשאול וכה\"ג כמ\"ש בשמים ממעל ועל הארץ כו' אין עוד<sup data-n=\"8037\">133</sup> בשוה וכתיב אם אסק שמים<sup data-n=\"8038\">134</sup> שם אתה [ו]אציע[ה] שאול הנך וכמו שא' יונה מבטן שאול שועתי<sup data-n=\"8039\">135</sup> כו' דגם גקה\"ט [לגמרי] כבלעם הי' בו גילוי אור הנבואה כמ\"ש מחזה שדי יחזה<sup data-n=\"8040\">136</sup> כו' וכתי' ויאמר ה' אל בלעם<sup data-n=\"8041\">137</sup> כו', וע\"כ ביקש משה שלא תשרה שכינה באוה\"ע<sup data-n=\"8042\">138</sup> כמ\"ש ונפלינו אני ועמך<sup data-n=\"8043\">139</sup> כו', וז\"ש השמים והארץ אני מלא<sup data-n=\"8044\">140</sup> בהשוואה א' ממש להיותו למעלה מבחי' מעלה ומטה שאין זה רק בבחי' גילוי אור וחיות המתפשט למטה בעולמות שיתכן בו לומר חילוק מדרגות בין רוחניות לגשמיות כנ\"ל (ובאמת מאחר שמבואר למעלה דגם בשם אלקים דבחי' ממלא אין האור וחיות האלקי בא ונמשך רק מבחי' הארה דהארה ע\"י צמצום בשינוי המהות ולא מעצמו' אור המל' כנ\"ל א\"כ גם בבחי' המל' יש בחי' סובב ומקיף לכל ההשתלשלו' כא' ממש והוא בחי' כתר מל' שלמעלה מהתלבשות בעולמות כידוע, וז\"ש כי הוי' הוא האלקי' כולא חד ממש) וזהו שאו' הקדוש בשמים ובארץ<sup data-n=\"8045\">141</sup> בשוה כו', ועכ\"ז הארת אור המקיף דסוכ\"ע מאיר תמיד בממכ\"ע (וכמו הרצון הבלתי מורכב בשכל ומדות וחיות האברים ששולט בראש ורגל בשוה וז\"ש כל אשר חפץ ה' עשה כו').",[["8031","127","<b><a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670361\" data-slug=\"torat-chaim\" data-id=\"2300670361\">שאדם מרגיש א</a><a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670238\" data-slug=\"torat-chaim\" data-id=\"2300670238\">\"ע. . בבת א</a>'</b>: ראה גם לעיל פ' שמות מה, ב. לקמן קעח, ג. קפז, ג. פ' תצוה שמ, ב. תו\"ח נח סט, ב. וירא ק, ב. שה\"א לה, ב. מאמרי אדה\"א שמות ח\"א ע' רמד."],["8032","128","<b>הרצון. . בשוה</b>: ראה לעיל פ' בא פט, ג הערה 143."],["8033","129","<b>כמשי\"ת)</b>: א: כמשי\"ת. ואוצ\"ל: (כמשי\"ת)."],["8034","130","<b>מחשבה אחת הכללי' שצופה ומביט</b>: ראה ר\"ה יח, א. ברכת זכרונות. הנסמן במאמרי אדה\"א הנחות תקע\"ז ע' צ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680084\" data-slug=\"torat-chaim\" data-id=\"2300680084\">תו\"ח ויגש רל, ד</a>. לקמן פ' משפטים רצט, ג."],["8035","131","<b>וגם חשך</b>: נסמן לעיל סד, א."],["8036","132","<b>קמי' כחשיכה כאורה</b>: נסמן לעיל פ' שמות ל, ד הערה 179."],["8037","133","<b>בשמים. . אין עוד</b>: ואתחנן ד, לט."],["8038","134","<b>אם אסק שמים</b>: תהלים קלט, ח."],["8039","135","<b>מבטן שאול שועתי</b>: יונה ב, ג."],["8040","136","<b>מחזה שדי יחזה</b>: בלק כד, ד."],["8041","137","<b>ויאמר ה' אל בלעם</b>: בלק כב, יב."],["8042","138","<b>ביקש משה. . באוה\"ע</b>: נסמן לעיל פ' שמות לא, א."],["8043","139","<b>ונפלינו אני ועמך</b>: תשא לג, טז."],["8044","140","<b>השמים והארץ אני מלא</b>: ירמי' כג, כד. ראה גם מאמרי אדה\"א דברים ח\"א ע' קפב. וש\"נ. שע\"ת יד, ג ובהערה 20. לקמן פ' תצוה שמ, ג. ויקהל שפח, ג."],["8045","141","<b>הקדוש </b>[א: והקדוש]<b> בשמים ובארץ</b>: ראה ברכת ישתבח. מאמרי אדה\"א שמות ח\"ב ע' תכב. דברים ח\"א ע' קפג ובהנסמן בהנ\"ל."]]],[2300540381,"<b>ואמנם</b> הארה זו שמבחי' מקיף דסובב בממלא נק' בשם פלא כידוע דאל\"ף אותיות פל\"א<sup data-n=\"8046\">142</sup> בהיפוך אותיות דהיינו כאשר בא הרצון בשכל ומדות נק' אולפנא דחכ' שמאין תמצא כרצון וחכ' דמע\"ב שבא בצרופי' די\"מ כו', אבל בחי' פל\"א הוא בחי' ההסתר וההעלם דבחי' מקיף וסובב דמח' א' הנ\"ל שבלתי בא בגילוי באו\"פ בהשתלשלו' העולמות כנ\"ל, ואמנם כאשר מאיר ממנו בצירופי אותיות דמל' דאצי' <span data-k=\"pg\">רלד</span> ּ בבי\"ע אז נק' נפלאות כמו הניסים שנק' נפלאות ל' נפעל שמקבל מבחי' פלא העליון הנ\"ל, דגם שבכל מע\"ב בסדר הצרופי' די\"מ מאיר ג\"כ מבחי' שם הוי' דסובב בממלא כנ\"ל, אך כאשר מאיר מבחי' ההעלם דעצמו' אוא\"ס שבמקיף דשם הוי' דאצי' בשם אלקי' הוא ענין הניסים שנק' נפלאות שמהפך סדר הצירופי' ששרשם בח\"ע שבמל' (דהיינו מבחי' הרצון הבלתי מורכב בחכ' ומדות כו') כמו נס דקי\"ס בהיפוך ים ליבשה כו' (וכמשי\"ת) וכרחב\"ד שא' מי שא' לשמן וידליק<sup data-n=\"8047\">143</sup> כו' וכה\"ג שבהכרח יבא אור זה מלמעלה מסדר ההשתל' דצירופי אותיות דמל' (וכי' מכות דמצרים דכתי' כימי צאתך<sup data-n=\"8048\">144</sup> מאמ\"צ אראנ\"ו נפלאו\"ת שהוא משם הוי' דוקא כמ\"ש וידעו מצרים<sup data-n=\"8049\">145</sup> כי אני הוי' כו'). וזהו שנק' נפלאות לשון רבים שיש בזה ריבוי חילוקי מדרגות הנמשך מעצמות אור המקיף דסובב בממלא ומקור[ם] הכללי נק' אדו\"ן הנפלאו\"ת וכמו [ל]עושה נפלאות גדולות לבדו<sup data-n=\"8050\">146</sup> כו' (והיינו<sup data-n=\"8051\">147</sup> בחי' פל\"א הוא שם העצם דבחי' עצמו' אור המקיף דשם הוי' דאצי' שממנו נמשך כל הנפלאו\"ת למטה בעלמא דאתגלייא בצירופי אותיות דמל' דאצי' בבי\"ע והוא הנק' אדון <sup data-n=\"8052\">148</sup>כל הנפלאו\"ת כו' וד\"ל (ויש בזה ב' מדרגות א' בבחי' ממכ\"ע עצמו שהוא בחי' כתר מל' דאצי' שבוקע המסך שבין אצי' לבריא\"ה שיאיר האור דאצי' להדיא שלא ע\"י צמצום שנק' הארה דהארה כו' שמזה נעשה הניסים שנק' נפלאות בהיפוך צירופי אותיות די\"מ כו' להפך הטבע וכה\"ג כמו מי שא' כו', והוא בחי' הרצון המורכב כבר בחכ' ומדות דמע\"ב שיהופך מדין לחסד בבקשת יהי רצון כו' וכן בש\"ע כמו בא\"י רופא חולים<sup data-n=\"8053\">149</sup> וכה\"ג ונק' ג\"כ אדו\"ן הנפלאו\"ת שנק' פל\"א כנ\"ל. והב' בחי' האצי' עצמו והוא בחי' כתר דאצי' עצמו שלמעלה מחו\"ב ומדות דאצי' שבו גילוי אור העצמו' דא\"ס בפנימי' דשם הוי' דאצי' כמו גילוי שכינה בהיכל ק\"ק כר\"י כה\"ג שראה<sup data-n=\"8054\">150</sup> כו' וא' יהי רצון מלפניך ממש שיכבשו רחמיך את כעסך (וכמו [ל]שנות מדין לחסד באצי' עצמו או להחליף אור החסד בכלי הגבורה כמ\"ש במ\"א<sup data-n=\"8055\">151</sup> ) וזה נק' נפלאו\"ת גדולות",[["8046","142","<b>דאל\"ף אותיות פל\"א</b>: נסמן לעיל פ' וארא עח, ב."],["8047","143","<b>מי שא' לשמן וידליק</b>: נסמן לעיל פ' שמות כ, א."],["8048","144","<b>כימי צאתך</b>: מיכה ז, טו."],["8049","145","<b>וידעו מצרים</b>: בשלח יד, ד. יח."],["8050","146","<b>[ל]עושה נפלאות גדולות לבדו</b>: תהלים קלו, ד. ראה גם לקמן פ' ויקהל שפח, א."],["8051","147","<b>(והיינו</b>: או: והיינו."],["8052","148","<b>כל</b>: א: ליתא."],["8053","149","<b>בש\"ע. . רופא חולים</b>: כ\"ה גם בהכת\"י."],["8054","150","<b>כר\"י כה\"ג שראה</b>: ברכות ז, א. וראה גם לעיל פ' בא צז, סע\"ג ואילך. וש\"נ."],["8055","151","<b>כמ\"ש במ\"א</b>: ראה גם מאמרי אדה\"ז תקס\"ח ח\"א ע' מד. שעה\"י קטז, א ובהערה 4."]]],[2300540401,"שעושה לבדו כו') (או כמו שא' שהקב\"ה מתפלל<sup data-n=\"8056\">152</sup> מאי מצלי יה\"ר מלפני שיגולו רחמי על בני כו') וכגילוי הנבואה משם הוי' דאצי' בנביאי' וכן בגילוי אור דשם הוי' בתו\"מ (כמשי\"ת). וזהו ענין הסמיכות דמחדש בטובו מע\"ב למה שקדם שהוא אדו\"ן הנפלאו\"ת דהא בהא תליא דוקא משום דחידוש מע\"ב בטובו היינו בבחי' רב חסד וטוב שברצה\"פ הקדום שהוא בחי' סוכ\"ע הכלל[י ש]באצי' ומאצי' לבי\"ע שנק' פל\"א [ד]כת\"ר עליון שממנו נמשך כל בחי' הנפלאות לשנות הרצון וחכ' דמע\"ב בהשגחה הפרטי' שבכל יום בכל העולמות כמ\"ש משמים הביט הוי'<sup data-n=\"8057\">153</sup> כו' להשפיל ולהרים וכן לחדש אור וחיות חדש מאין ליש בכל יום ויום ע\"י צמצום כי גם בחי' הצמצום הנ\"ל נעשה ע\"י בחי' טובו וחסדו כנ\"ל, וע\"כ א' אדון הנפלאות המחדש בטובו דהא בהא תליא דמפני שהוא אדו\"ן הנפלאו\"ת [מ]בחי' פל\"א העליון הנ\"ל ע\"כ מחדש בטובו כו' וד\"ל.\n<b>ומעתה</b> יש להבין ענין נורא תהלות שהזכיר קודם אדון הנפלאות ומה שייכות יש לזה <span data-k=\"pg\">470</span> ּ עם זה כו', להיות מבואר למעלה בענין אדון הנפלאות שהוא בחי' פלא דהיינו בחי' כתר עליון (בין באצי' בין בבריאה כנ\"ל) שזהו בחי' המקיף הסובב לכל ההשתל' ד[בחי'] ממלא שבבחי' או\"פ כו' כמו הכלל אל הפרט שזהו בחי' מח' א' הכללי' כנ\"ל, והנה כתיב נורא תהלות עושה פלא דגם בחי' פלא העליון הוא נעשה בבחי' עשי' ממש מעצמות אור א\"ס שבפנימי' הכתר שזהו שנק' נורא תהלות כו'. והענין הוא לפי שגם שלגבי ההשתל' דבחי' ממלא הנ\"ל נק' בחי' מקיף וסובב בהעלם למעלה ולמטה בשוה ממש כנ\"ל ונק' פלא שהוא מופלא ומוסתר מן כל ההשתלשלו' ונק' קדוש הוי' כידוע עכ\"ז גם הוא בא בבחי' מדה וגבול כמו היקף החומה שמוגבלת במדה ושיעור להקיף העיר אם קטנה או גדולה כו', וכן הוא הגבלת הכלל לפ\"ע הפרט דוקא כמו השכל כללי הכולל כל הצירופי אותיות הדבור המוגבלים וכן הרצון השולט בכל האברים בשוה שמוגבל גם הוא לפ\"ע הגבלת כלי הגוף כו', ואע\"פ שנק' פלא או קדוש שמובדל בערך זהו לגבי המקבלים ממנו בלבד, אבל לגבי עצמו' אוא\"ס שבפנימי' הכתר גם הוא אינו אלא בבחי' גבול ומדה שיתכן לומר בו בחי' עשי' כמ\"ש עושה פלא שעושה לבחי' פלא העליון הנק' מקיף הכללי כמו שעושה לשמים הגשמיי' דכתיב נוטה שמים כיריעה<sup data-n=\"8058\">154</sup> כו' (וכך הוא בענין הנפלאות כניסים בפועל ממש שנמשך מבחי' פלא העליון שנק' אדון כל הנפלאות נק' בבחי' עשי' ממש כמ\"ש לעושה נפלאות כו' והוא מ\"ש עושה פלא כפשוטו), וזהו נורא תהלות עושה פלא שמבחי' נורא תהלות הוא שעושה לבחי' פלא העליון כנ\"ל.",[["8056","152","<b>שהקב\"ה מתפלל</b>: ראה ברכות שם."],["8057","153","<b>משמים הביט הוי'</b>: תהלים לג, יג."],["8058","154","<b>נוטה שמים כיריעה</b>: תהלים קד, ב."]]],[2300540421,"<b>והענין</b> הוא להיות כי תיבת פלא שמורה על ענין ההפלאה והבדלה בערך שזהו בחי' פלא שהוא ההסתר וההעלם מן השכל (כמו שכל מופלא<sup data-n=\"8059\">155</sup> שנק' שכל הנעלם מכ\"ר<sup data-n=\"8060\">156</sup> וכה\"ג) כמו כי יפלא ממך דבר<sup data-n=\"8061\">157</sup> כו', אינו שייך רק בדבר המושג קצתו ואפס מעט מזעיר ממנו עכ\"פ רק שא\"א להשיג לאמיתי' עצמותו ומהותו שנפלא [ונעלם] מן ההשגה כמו סתרי תורה<sup data-n=\"8062\">158</sup> ורזי' דאוריי'<sup data-n=\"8063\">159</sup> שנק' פלאו' חכ'<sup data-n=\"8064\">160</sup> שאפס קצהו מושג, אך עומק סוד החכ' נעלם מכל חכם שלא יוכל לידע לאמתתו כלל וכמו אמרתי אחכמה<sup data-n=\"8065\">161</sup> כו' בסוד דמצות פרה אדומה דגם שנק' נסתרות מ\"מ לפרקי' יוכלו גם הם לבוא בגילוי אור ההשגה לנשמות, כמו בגעה\"ע בכל שבת וחדש שיבא כ\"ב להשתחוות כו' שזהו עליות הנשמות<sup data-n=\"8066\">162</sup> בעילוי אחר עילוי לבא להשגות עמקו' הח\"ע דתורה שנק' נסתרות וכמו סוד ה' ליריאיו גם לנשמות בגופי' בעוה\"ז<sup data-n=\"8067\">163</sup> כמו רשב\"י וחביריו וכה\"ג, וכמו\"כ למעלה מזה בנשמות הנביאים כמשה ואהרן ושמואל שנגלה עליהם מבחי' פנימי' דשם הוי' דח\"ע דאצי' כו' (וגם הנסים שנק' נפלאות בפו\"מ הרי בא בגילוי אור בכלי בגשמיות כמו שא' הרואה מקום שנעשה בו הנס<sup data-n=\"8068\">164</sup> כו'). אבל למעלה מבחי' פלא העליון הוא שנק' נורא תהלות שהוא בחי' עצמו' אוא\"ס שבפנימי' כ\"ע שעליו א' לית מח' תפיסא בך כלל<sup data-n=\"8069\">165</sup> וכלל ונק' סדכ\"ס<sup data-n=\"8070\">166</sup> דהיינו שאינו בא בגילוי אור אפי' אפס קצהו, דאפי' אור צח ומצוחצח<sup data-n=\"8071\">167</sup> אוכם הוא לגבי עה\"ע עצמו כו' שזהו גם מחה\"ק דאור הכתר הנק' פלא ונק' אור צח ומצוחצח כו', דאור א\"ס עצמו למעלה מכל הע\"ס דאצי' שמובדל ומרומם לגמרי וגם מבחי' הכתר שהוא בחי' הרצון <span data-k=\"pg\">רלה</span> ּ ותענוג שלמעלה מן החכ' דהיינו מ\"ש לית מח' שנק' רצון ומח' כללי תפיסא בי' כלל וכלל שלא יתכן לומר בו גם לשון פלא (ונק' בחי' רדל\"א דלא ידע לי'<sup data-n=\"8072\">169</sup> בר איהו בלחודוי כמ\"ש במ\"א ומבואר בפי' ב\"ש בסידור<sup data-n=\"8073\">168</sup> ) והוא שנק' נורא תהלות, כי ענין התהלה לא שייך רק בבחי' ההשגה לאפס קצהו עכ\"פ שגם שאינו משיג לאמיתתו יוכל לבא לבחי' ההלל והודאה כענין [ה]הפלאה והבדלה בערך איך שהוא קדוש ומובדל ומופלא כו', כמו בע\"ס דחו\"ב ומדות דאצי' שיהללו לשם הוי' דאצי' בבחי' הפלאה והבדלה בערך עכ\"פ כמו לך ה' הגדולה<sup data-n=\"8074\">170</sup> כו' וכמו ענין חכים ולא בחכ' ידיעא<sup data-n=\"8075\">171</sup> כו' וכה\"ג, לפי שבא אור החכ' דאצי' מן ההעלם דח\"ע העצמי' מן ההעלם לגילוי אפס קצהו עכ\"פ יוכל להלל לרוממות דח\"ע שנק' חכים ולא כו' וכן במדות דחג\"ת איך שמופלא ומרומם מן המדות דאצי' כמ\"ש לך ה' הגדולה כו' וכה\"ג, אבל בבחי' מהו\"ע דאוא\"ס שבפנימיות אור הכתר שנק' סדכ\"ס דלמת\"ב כלל נק' נורא תהלות שלא יושג גם אפס קצהו לבא בבחי' תהלה ושבח בחו\"ב ומדות כלל כמ\"ש ולאו מכא\"מ",[["8059","155","<b>שכל מופלא</b>: נסמן לעיל לג, א."],["8060","156","<b>שכל הנעלם מכ\"ר</b>: נסמן לעיל פ' שמות מז, ג."],["8061","157","<b>כי יפלא ממך דבר</b>: פ' שופטים יז, ח."],["8062","158","<b>סתרי תורה</b>: פסחים קיט, א. חגיגה יג, א."],["8063","159","<b>ורזי' דאוריי'</b>: זהר יתרו עח, א. צב, א. צג, סע\"ב. פקודי רלז, ב. ועוד."],["8064","160","<b>פלאו' חכ'</b>: נסמן לעיל כא, ב."],["8065","161","<b>אמרתי אחכמה</b>: קהלת ז, כג."],["8066","162","<b>שבת וחדש. . עליות הנשמות</b>: ישעי' סו, כג. נסמן לעיל פ' שמות לה, ב."],["8067","163","<b>סוד ה' ליריאיו. . בעוה\"ז</b>: תהלים כה, יד. ראה גם סוטה ד, ב. לקמן פקודי תנד, א."],["8068","164","<b>הרואה מקום שנעשה בו הנס</b>: ראה ברכות נד, א."],["8069","165","<b>לית מח' תפיסא בך כלל</b>: ת\"ז בהקדמה (יז, א). וראה גם בסמוך בפנים. לקמן קעא, סע\"ג ואילך. קעט, ד."],["8070","166","<b>סדכ\"ס</b>: ראה זהר בהקדמה (ב, א). ועוד."],["8071","167","<b>אור צח ומצוחצח</b>: נסמן לעיל יב, ב."],["8072","169","<b>דלא ידע לי'</b>: ראה זהר ויקהל רי, ב. (אד\"ר) נשא קכט, ב. קמ, ב. (אד\"ז) האזינו רפח, א."],["8073","168","<b>רדל\"א. . ב\"ש בסידור</b>: שחרית לט, ג ואילך."],["8074","170","<b>לך ה' הגדולה</b>: דהי\"א כט, יא."],["8075","171","<b>חכים ולא בחכ' ידיעא</b>: ז\"ח יתרו לד, ד. ת\"ז בהקדמה (יז, ב)."]]],[2300540441,"כלל<sup data-n=\"8076\">172</sup> וכמ\"ש לו דומיה תהלה<sup data-n=\"8077\">173</sup> כו' לפי שמובדל ומרומם למעלה גם מהיות גם ממקור לע\"ס דאצי' כו' וד\"ל. והטעם שנק' נורא תהלות לפי שא\"א לבא ולהגיע לאמתת אור העצמות בבחי' השגה ותפיסא כנ\"ל ע\"כ נק' נורא שנמשך ממנו התפשטות היראה<sup data-n=\"8078\">174</sup> שלמעלה מן הטעם ודעת רק בבחי' ביטול עצמי ופשוט לגמרי מכל וכל, כמו שידוע בענין בחי' השוב שאחר הרצוא שהוא בחי' ביטול המציאות לגמרי מפני היראה כשבא מקרוב כמו בעליות הנשמות בג\"ע שטרם עלותם לפני ה' ממש עולי' בהתפעלות אהבה ותשוקה ע\"פ השגה וטעם כי אין דביקות וקירוב באה רק ע\"י ההשגה וטעם וכמו לאהבה את ה' אלקיך כי הוא חייך<sup data-n=\"8079\">175</sup> וכה\"ג דהיינו בבחי' השגה ותפיסא עכ\"פ כי הוא חייך בבחי' ממלא שנק' מקור החיים או בבחי' מקיף וסובב שנק' חיי החיים (שמושג אפס קצהו רק שהוא בהפלא' כנ\"ל), אבל כשמגיעי' הנשמות לפני ה' ממש בבחי' האצי' עצמו שם מתבטלים ממציאותם לגמרי ונסוגים אחור בבחי' שוב בביטול שלמעלה מן ההשגה כי אין להם שום השגה ותפיסא בעצמו' א\"ס שבאצי' כנ\"ל וד\"ל (ומ\"ש וקדושים בכ\"י יהללוך סלה כו' בלי הפסק<sup data-n=\"8080\">176</sup> היינו שכל שעולים יותר בעילוי למעלה לא יגיעו לאמתת מהו\"ע ית' ע\"כ יהללו[ך] סלה בלי הפסק כמ\"ש במ\"א בענין משובח ומפואר עדי עד<sup data-n=\"8081\">177</sup> כו').\n<b>(ושרש</b> הענין הוא לפי שידוע דאוא\"ס למעלה עד אין קץ<sup data-n=\"8082\">178</sup> כו' והוא מצד בחי' הרוממות בעצמו' עד אין שיעור למעלה כו' והוא מבחי' הגבורות שהוא בחי' ההסתלקו' והעילוי בעצמותו היפך הירידה והתפשטו' כו', וע\"כ נק' בשם נורא תהלות שהוא בחי' מל' דא\"ס שנק' שמו הגדול<sup data-n=\"8083\">179</sup> שלמעלה מן ההשתל' דקו\"ח כמו שאו' ושמך נורא<sup data-n=\"8084\">180</sup> כו' שאין תהלה ושבח מגיע לשם כלל להיותו מרומם ונשגב שמו לבדו בבחי' העילוי בעצמו' ממש כמאמר שהי' הוא ושמו בלבד<sup data-n=\"8085\">181</sup>. וזהו שאו' הגדול הגבור והנורא<sup data-n=\"8086\">182</sup>, דב' מדות דגדול וגבור הוא <span data-k=\"pg\">472</span> ּ בחי' החו\"ג דעצמו' אוא\"ס<sup data-n=\"8087\">*183</sup> דמה שהוא למעלה עד אין שיעור בבחי' גבורות והסתלקות בעצמו' (ששם א' שמים לא זכו בעיניו<sup data-n=\"8088\">183</sup> כו' כמ\"ש במ\"א) ומה שהוא בבחי' הירידה והמשכה למטה בקו\"ח עד סוף העשי' שהוא בחי' החסד דעצמו' א\"ס שמתפשט למטה עד אין תכלית כידוע. ואמנם בחי' הממוצע שהוא בחי' הת\"ת זהו ענין והנורא, כידוע דבחי' נורא זהו [ב]בחי' הגילוי מן ההעלם",[["8076","172","<b>ולאו מכא\"מ כלל</b>: ראה ת\"ז שם."],["8077","173","<b>לו דומיה תהלה</b>: תהלים סה, ב [ושם: לך, וכ\"ה בו — ראה גם לעיל פ' וארא סא, ב. לקמן פ' פקודי תנז, א]."],["8078","174","<b>נורא שנמשך ממנו התפשטות היראה</b>: ראה גם מאמרי אדה\"א דברים ח\"ד ע' א'תה. וש\"נ."],["8079","175","<b>לאהבה. . כי הוא חייך</b>: נצבים ל, כ [בדילוג]."],["8080","176","<b>וקדושים. . בלי הפסק</b>: ברכת אתה קדוש. ערובין נד, א."],["8081","177","<b>משובח ומפואר עדי עד</b>: ראה לעיל פ' שמות ד, ג ואילך."],["8082","178","<b>דאוא\"ס. . אין קץ</b>: נסמן לעיל פ' שמות ד, ד."],["8083","179","<b>מל' דא\"ס שנק' שמו הגדול</b>: נסמן לעיל פ' שמות ה, ג."],["8084","180","<b>ושמך נורא</b>: תפלת העמידה לימים נוראים."],["8085","181","<b>שהי' הוא ושמו בלבד</b>: נסמן לעיל פ' וארא נג, ב."],["8086","182","<b>הגדול הגבור והנורא</b>: נסמן לעיל קנה, א."],["8087","*183","<b>החו\"ג דעצמו' אוא\"ס</b>: נסמן לעיל פ' בא צ, ב."],["8088","183","<b>שמים לא זכו בעיניו</b>: איוב טו טו [ושם: ושמים]. ראה לקמן רכה, ב. עט\"ר (שער ר\"ה) ע' יא. מאמרי אדה\"א דברים ח\"ד ע' א'רנב."]]],[2300540461,"דרוממות העצמות עכ\"פ שיתכן לומר בזה ענין היראה [עד] שנק' נורא, משא\"כ כשהוא בבחי' הסתלקות ועילוי בעצמות ממש בהעלם אחר העלם שנק' סדכ\"ס כנ\"ל גם נורא לא שייך לקרותו, וזהו בחי' ממוצע דחו\"ג שבעצמו' והוא ענין וי\"ו דוהנורא<sup data-n=\"8089\">184</sup> כמ\"ש במ\"א והוא שכלול בקו\"ח שהוא ציור וי\"ו<sup data-n=\"8090\">185</sup> מחו\"ג שבעצמו'. וזהו ג\"כ כללות ענין הפסוק דמי כמוך באלים הוי' שזהו בחי' הת\"ת<sup data-n=\"8091\">186</sup> דוקא כידוע דאל ואלקי' הן בבחי' חו\"ג<sup data-n=\"8092\">187</sup>, וז\"ש מי כמוך באלים הוי' בחי' הת\"ת שהוא קו האמצעי<sup data-n=\"8093\">188</sup> שעולה עד פנימי' הכתר<sup data-n=\"8094\">189</sup> דוקא שנק' בריח התיכון שמבריח לקצה<sup data-n=\"8095\">190</sup> העליון כו', והיינו מ\"ש נאדר בקדש<sup data-n=\"8096\">191</sup> דחכ' הנק' קדש מלה בגרמי'<sup data-n=\"8097\">193</sup> כידוע ולהיותו למעלה גם מבחי' מקור החכ' שנק' ח\"ס כנ\"ל נק' נאדר בקדש<sup data-n=\"8098\">192</sup> והוא מ\"ש נורא תהלות עושה פלא שעושה לבחי' פלא העליון דכתר כנ\"ל, וזהו נורא תהלות אדון הנפלאות שמבחי' נורא תהלות<sup data-n=\"8099\">194</sup> דוקא נמשך [בחי' פלא העליון הנ\"ל שנק' אדון הנפלאות כנ\"ל וד\"ל. ואע\"פ שלכאו' זהו כמו] דבר והיפוכו דמאחר שנק' נורא תהלות שנק' סדכ\"ס דלמת\"ב כלל איך עושה לפלא הנ\"ל שהוא הבא בגילוי למטה מן ההעלם לפרקים עכ\"פ כנ\"ל, הענין הוא מטעם שבחי' נורא זה הוא בחי' הממוצע דחו\"ג שבעצמו' אוא\"ס כנ\"ל ע\"כ יוכל להסתעף ממנו דבר והיפוכו דהיינו שמבחי' הרוממו' והעלם דעצמו' שנק' סדכ\"ס יבא לגילוי להיות עושה פלא הנ\"ל וד\"ל).\n<b>ובזה</b> יובן סדר המשך הדברים בנוסח זה שאו' בסיום [ד]ברכת יוצר כי הוא לבדו מרום וקדוש היינו בבחי' הקדושה העצמי' שבבחי' רוממות והעלם העצמות בעילוי אחר עילוי עד אין שיעור כנ\"ל שזהו שנק' מרום וקדוש לבדו כו', ואח\"כ פועל גבורות שבחי' גבורות הללו הוא שפועל לבוא מבחי' ההעלם לגילוי למטה ע\"י בחי' ממוצע הנ\"ל שהוא בחי' הת\"ת (כענין וי\"ו דוהנורא שהוא בבחי' הקו\"ח שכלול מצמצום והתפשטות יחד כידוע), והוא בבחי' גבו' שבחסד להיות מאיר מלמעלה מבחי' הצמצום וההעלם דעצמו' שיהי' מזה בחי'<sup data-n=\"8100\">195</sup> תוס' אור בחסד שברצון הקדום שעלה ברצונו להאציל ולברוא כו'. וזהו אחר שפועל גבורות עושה חדשות לחדש הרצון וחכ' ומדות דמע\"ב בתוס' מרובה על העיקר כו' (וכענין המבואר במ\"א בברכה דאתה גבור<sup data-n=\"8101\">196</sup> לעולם כו' שהוא בבחי' גבו' שבחסד דוקא ע\"כ מזכיר בה מזונות ורפואה ותח\"ה כו'). וזהו בעל מלחמות",[["8089","184","<b>וי\"ו דוהנורא</b>: ראה גם לעיל קנה, א."],["8090","185","<b>בקו\"ח שהוא ציור וי\"ו</b>: ראה גם לעיל קנה, ב. וש\"נ."],["8091","186","<b>דמי כמוכה. . הת\"ת</b>: נסמן לעיל קנה, ב הערה 234."],["8092","187","<b>דאל ואלקי'. . חו\"ג</b>: ראה לעיל פ' וארא סא, ד. וש\"נ."],["8093","188","<b>הת\"ת שהוא קו האמצעי</b>: ראה השמטות לזח\"א רנז, א."],["8094","189","<b>הת\"ת. . שעולה. . הכתר</b>: ראה שערי אורה לר\"י גיקטלייא שער ה (סג, ב)."],["8095","190","<b>הת\"ת. . בריח התיכון שמבריח לקצה</b>: ע\"פ תרומה כו, כח. ויקהל לו, לג. ראה זהר בלק קפו, ב ובהגהת הרח\"ו שם."],["8096","191","<b>נאדר בקדש</b>: המשך הכתוב מי כמוכה."],["8097","193","<b>דחכ' הנק' קדש מלה בגרמי'</b>: זהר אמור צד, ב."],["8098","192","<b>דחכ'. . בקדש</b>: א: ליתא. וכנראה נשמט מפני תיבות הדומות: נאדר בקדש. . נאדר בקדש."],["8099","194","<b>עושה. . תהלות</b>: א: ליתא. וכנראה נשמט מפני תיבות הדומות: תהלות. . תהלות."],["8100","195","<b>בחי'</b>: ו: ליתא."],["8101","196","<b>בברכה דאתה גבור</b>: תפילת העמידה. ראה גם מאמרי אדה\"א במדבר ח\"ב ס\"ע תרמח. דברים ח\"ד ע' א'תכח ואילך. ש\"א כו, ב. לקמן ריב, ג. וראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1301410173\" data-slug=\"likkutei-sichot\" data-id=\"1301410173\">לקו\"ש תולדות כרך ל ע' 108</a>. וש\"נ."]]],[2300540480,"לאגברא ימינא על שמאלא<sup data-n=\"8102\">197</sup> כמו ימין ה' עושה חיל<sup data-n=\"8103\">198</sup> כו' כמו יהי רצון כו' [שיכבשו רחמיך כו'], וכמא' בים נדמה כבחור<sup data-n=\"8104\">199</sup> עושה מלחמה וכן במ\"ת כזקן<sup data-n=\"8105\">200</sup> במלחמתה של תורה כו' לעמוד לנגד מדה\"ד כו', וכן זורע צדקות מצמיח ישועות הכל מבחי' גבו' שבחסד דוקא כידוע במ\"ש הוש[יעה] לו ימינו<sup data-n=\"8106\">201</sup> כו'. וזהו ג\"כ <span data-k=\"pg\">רלו</span> ּ בורא רפואות שהרפואה ג\"כ בבחי' גבו' שבחסד להמתיק כח הדין בחסד כמו כי הוא יך וירפאנו<sup data-n=\"8107\">202</sup> כו' שאין רפואה בלא מכה שהוא מדה\"ד הקשה ונמתק בחסד שזהו בחי' גבו' שבחסד כמו כי גבר עלינו חסדו<sup data-n=\"8108\">203</sup> כו' וכידוע שהרפואה הוא בבחי' הת\"ת, ואח\"כ סמך לזה מ\"ש נורא תהלות דהיינו בחי' מרום וקדוש שהזכיר בתחלה שממנו נמשך להיות אדון הנפלאות בגילוי ההעלם שהן הניסים שמאיר מבחי' ההעלם דסובב בממלא וגם לפלא עצמו הרי עושה פלא כו' וכ\"ז כדי להיות מחדש בטובו בחידוש גמור מעצמות הא\"ס ממש כנ\"ל וד\"ל, וכל זה נכלל במה שמסיים ביוצר המאורות שהן שמש וירח שהוא שם הוי' ואלקים<sup data-n=\"8109\">204</sup> שיהי' תוס' [אור] בשם הוי' לבקוע הצמצום והמסך דאותיות דו\"מ<sup data-n=\"8110\">205</sup> שבשם אלקים והוא בחי' היצי' שהוא בחי' הגילוי מן ההעלם דוקא כמ\"ש יוצר אור כו' וד\"ל).\n<b>והנה</b> הגם שבבחי' נורא תהלות הנ\"ל שהוא בחי' עצמות אוא\"ס ממש שנק' סדכ\"ס דלמחת\"ב כלל א\"א להשיגו בדביקו' ואה\"ר להיותו למעלה מבחי' סובב וממלא דהוי' ואלקים כנ\"ל ולמעלה גם מבחי' פלא העליון הנ\"ל כמ\"ש עושה פלא כו', אבל ע\"י עסק התו\"מ תוכל הנשמה האלקי' לבוא לידי דביקות בבחי' אמיתת מהו\"ע דאוא\"ס ממש (שלמעלה גם מחיי העוה\"ב שנהנין מעצמו' התענוג הפשוט שנק' שעשועי המלך בעצמו<sup data-n=\"8111\">206</sup> כו'), והטעם הוא כי גם שא' דאוריי' מח\"ע נפקת<sup data-n=\"8112\">207</sup> דהיינו שגם היא ירדה בהשתלשלו' באבי\"ע בחכ' ומדות דאצי' ומאצי' לבי\"ע עד התורה הנגלית לנו כו', מ\"מ שרשה הראשון הוא במהו\"ע חכמתו ית' כמו שהוא באמיתת פנימי' אור העצמו' ממש כמ\"ש בתורה ואהי' אצלו אמון שעשועי'<sup data-n=\"8113\">208</sup> כו', אצלו ממש טרם שעלה ברצונו הפשוט להאציל כו', ואע\"פ דלמת\"ב כלל היינו בחי' מח' ורצון הקדום שלפני ההשתל' דקו\"ח לצורך ההשפעה לעולמות בבחי' סובב וממלא כו', אבל תוה\"ק קדמה לעולם<sup data-n=\"8114\">209</sup> ונק' משל הקדמוני<sup data-n=\"8115\">210</sup> כידוע הרי היתה כלולה באמתת מהו\"ע ית', וכן במצות שהן בחי' פנימי' ועצמו' רצונו שלמעלה הרבה מן הרצון",[["8102","197","<b>לאגברא ימינא על שמאלא</b>: נסמן לקמן הערה 875."],["8103","198","<b>ימין ה' עושה חיל</b>: תהלים קיח, טז."],["8104","199","<b>בים נדמה כבחור</b>: ראה מכילתא בשלח טו, ג. יתרו כ, ב [ורש\"י שם]. להלן קסט, סע\"ב ואילך. שה\"א עה, ב ובהערה 20."],["8105","200","<b>במ\"ת כזקן</b>: נסמן בהערה שלפנ\"ז."],["8106","201","<b>הוש[יעה] לו ימינו</b>: תהלים צח, א."],["8107","202","<b>כי הוא יך וירפאנו</b>: הושע ו, א [ושם: כי הוא טרף וירפאנו יך ויחבשנו — אבל כ\"ה בכ\"מ ומהם: שעה\"י קכה, ב. מאמרי אדה\"א שמות ח\"ב ע' תקסט. וש\"נ]."],["8108","203","<b>כי גבר עלינו חסדו</b>: תהלים קיז, ב."],["8109","204","<b>שמש וירח. . הוי' ואלקים</b>: ראה גם מאמרי אדה\"ז על פרשיות התורה ח\"א ע' מח. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680270\" data-slug=\"torat-chaim\" data-id=\"2300680270\">תו\"ח ויחי רמו, ד</a>."],["8110","205","<b>דו\"מ</b>: או: די\"מ די' מאמרות."],["8111","206","<b>שעשועי המלך בעצמו</b>: נסמן לעיל פ' בא צב, ד."],["8112","207","<b>דאוריי' מח\"ע נפקת</b>: נסמן לעיל פ' שמות יא, א."],["8113","208","<b>ואהי' אצלו אמון שעשועי'</b>: משלי ח, ל [בדילוג]."],["8114","209","<b>תוה\"ק קדמה לעולם</b>: ראה פסחים נד, א. עמה\"מ (שער שעשועי המלך) ש\"א, פ\"ד (ג, א)."],["8115","210","<b>משל הקדמוני</b>: נסמן לעיל פ' שמות ח, ב."]]],[2300540498,"ותענוג להשתלשלו' העולמות וכמ\"ש לכל תכלה<sup data-n=\"8116\">211</sup> כו' רחבה מצותך מאד בלי גבול<sup data-n=\"8117\">212</sup> דעצמו' א\"ס ממש, וע\"כ בעשות האדם המצוה בפו\"מ בעוה\"ז, וכן כשעוסק בתורה הנגלית לנו נדבקה נשמתו באמתת מהו\"ע ית' כמו שהוא קודם כל ההשתל' שהי' הוא ושמו בלבד, וזהו קרוב ה' כו' אשר יקראוהו באמת דתו\"מ<sup data-n=\"8118\">213</sup> כו'. וזהו עיקר ענין בריאת האדם שנברא' הנשמה מאין ליש ובאה וירדה למטה בעוה\"ז בגוף חומרי לקיים התו\"מ בפו\"מ דאע\"פ שזהו בחי' ירידה גדולה כנ\"ל, אבל ירידה זו לצורך עלי' הוא כדי להעלות הנשמה במדרגה גבוה יותר משרשה והוא להדבק במהו\"ע אוא\"ס ב\"ה שלמעלה גם מבחי' פלא הנ\"ל, שזהו למעלה הרבה מאוי\"ר בדביקות אמיתי' שהי' לנשמה בשרשה במל' דאצי' בעמדה לפני ה' כו' שזה אינו רק בבחי' ממלא וסובב שנק' פלא שמתגלה לפרקי' בג\"ע לנשמות כנ\"ל, אבל באמתת עצמו' אוא\"ס שבפנימי' הכתר למחת\"ב כלל וכשמגיעי' הנשמות שם משתחוי' בביטול המציאו' ונסוגי' אחור (כמו וירא העם וינועו כנ\"ל) בבחי' שוב. אך ע\"י עסק התו\"מ בעוה\"ז הרי תדבק הנשמה במהו' חכמתו ורצונו העצמי ממש בכל דבר ה' זו הלכה<sup data-n=\"8119\">214</sup> ומקרא כמ\"ש ואשים דברי בפיך<sup data-n=\"8120\">215</sup> כו' כמ\"ש ז\"ל דהקורא<sup data-n=\"8121\">216</sup> <span data-k=\"pg\">474</span> ּ בתורה קורא בשמותיו<sup data-n=\"8122\">217</sup> ממש כו', וע\"כ גזרו אומר דיפה שעה א'<sup data-n=\"8123\">218</sup> בתשו' ומע\"ט בעוה\"ז מכל חיי העוה\"ב, דגם שחיי העוה\"ב נמשך מבחי' התענוג הפשוט שלמעלה מחכ' ורצון דמע\"ב ונק' עדן (שנק' שעשועי המלך כו', אבל שעשועי' שבתורה יותר עצמיי'<sup data-n=\"8124\">219</sup> כו') מ\"מ המצוה עצמה גבוה יותר כמא' דשכר מצוה מצוה<sup data-n=\"8125\">220</sup> עצמה וכידוע דהעוה\"ב נברא ביו\"ד<sup data-n=\"8126\">221</sup> לבד וכמו שאנו או' אין זולתך מלכינו<sup data-n=\"8127\">222</sup> לחיי העוה\"ב כו' (וזהו שארז\"ל דת\"ח אין להם מנוחה אפי' בעוה\"ב שנא' ילכו מחיל<sup data-n=\"8128\">223</sup> כו' לפי שעולי' ע\"י לבוש דאור דתורה למעלה מחיי העוה\"ב באמתת מהו\"ע ית' ממש שאין לו שיעור למעלה כו' למעלה הרבה מבחי' העדן דעוה\"ב כמ\"ש במ\"א). וראי' ממ\"ת ש[ב]תחלה ראו וינועו ויעמדו מרחוק ואח\"כ קיבלו התורה פב\"פ ולא נתבטלו ממציאותם כי נדבקו נשמתם ע\"י אור פנימי' די' הדברות במהו\"ע ית', ואע\"פ שעכ\"ד פרחה נשמתן<sup data-n=\"8129\">224</sup> כו' הרי בחי' טל דתורה החי' אותם<sup data-n=\"8130\">225</sup> כידוע, וגם עכשיו שדבריו חיים וקיימים בעסק התורה יחי' האדם במעלה ומדרגה גבוה הרבה יותר מדביקות הנשמה באה\"ר בתענוגי' במס\"נ בק\"ש ותפלה מטעם הנ\"ל וד\"ל.",[["8116","211","<b>לכל תכלה</b>: תהלים קיט, צו."],["8117","212","<b>מאד בלי גבול</b>: נסמן לעיל פ' וארא סא, ב."],["8118","213","<b>קרוב. . באמת דתו\"מ</b>: תהלים קמה, יח. ראה גם לעיל פ' שמות יא, ג ובהערה 513."],["8119","214","<b>דבר ה' זו הלכה</b>: עמוס ח, יב. שבת קלח, ב."],["8120","215","<b>ואשים דברי בפיך</b>: ישעי' נא, טז."],["8121","216","<b>כמ\"ש ז\"ל דהקורא</b>: ו: כמשארז\"ל כל הקורא."],["8122","217","<b>כל הקורא בתורה קורא בשמותיו</b>: נסמן לעיל פ' שמות ז, ד."],["8123","218","<b>דיפה שעה א'</b>: נסמן לעיל פ' שמות ט, א."],["8124","219","<b>שעשועי' שבתורה יותר עצמיי'</b>: ראה <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680248\" data-slug=\"torat-chaim\" data-id=\"2300680248\">תו\"ח תולדות קנב, ד</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680459\" data-slug=\"torat-chaim\" data-id=\"2300680459\">מקץ רכח סע\"א</a>."],["8125","220","<b>דשכר מצוה מצוה</b>: נסמן לעיל פ' שמות ז, ב."],["8126","221","<b>דהעוה\"ב נברא ביו\"ד</b>: מנחות כט, ב."],["8127","222","<b>אין זולתך מלכינו</b>: ראה גם לעיל פ' שמות ה, ג."],["8128","223","<b>דת\"ח. . ילכו מחיל</b>: תהלים פד, ח. ברכות בסופה. ראה מאמרי אדה\"א שמות ח\"א ס\"ע רז ואילך."],["8129","224","<b>שעכ\"ד פרחה נשמתן</b>: נסמן לעיל פ' וארא סט, א."],["8130","225","<b>טל דתורה החי' אותם</b>: ראה שבת פח, ב ע\"פ תניא ספל\"ו."]]],[2300540516,"<b>ובכל</b> הנ\"ל יובן שרש ענין קי\"ס שהי' הכנה למ\"ת<sup data-n=\"8131\">226</sup> דוקא כידוע, דהנה כתי' הפך ים ליבשה<sup data-n=\"8132\">227</sup> כו' שם נשמחה בו ממש כו' הרי הי' שמחה זו דכנ\"י במהו\"ע ית' ממש שלמעלה מן ההשתל' דבחי' סובב וממלא כו', וכמו\"כ הי' במ\"ת מלמעלה למטה בשמחה עליונה דהקב\"ה בכנ\"י דכתיב ביום חתונתו<sup data-n=\"8133\">228</sup> וביום שמחת לבו כו' כידוע. והענין הוא כי ידוע בכללות ענין קי\"ס שגבוה מכל הניסים ונפלאות שהי' במצרים שזהו מצד שהאיר אז מבחי' מהו\"ע ית' ממש שלמעלה מסובב וממלא כנ\"ל שנק' אדון הנפלאות ועושה פלא כו'. דהנה ידוע שכל מה שיש ביבשה<sup data-n=\"8134\">229</sup> יש בים כו' [ו]למעלה זהו בחי' עלמא דאתכסיי' ועלמא דאתגלייא<sup data-n=\"8135\">230</sup> בחי' ההעלם וגילוי דמח' ודבור שהוא בחי' סובב וממלא בכלל כמ\"ש יקוו המים כו' ותראה היבשה<sup data-n=\"8136\">231</sup>, ואז א' תוצא הארץ כו' שיצאו כל הברואי' מן הארץ מאין ליש, כך הוא למעלה בארץ עילאה שיצא ממנה כל התהוות העולמות<sup data-n=\"8137\">233</sup> הרוחניי' מאין ליש כמלאכים<sup data-n=\"8138\">232</sup> עליונים שנק' בשם בהמות וחיות<sup data-n=\"8139\">234</sup> כמו פני ארי' ושור<sup data-n=\"8140\">235</sup> כו' כמ\"ש בזהר והוא בחי' ממכ\"ע בכלל שנק' כח הפב\"נ כנ\"ל (והיינו י\"מ שבדיבור העליון שא' תוצא הארץ כו' וכה\"ג כידוע), ובחי' ים העליון שנק' דא\"ס<sup data-n=\"8141\">236</sup> הוא בחי' ההעלם דבחי' סוכ\"ע בכלל שזהו כמו הברואי' שבים למטה והוא בחי' המח' שה[י]א בהעלם ומקפת לגילוי אותיות הדבור כידוע. והנה מאחר שא' הפך ים ליבשה למטה הרי ממילא נעשה כך עד\"ז עד רום המעלות בכלל דהיינו שנהפך בחי' ים העליון ליבשה שזהו שנהפך בחי' ההעלם דסובב הכללי ונעשה בבחי' גילוי דיבשה בבחי' ממלא כו', והוא שנעשה מעלדא\"ת עלד\"א<sup data-n=\"8142\">237</sup> כמו שהי' גילוי ההעלם דמח' עצמה להיות בבחי' דיבור והיינו שנעשה מבחי' המקיף [עצמו] פנימי (כמ\"ש יעקב והי' הוי' לי לאלקים<sup data-n=\"8143\">238</sup> כו' כמ\"ש במ\"א), וא\"כ הרי בחי' ההעלם והגילוי דים ויבשה שהוא סובב וממלא נעשי' בהשווא' א' ממש, שמזה מוכרח לומר עכ\"פ שהי' אז מאיר ההארה מבחי' עצמו' אוא\"ס שבפנימי' הכתר שלמעלה הרבה מבחי' סובב <span data-k=\"pg\">רלז</span> ּ וממלא דהוי' ואלקים כנ\"ל שלמעלה גם מבחי' פלא כנ\"ל שלפניו שוין ממש ההעלם והגילוי ע\"כ בהגלות נגלות אור העצמו' דא\"ס נעשה מן ההעלם גילוי כמ\"ש הים ראה וינוס<sup data-n=\"8144\">239</sup> כו', לפי שאין בחי' העלם וגילוי שייך רק בבחי' ההשפעה למקבלי' שבהכרח צ\"ל בבחי' מקיף ופנימי שהוא העלם וגילוי דסובב וממלא כנ\"ל, אבל כמו שהוא ית' במהו\"ע שהוא ושמו בלבד כנ\"ל הרי בחי' המקיף ופנימי שוין ממש ע\"כ נהפך לפניו מים ליבשה כו', וזהו הפך ים ליבשה כו' שם נשמחה בו ממש כמ\"ש במ\"א באריכות. וזהו כללות ענין קי\"ס שהי' הכנה למ\"ת",[["8131","226","<b>קי\"ס שהי' הכנה למ\"ת</b>: נסמן לעיל קמח, ג."],["8132","227","<b>הפך ים ליבשה</b>: תהלים סו, ו."],["8133","228","<b>במ\"ת. . ביום חתונתו</b>: נסמן לעיל פ' בא קיח, ב."],["8134","229","<b>שכל מה שיש ביבשה</b>: נסמן לעיל פ' שמות יח, ג."],["8135","230","<b>ביבשה יש בים. . עלמא דאתכסיי' ועלמא דאתגלייא</b>: נסמן לעיל קלח, ג."],["8136","231","<b>יקוו. . היבשה</b>: בראשית א, ט."],["8137","233","<b>העולמות</b>: ו: ליתא."],["8138","232","<b>תוצא הארץ. . כמלאכים</b>: בראשית א, כד. ראה גם תו\"ח ח\"ש קל, ג ובהערה 32. שה\"א לג, א. מאמרי אדה\"א הנחות תקע\"ז ע' צח."],["8139","234","<b>כמלאכים. . בהמות וחיות</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310044\" data-slug=\"tanya\" data-id=\"3401310044\">תניא רפל\"ט</a>. מאמרי אדה\"א ויקרא ח\"א ע' ט. וש\"נ."],["8140","235","<b>פני ארי' ושור</b>: יחזקאל א, י."],["8141","236","<b>דא\"ס</b>: או: עלמא דאתכסייא."],["8142","237","<b>מעלדא\"ת עלד\"א</b>: או: מעלמא דאתכסייא עלמא דאתגלייא."],["8143","238","<b>והי' הוי' לי לאלקים</b>: ראה לעיל פ' שמות מח, ג. וש\"נ."],["8144","239","<b>הים ראה וינוס</b>: תהלים קיד, ג."]]],[2300540534,"שיהי' התגלות אור פנימי' ועצמו' דרצונו וחכמתו בי[ו\"ד] הדברות בכללות דתו\"מ מלמעלה למטה ואם לא הי' קי\"ס קודם לא היו בנ\"י כלי [בית] קיבול לקבל מבחי' פנימי' ועצמו' דאור דתו\"מ פב\"פ ממש כו' וד\"ל.\n<b>וזהו</b> אשירה לה' כי גאה גאה<sup data-n=\"8145\">240</sup>, פי' גאה גאה כי הנה בחי' הגיאות [האלקית] העליונ[ה] הוא בחי' [ו]ענין ההתנשאות שמובדל ומרומם בערך מכל ההשתל' כמ\"ש ה' מלך גיאות לבש<sup data-n=\"8146\">241</sup> כו' (שהוא בחי' סוכ\"ע הכללי שהוא בחי' מל' דא\"ס שמקיף לכל ההשתל' דקו\"ח בכלל והוא בחי' מח' אחת הכללי' הנ\"ל) והיינו בחי' פלא העליון שמאיר למעלה ולמטה בשוה ממש וכמו שאו' המתנשא מימות עולם<sup data-n=\"8147\">242</sup> כידוע, אך גם בחי' גיאות והתנשאות זאת אינה רק על ימות עולם שהוא כללות ההשתל' דאבי\"ע כו' בבחי' סובב וממלא בכלל ובפרט כנ\"ל, אבל גאה גאה היינו בחי' הגיאות והתנשאו' שמצד אור העצמות דא\"ס ב\"ה ממש שגאה ומתנשא גם על גיאות הזאת, כידוע דגם בחי' גיאות והתנשאות זאת שמתנשא על ימות עולם אינו רק ע\"י בחי' לבוש וצמצום גדול להיות מלך על עם כו' וכמ\"ש ה' מלך גיאות לבש שאינו אלא בחי' לבוש חיצוני בלבד לגבי בחי' רוממות העצמות אוא\"ס ממש שהוא בחי' ההתנשאות הבאה מצד רוממות דעצמו' ממש שאין ערוך כלל ביניהם ונק' מלך מרומם לבדו<sup data-n=\"8148\">243</sup> ממש וכן נק' מלך הקדוש<sup data-n=\"8149\">244</sup> כמ\"ש במ\"א (והיינו בחי' טה\"ע שלמעלה הרבה מבחי' טה\"ת שמקיף לד' עולמות דאבי\"ע כו') והוא בחי' נורא תהלות הנ\"ל שעושה פלא ונק' אדון הנפלאות כו' כנ\"ל, ומשם האיר האור בקי\"ס לעשות מהעלם גילוי כנ\"ל וע\"כ א' אשירה לה' כי גאה גאה בחי' אור העצמו' דא\"ס שנק' סדכ\"ס דלמחת\"ב כלל כנ\"ל, והי' זה הכנה לפני מ\"ת כנ\"ל להורות להם הדרך והא[י]ר מעט מזעיר שמבחי' אור פנימי' ועצמו' דאור א\"ס ממש שהי' במ\"ת בהגלות נגלות אור פנימי' רצונו וחכמתו העצמי' שיוכלו כנ\"י לידבק נפשם במהו\"ע ית' ממש ע\"י בחי' אור דתו\"מ שבזה דוקא תדבק הנשמה בפנימי' ועצמו' דא\"ס ב\"ה ממש כנ\"ל, רק שבקי\"ס הי' זה בדרך העלא' מלמטה למעלה כמ\"ש אשירה לה' כו' ועי\"ז נגלה עליהם האור דעצמו' א\"ס במ\"ת מלמעלמ\"ט כנ\"ל וד\"ל.\n<b>וזהו</b> סוס ורוכבו רמה בים, דהנה כתי' לסוסתי ברכבי פרעה<sup data-n=\"8150\">245</sup> דמיתיך רעייתי כו' להיות ידוע בשרש פרעה שהוא בחי' עורף<sup data-n=\"8151\">246</sup> ואחוריי' דכתר דקדושה והוא בחי' גסות והתנשאות דקליפה כמו שא' לי יאורי ואני עשיתיני<sup data-n=\"8152\">247</sup> כו', וע\"כ א' מי הוי'",[["8145","240","<b>גאה גאה</b>: נסמן לעיל קמ, א."],["8146","241","<b>ה' מלך גאות לבש</b>: ראה גם לעיל פ' וארא עה, א. וש\"נ."],["8147","242","<b>המתנשא מימות עולם</b>: ע\"פ ברכת יוצר."],["8148","243","<b>מלך מרומם לבדו</b>: נסמן לעיל פ' בא צ, א."],["8149","244","<b>מלך הקדוש</b>: נסמן לעיל ק, ג הערה 181."],["8150","245","<b>לסוסתי ברכבי פרעה</b>: שה\"ש א, ט."],["8151","246","<b>פרעה. . עורף</b>: נסמן לעיל פ' שמות יט, ב."],["8152","247","<b>לי יאורי ואני עשיתיני</b>: יחזקאל כט, ג."]]],[2300540552,"אשר אשמע בקולו<sup data-n=\"8153\">248</sup> כו', וסוס ב\"פ גס<sup data-n=\"8154\">249</sup> היינו ב' מיני אותיות דמו\"ד בחי' העלם וגילוי כידוע דהאותיות נק' סוסים<sup data-n=\"8155\">250</sup>, וז\"ש לסוסתי ברכבי פרעה כו' וכמו מו\"ד<sup data-n=\"8156\">251</sup> זרות שברע דק\"נ <span data-k=\"pg\">476</span> ּ ששרשם בבינה דק\"נ שהן מ\"ט ש\"ט<sup data-n=\"8157\">252</sup> דמצרים לנגד בחי' העלם וגילוי דב' עולמו' דאתכסייא ואתגלייא דקדושה. וזהו סוס ורוכבו כי הסוס בחי' אותיות דמו\"ד נק' בחי' נוק' בחי' מקבל והרוכב על הסוס זהו בחי' דכר<sup data-n=\"8158\">253</sup> והוא בחי' הרצון והשכל שרוכב על האותיות ומנהיגם לכל אשר יחפוץ, ואמנם יש כח בסוס להוליך את הרוכב למרחוק ולגובה ההר שלא יכול הרוכב לילך שם מכח עצמו כלל כידוע, וכך הוא באותיות דמו\"ד שיש בכחם להוליך הרוכב עליהם שהוא הרצון ושכל החושב ומדבר להוליכם לעומק הרע בבחי' המקיף למרחוק וגם בגובה שלא יש בכח הרצון ושכל עצמו כלל (וכנראה בחוש בחושבי מחשבות לרע ומדברי' דברי נבלה שיש בכח צרופי אותיות המו\"ד להוליך הרצון ושכל שרוכב על המו\"ד לעמקו' הרע הגנוז ונעלם בנפשו שלא הי' בלבו מעולם וראי' מריבוי מ\"ז שבא מריבוי דב\"ט<sup data-n=\"8159\">254</sup> כמ\"ש במ\"א). אך הנה בקי\"ס הי' האור מאיר מבחי' גאה גאה שהוא למעלה מכל ההשתל' דהעלם וגילוי דסובב וממלא בקדושה האלקי' כנ\"ל עד שנהפך הים ליבשה ונעשה מ[ה]העלם גילוי כנ\"ל ע\"כ סוס ורוכבו דפרעה דק\"נ רמה בים, שהפי' רמה זה היינו ענין רוממות וענין השלכה<sup data-n=\"8160\">255</sup> למטה ושניהם אמת, דמפני שרדף פרעה בסוסיו ורוכבו בים בשעה שהאיר מעצמו' א\"ס שנק' גאה גאה שנק' גיאה על גיוותנייא<sup data-n=\"8161\">256</sup> כתרגומו אז השפיל גאים דק\"נ שהוא סוס ורוכבו בחי' דכר ונוק' דק\"נ, כי מאחר שההעלם נעשה גילוי להיותו למעלה מכל ההשתל' ע\"כ אין מקום שם ליניקות החיצוני' שמקבלי' מבחי' אחוריי' דכתר וחכ' ומדות כו'. וזהו רמה ל' השלכה למטה כמו צללו כעופרת<sup data-n=\"8162\">257</sup> כו', וגם ענין רוממו' דמצד בחי' רוממות האור שהאיר על פרעה ורכבו נתבטלו ממציאותם כמ\"ש כי גאה גאה כו' וכמו דכתיב וישקף ה' על מחנה מצרים<sup data-n=\"8163\">258</sup> כו' וזהו ה' איש מלחמה<sup data-n=\"8164\">259</sup> כו' מרכבות פרעה<sup data-n=\"8165\">260</sup> כו' ירה בים וד\"ל, והכל א' דמפני בחי' הרוממות הושלכו<sup data-n=\"8166\">261</sup> בים, ואמנם עיקר הרבותא הי' במה שסוס ורוכבו כו' שהקדים סוס לרוכב לפי שיש כח בסוס למעלה מן הרוכב כנ\"ל.\n<b>וזהו</b> לסוסתי ברכבי פרעה דמיתיך רעייתי כו' לפי שקי\"ס הי' הכנה למ\"ת כנ\"ל, ובמ\"ת כתיב כי תרכב על סוסיך<sup data-n=\"8167\">262</sup> כו'",[["8153","248","<b>מי הוי' אשר אשמע בקולו</b>: שמות ה, ב."],["8154","249","<b>וסוס ב\"פ גס</b>: נסמן לעיל קסא, ג."],["8155","250","<b>דהאותיות נק' סוסים</b>: ראה לעיל קסג, ב ובהערה 69."],["8156","251","<b>מו\"ד</b>: א: מחשבה ודיבור."],["8157","252","<b>ש\"ט</b>: ו: שערי טומאה."],["8158","253","<b>הסוס. . נוק'. . והרוכב. . דכר</b>: ראה גם שה\"א לו, ב ובהערה 10. שם עב, ב. ש\"א פו, א."],["8159","254","<b>מריבוי מ\"ז שבא מריבוי דב\"ט</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370453\" data-slug=\"torah-or\" data-id=\"3901370453\">תו\"א ויחי קב, סע\"ג</a> ואילך. מאמרי אדה\"א בראשית ע' תעח. דברים ח\"א ע' קפח. לעיל פ' בא קז, ג."],["8160","255","<b>רמה. . רוממות וענין השלכה</b>: ראה גם מאמרי אדה\"ז תקס\"ו ס\"ע קכג. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370284\" data-slug=\"torah-or\" data-id=\"3901370284\">תו\"א כאן (סג, סע\"ג</a>). מג\"א קכ, ב. מאמרי אדה\"א שמות כאן (ע' קלב)."],["8161","256","<b>גיאה על גיוותנייא</b>: לעיל קסא, ג: בת\"א [ושם: אתגאי]."],["8162","257","<b>צללו כעופרת</b>: בשלח טו, י."],["8163","258","<b>וישקף ה' על מחנה מצרים</b>: בשלח יד, כד [ושם: אל — אבל כ\"ה גם להלן קפא, ד — ראה לקמן קצג, ב. קצד, א]."],["8164","259","<b>ה' איש מלחמה</b>: שם טו, ג."],["8165","260","<b>מרכבות פרעה</b>: בשלח שם, ד."],["8166","261","<b>הושלכו</b>: א: ניתוסף: והושפלו. ו: הושפלו."],["8167","262","<b>ובמ\"ת. . כי תרכב על סוסיך</b>: חבקוק ג, ח. ראה גם לקמן קעט, ב. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370410\" data-slug=\"torah-or\" data-id=\"3901370410\">תו\"א מג\"א צ, א</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370433\" data-slug=\"torah-or\" data-id=\"3901370433\">צא, א</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370435\" data-slug=\"torah-or\" data-id=\"3901370435\">צו, ד</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370522\" data-slug=\"torah-or\" data-id=\"3901370522\">צז, ב</a>. קטז, ד. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381263\" data-slug=\"likkutei-torah\" data-id=\"4001381263\">לקו\"ת שה\"ש לג, ג</a>. מאמרי אדה\"ז על מארז\"ל ע' שצט [ושם: תרכוב]. ש\"א נד, א. וש\"נ."]]],[2300540569,"שבחי' המרכבה שירד ה' על ה\"ס זהו בחי' אותיות התורה שנק' סוסיך בב' מדריגות דמו\"ד במצות עיון ומצות קריאה<sup data-n=\"8168\">263</sup> בדבור בד\"ת כידוע שזהו עיקר המנגד [להשפיל] לבחי' סוס ורוכבו דק\"נ, וז\"ש ה' איש מלחמה כו' וכמו במלחמה שעיקר הנצחון הוא בסוס שמוליך את הרוכב בכח גדול יותר מכח גבור[ת] עצמ[ו] כנ\"ל, וכך הוא מלמטה למעלה גם בבחי' אותיות התורה שקורא האדם בתשב\"כ אע\"פ שאינו מבין ומשיג כלל מה שכתוב כע\"ה שעולה לתורה יוכל לידבק נשמתו בעצמות אוא\"ס ממש ע\"י צרופי אותיות הללו שקורא ושונה שלא הי' ביכולת נשמתו מצד עצמו לעלות ולידבק כלל, עד\"מ הרוכב על הסוס שהסוס יוליכנו למרחק גדול<sup data-n=\"8169\">264</sup> ובגובה מאד שלא הי' ביכולתו לעלות ולהגיע בעצמו שם, כך המרכבה של האותיות דתורה יוליכו לנפש הקורא אותם שנק' רוכב על אותיות הדיבור למעלה מעלה שהוא בחי' הדביקו' בעצמו' אוא\"ס למעלה גם מבחי' הח\"ע הגנוז באותיות <span data-k=\"pg\">רלח</span> ּ הללו, כי שרש האותיות דתורה למעלה גם מבחי' הרצון וחכ' שבהם כמ\"ש<sup data-n=\"8170\">265</sup> במ\"א בענין טנת\"א דתורה<sup data-n=\"8171\">266</sup> כו') וגם הנה הכוונה ורעותא דלבא שיש לאדם בקריאתו בתורה בבחי' דו\"ר שכליי' כדי לדבקה בה' השורה באותיות הללו וכה\"ג שגם זה נק' רוכב (וכן המח' ועיון השכל שמקיף לאותיות הדבור דתורה) על האותיות דתורה שקורא בפיו, לפי שהקריאה בפה אינו רק בחי' חיצוני' לגבי בחי' הפנימי' הרצון ואוי\"ר וכוונה שהוא בחי' הפנימי' שבנפשו, עכ\"ז<sup data-n=\"8172\">267</sup> יוליכנו הצירופי' דאותיות דתורה גם לאותה הכונה למעלה הרבה משרש נשמתו שזהו למעלה מעצם כח יכולת הנשמה בכוונה להגיע שם וכנ\"ל. וזהו כי על כל מוצא פי ה'<sup data-n=\"8173\">268</sup> דוקא יחי' האדם וכן חיים הם למוצאיהם בפה<sup data-n=\"8174\">270</sup><sup data-n=\"8175\">269</sup> דוקא וכן כי אמרתך חייתני<sup data-n=\"8176\">271</sup> וכה\"ג (וזהו הטעם שנשמות ת\"ח דוקא ילכו מחיל אל חיל בעליות עד אין שיעור למעלה משרש נשמתם לידבק בעצמו' א\"ס ממש מצד בחי' אותיות התורה שקראו ושנו כל ימיהם), וכ\"ז לפי שצרופי אותיות דתורה מצד עצמם יש להם שרש גבוה בעצמו' ממש לפי שנתחב\"ס יותר ממקור הח\"ע דתורה שהוא למעלה מבחי' אדם הרוכב על המרכבה העליונה כמו במ\"ת שא' כי תרכב על סוסיך כו' שבחי' אותיות הדיבור שיצא מפי ה' בי' הדברות שרשם למעלה יותר מבחי' הח\"ע ורצה\"ע שגנוז ורוכב עליהם כמשל המרכבה שנושא לרוכב כנ\"ל, וזה הי' ג\"כ ענין המלחמה בקי\"ס שא' ה' איש מלחמה להפיל לסוס ורוכבו דפרעה וכנ\"ל וד\"ל (וכמארז\"ל בים נדמה להם כבחור עושה מלחמה שנא' תפארת",[["8168","263","<b>במצות עיון ומצות קריאה</b>: ראה הל' ת\"ת לאדה\"ז פ\"ב, הי\"ב. לקמן קפא, א. פ' יתרו רנו, ב. תרומה שטז, ב. מאמרי אדה\"א בראשית ע' תקכז. וש\"נ. קונטרסים ע' תקמב. וש\"נ. הנחות תקע\"ז ע' ער. שע\"ת קכא, ב."],["8169","264","<b>למרחק גדול</b>: ו: למרחוק יותר."],["8170","265","<b>כמ\"ש</b>: אוצ\"ל: (כמ\"ש."],["8171","266","<b>טנת\"א דתורה</b>: ראה מאמרי אדה\"ז תקס\"ה ח\"ב ע' תרפג וע' א'יט. לקו\"ת חוקת נח, א ואילך."],["8172","267","<b>עכ\"ז</b>: ו: ע\"כ."],["8173","268","<b>כי על כל מוצא פי ה'</b>: עקב ח, ג."],["8174","270","<b>בפה</b>: ו: ליתא."],["8175","269","<b>חיים הם למוצאיהם בפה</b>: משלי ד, כב. ערובין נד, א."],["8176","271","<b>כי אמרתך חייתני</b>: תהלים קיט, נ."]]],[2300540585,"בחורים כחם<sup data-n=\"8177\">272</sup> שזהו המלחמה במדות דחו\"ג כמו שקטרגו מה נשתנו אלו מאלו<sup data-n=\"8178\">273</sup> ונצח למדה\"ד לפי שעתידים לקבל התו\"מ בה\"ס ובמ\"ת נדמה להם כזקן במלחמתה של תורה כו' כמ\"ש במ\"א), וזהו פי' רמה בים ענין רוממות וענין השלכה ושניהם אמת.\n<b>ויובן</b> זה בתוס' ביאור בהקדים תחלה להבין מ\"ש כי ידעתיו למען אשר יצוה את בניו ושמרו דרך הוי' לעשות צדקה ומשפט<sup data-n=\"8179\">274</sup> כו' שהן כללות כל המצות שנק' דרך הוי' דוקא כמ\"ש כי ישרים דרכי הוי'<sup data-n=\"8180\">275</sup> כו', וא\"כ יש להבין מ\"ש עוד לעשות צדקה ומשפט דמשמע דעיקר ענין המצות במעשה נק' צדקה ומשפט והול\"ל ושמרו לעשות צדקה ומשפט ומה זה שכפל הדברים לומר ב' דברים שמירה בדרך הוי' ועשי' בצדקה כו'. אך הענין הוא כמו שמבואר למעלה בענין אותיות התורה ששרשם יותר גבוה מן הח\"ע ורצון ותענוג העליון שגנוז בהם וכמרכבה שנושא לרוכב כו', כך יובן ג\"כ בענין המצות דהנה ידוע שיש מ\"ד דמצות צריכות כוונה<sup data-n=\"8181\">276</sup> שהוא בחי' הכוונה ורעו\"ד באוי\"ר ברצון ותענוג כמ\"ש במצותיו חפץ מאד<sup data-n=\"8182\">277</sup> ושידע הטעם וסוד הגנוז בה להיות יח\"ע השייך למצוה זו באו\"כ דאצי' כו', וזהו כמו הרוכב על הסוס שמנהיגו כרצונו כנ\"ל, כך הכוונה ורעו\"ד בהיותה בשרשה למעלה ברצון וח\"ע שבמצות הוא כמו בחי' רוכב על גוף מעשה המצות, ואמנם הרי מבואר למעלה שיש כח במרכבה דסוס להעלות לרוכב למקום שא\"י להגיע לשם מכח עצמו כלל כו', וזהו טעם דמ\"ד דמצות א\"צ כוונה<sup data-n=\"8183\">278</sup> וטעם כי המצות בפו\"מ מצד עצמה יש לה שרש גבוה הרבה יותר מן הכוונה וסוד הגנוז בה למעלה, כי שרש המעשה<sup data-n=\"8184\">279</sup> מצד עצמה מגיע בעצמו' בעל הרצון שלמעלה גם מטעם <span data-k=\"pg\">478</span> ּ כמוס לרצון כו' כמ\"ש במ\"א בענין החפץ לה' בעו\"ז<sup data-n=\"8185\">281</sup> כ\"א שמוע מזבח טוב<sup data-n=\"8186\">280</sup> כו' וזהו כתר ש\"ט דמשיח<sup data-n=\"8187\">282</sup> שהקים עולה של תו\"מ<sup data-n=\"8188\">283</sup> כו' והוא כתר דנעשה שבמ\"ת שלמעלה מכתר דנשמע כו' (וראי' משמחה ש\"מ מצד המעשה עצמה זוכה עי\"ז לג\"א<sup data-n=\"8189\">284</sup> ורוה\"ק שהן טעמי' וסודות התו\"מ כמ\"ש הרח\"ו [ז\"ל] על האריז\"ל<sup data-n=\"8190\">285</sup> כידוע). וזהו ושמרו דרך הוי' שהוא בחי' הכוונה וטעם במצות שעושה בחי' דרך להוי' באו\"כ דאצי' בתוס' אור חדש מבחי' העלם אור העצמו' ופנימי' דא\"ס עצמו כידוע בפע\"ח שכל המצות עיקרם להוסיף אורות באצי'<sup data-n=\"8191\">286</sup> (וכמו ע\"י עובדות דאברהם שקיים כל",[["8177","272","<b>תפארת בחורים כחם</b>: משלי כ, כט."],["8178","273","<b>מה נשתנו אלו מאלו</b>: נסמן לעיל פ' בא פח, ד."],["8179","274","<b>כי ידעתיו. . לעשות צדקה ומשפט</b>: וירא יח, יט [בדילוג]."],["8180","275","<b>כי ישרים דרכי הוי'</b>: הושע יד, י."],["8181","276","<b>דמצות צריכות כוונה</b>: ערובין צה, ב. לעיל קנו, ב. וש\"נ."],["8182","277","<b>במצותיו חפץ מאד</b>: תהלים קיב, א."],["8183","278","<b>דמצות א\"צ כוונה</b>: נסמן בהערה 276."],["8184","279","<b>המעשה</b>: ו: המצוה."],["8185","281","<b>בעו\"ז</b>: בעולות וזבחים."],["8186","280","<b>החפץ. . מזבח טוב</b>: (נסמן לעיל קנו, ד). ראה מאמרי אדה\"א נ\"ך ע' ב ובהנסמן בריש המאמר שם."],["8187","282","<b>כתר ש\"ט דמשיח</b>: נסמן לעיל קנו, ב."],["8188","283","<b>דמשיח שהקים עולה של תו\"מ</b>: ראה מאמרי אדה\"א דברים ח\"ד ע' א'תח. וש\"נ. שמות ח\"ב ע' תנח. וש\"נ. לקמן פ' תצוה שלו, א. ויקהל שצח, א."],["8189","284","<b>לג\"א</b>: ראה לעיל קנז, א הערה 353."],["8190","285","<b>האריז\"ל</b>: נסמן לעיל נה, א."],["8191","286","<b>בפע\"ח שכל המצות. . אורות באצי'</b>: נסמן לעיל קנו, ב."]]],[2300540601,"המצות<sup data-n=\"8192\">287</sup> ברוחניות למעלה באצי' כמ\"ש במ\"א). וז\"ש אשר יצוה את בניו ושמרו דרך הוי' שיצוה להם שיהי' בהם הכח ועוז לשמור דרך הוי', וכל שמירה הוא במח' וכוונה ורעותא דלבא באוי\"ר ודביקות אמיתי' להיות עי\"ז תוס' אור בשם הוי' דאצי' כמו במצות העליונות בשם הוי' דאצי' עצמו שנק' מצות[\"י] וכן או' שקדשנו במצותיו כידוע שה' מניח תפילין ומתעטף בציצית<sup data-n=\"8193\">288</sup> ועושה צדקה<sup data-n=\"8194\">289</sup> כו' שזהו הנק' דרך להוי' דאצי' שנמשך מן העצמו' דא\"ס דוקא כמ\"ש דוד בפקודיך<sup data-n=\"8195\">290</sup> כו' אביטה<sup data-n=\"8196\">291</sup> אורחותיך וכידוע.\n<b>אך</b> העיקר הוא בחי' המעשה דמצות בארץ בגשמיות גם בלא כוונה וטעם וכמ\"ד מצות א\"צ כוונה לפי שנתחב\"ס<sup data-n=\"8197\">292</sup> דוקא כמ\"ש סוף דבר<sup data-n=\"8198\">293</sup> כו' וכמו משל המרכב' שנושא לרוכב, כך מעשה המצו' מצד עצמ[ה] יש לה שרש בעצמות יותר מן הכוונה וטעם שבה כנ\"ל ונושא לרוכב שהוא הכוונה והטעם למעלה במהו\"ע ית' שאין ביכולתו להגיע שם בכל אוי\"ר ודביקות כלל. וז\"ש לעשות צדקה ומשפט כידוע שכל המצות נק' בשם צדקה כמ\"ש וצדקה תהי'<sup data-n=\"8199\">294</sup> לנו כי כו' והיינו כאשר המצות נעשי' בפו\"מ דוקא שנק' מצות המלך<sup data-n=\"8200\">295</sup> ואז נק' צדקה בה\"א<sup data-n=\"8201\">296</sup> דגם שע\"י הכוונה ורעותא דלבא נמשך תוספת אור באצי' (וע\"כ משכנו בגעה\"ע<sup data-n=\"8202\">297</sup> ), אבל העיקר הוא בהגיע אור השפע למטה בעשי' בפו\"מ שלזה נק' צדקה בה\"א כמו שעיקר הצדקה הוא כשנתקבל במקבל בפו\"מ וכמ\"ש אל יתהלל חכם בחכמתו<sup data-n=\"8203\">298</sup> שהן כוונות המצות כו' כ\"א בזאת כו' השכל וידוע אותי<sup data-n=\"8204\">299</sup> ממש ע\"י מעשה המצות לעשות חסד ומשפט וצדקה בארץ<sup data-n=\"8205\">300</sup> דוקא כי באלה חפצתי שנתחב\"ס <sup data-n=\"8206\">301</sup>דוקא שבסוף מעשה בלא כוונה נעוץ תחלת הכל שנק' חפץ ותענוג הפשוט ועצמי שבלתי נגלה גם באור דח\"ע כו', והוא בחי' סדכ\"ס דלמת\"ב כלל כנ\"ל שיהי' מזה דוקא אתעדל\"ע בעצמותו ממש<sup data-n=\"8207\">302</sup> להיות זורע צדקות באורות עליונים דאצי' מפנימית עצמותו ממש כמו להאיר תוספת אור חדש בשם הוי' דח\"ע דאצי' מבחי' חכמתו העצמיי' ממש בשם הוי' דחכ' דאצי' ע\"י מצות ת\"ת למטה דוקא, וכן ע\"י מצות צדקה למטה [דוקא] נמשך מעצמות ופנימי' החסד דא\"ס בחסד דאצי' וכה\"ג בשאר המצות כציצית ותפילין בהמשכות המקיפי' דמוחי' דחב\"ד כו' שלא הי' אור כזה [כלל] ע\"י מצות הרוחניות באצי' וכן ע\"י כוונה וטעם שבמצות כמ\"ש (בפ' לך לך<sup data-n=\"8208\">303</sup> ). וזהו",[["8192","287","<b>דאברהם שקיים כל המצות</b>: ראה גם לעיל פ' וארא סג, ג. וש\"נ."],["8193","288","<b>שה' </b>[ו: שהוי']<b> מניח תפילין ומתעטף בציצית</b>: ראה ברכות ו, א. ר\"ה יז, ב. מאמרי אדה\"א ויקרא ח\"ב ע' תסז. וש\"נ."],["8194","289","<b>שה'. . ועושה צדקה</b>: ראה ב\"ר פל\"ג, א. ויק\"ר פכ\"ז, א. סוטה יד, א."],["8195","290","<b>בפקודיך. . אורחותיך</b>: נסמן לעיל קמט, א."],["8196","291","<b>כו' אביטה</b>: ג: אשיחה ואביטה."],["8197","292","<b>שנתחב\"ס</b>: ראה ס\"י פ\"א, מ\"ז."],["8198","293","<b>סוף דבר</b>: קהלת יב, יג."],["8199","294","<b>שכל המצות. . וצדקה תהי'</b>: נסמן לעיל פ' שמות יד, א."],["8200","295","<b>שנק' מצות המלך</b>: ראה אסתר ג, ג. הנסמן במאמרי אדה\"א שמות ח\"א ע' יא. נ\"ך ע' רלה. לקמן פ' פקודי תנה, ג."],["8201","296","<b>צדקה בה\"א</b>: ראה גם מאמרי אדה\"א הנחות תקע\"ז ע' יט. וש\"נ."],["8202","297","<b>שע\"י הכוונה. . משכנו בגעה\"ע</b>: נסמן לעיל פ' שמות ה, א הערה 240."],["8203","298","<b>אל יתהלל חכם בחכמתו</b>: ירמי' ט, כב."],["8204","299","<b>כ\"א בזאת. . אותי</b>: ירמי' שם, כג."],["8205","300","<b>לעשות. . בארץ</b>: נסמן לעיל קלח, ד."],["8206","301","<b>דוקא</b>: ו: ליתא."],["8207","302","<b>בעצמותו ממש</b>: ו: בעצמו."],["8208","303","<b>בפ' לך לך</b>: ראה תו\"ח שם פג, א ואילך."]]],[2300540615,"שהמצות בפו\"מ בגשמיות דוקא נק' בשם צדקה בה\"א כמ\"ש וצדקה תהי' לנו כו' <span data-k=\"pg\">רלט</span> ּ וכן לעשות צדקה כו' כמו הצדקה שהוא המשכת השפע לעני דלית לי' מגרמי' כלום כך אור הזרוע ברצה\"ע שבמצות גשמיות שנעשי' בפו\"מ בדברים גשמיי' בעוה\"ז דוקא הוא עיקר גילוי אור השפע הפנימיות ועצמיות דמהו\"ע ית' למקבלי' שהן כנ\"י לפי שנעוץ תחב\"ס דוקא כמ\"ש כי באלה חפצתי דוקא שאין זה גם במצות הרוחניו' דאצי' מטעם הנ\"ל כמשל המרכבה שנושא לרוכב כו'. וזהו צדקה תרומם גוי<sup data-n=\"8209\">304</sup> שתרומם לישראל שנק' גוי אחד בארץ<sup data-n=\"8210\">305</sup> למעלה משרשם הראשון כנ\"ל שעי\"ז דוקא נק' מהלכים שהולכי' ועולים בלי שיעור למעלה, וזהו ענין הירידה בשביל העלי' כנ\"ל וד\"ל.\n<b>והנה</b> מעתה יש להבין מ\"ש לעשות צדקה ומשפט מהו ענין המשפט כו' וכן כתי' משפט וצדקה ביעקב<sup data-n=\"8211\">306</sup> אתה עשית כו', דלכאו' הצדקה והמשפט הן ב' הפכים דהצדקה היינו מה שעושה לפנים משוה\"ד דוקא שהוא מחמת מדת הרחמים (כמשי\"ת) כמו למען דעת צדקות ה'<sup data-n=\"8212\">307</sup> כו' שלא שמע למקטרג כו' וכה\"ג, והמשפט הוא הדין והיושר כמו כי כל דרכיו משפט<sup data-n=\"8213\">308</sup> כו' כידוע. אך הנה יש להבין תחלה בתוס' ביאור ענין ובחי' הצדקה שהן כללות כל המצות כנ\"ל, להיות ידוע דעיקר בחי' הצדקה הוא נמשך מצד בחי' החסד והטוב שזהו מה שיש בטבע הטוב והחסד ליתן מכל אשר לו לכל אדם, אך הצדקה היא להחיות רוח שפלים דוקא, כי מה שבטבע הטוב להטיב זהו אינו רק מחמת טובו וחסדו העצמי הרי ייטיב גם לעשירים כמו לעניים ואין בזה שיתוף כ\"כ ממדה\"ר אבל בחי' הצדקה יש בה מצד בחי' הרחמים יותר שמפני מדה\"ר בטבעו הרי ירחם על העני ושפל ביותר<sup data-n=\"8214\">309</sup> כמו לעני דל\"ל כלום ולחולה ומדוכה וכה\"ג, הרי עיקר חסד זה הוא להחיות רוח שפלים דוקא שיכול להיות הרבה יותר מן החסד שבא מצד טובו כי הרי ישפיע במדה מרובה יותר מעצם טובו מצד עוצם הרחמנות (כמו שאנו רואים שגם איש כילי ישפיע לעני מצד הרחמים שגובר על מדה\"ד ואכזריות שבו), ועכ\"ז באיש טוב וחסדן ירבה בטבעו מדה\"ר כי טבע טובו מוסיף כח בהמשכה ושפע זו שגם שישפיע מפני הרחמנות אבל יותר ירחם מפני מדת טובו דוקא, לפי שטבע הטוב הוא להרגיש יותר בשפלים ונמוכי רוח, כנראה לעין שכל שאינו טוב וחסד בעצם כ\"כ לא ירגיש ויתפעל כ\"כ משפלות זולתו (והוא מפני ששרש הטוב הוא בחי' העדר הרגשת עצמו עד שיוכל להניח ולבטל כל עצמו ולצמצם א\"ע וליתן מכל אשר לו לרעהו או לאחרים וזה חיותו ממש יותר משיטיב לעצמו כידוע",[["8209","304","<b>צדקה תרומם גוי</b>: משלי יד, לד."],["8210","305","<b>לישראל. . גוי אחד בארץ</b>: דהי\"א יז, כא. שמו\"ב ז, כג."],["8211","306","<b>משפט וצדקה ביעקב</b>: תהלים צט, ד."],["8212","307","<b>למען דעת צדקות ה'</b>: מיכה ו, ה. ראה גם מאמרי אדה\"א שמות ח\"ב ע' תקסח. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670099\" data-slug=\"torat-chaim\" data-id=\"2300670099\">תו\"ח וירא קט, ד</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670469\" data-slug=\"torat-chaim\" data-id=\"2300670469\">קיז, ב</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670575\" data-slug=\"torat-chaim\" data-id=\"2300670575\">קכ, ג</a>."],["8213","308","<b>כי כל דרכיו משפט</b>: האזינו לב, ד."],["8214","309","<b>מדה\"ר. . על העני ושפל ביותר</b>: ראה גם מאמרי אדה\"א שמות כאן (ע' קיד). הנחות תקע\"ז כאן (ע' נט). וש\"נ. לקמן פ' משפטים רצט, א."]]],[2300540629,"בטבע הטובי' כאברהם אע\"ה דעביד טיבו יתירה עם ברייתא<sup data-n=\"8215\">310</sup> וע\"כ הי' מכניס אורחים גם זרים<sup data-n=\"8216\">311</sup> לפי שהי' בחי' מותר בנפשו<sup data-n=\"8217\">312</sup> כעפר ואפר<sup data-n=\"8218\">313</sup> ) וע\"כ ממילא יש לו הרגשה גדולה בהתפעלות הרחמי' על העני ושפל ומדוכא), וע\"כ הטוב והרחמים מסתעפי'<sup data-n=\"8219\">314</sup> ומתכללים זע\"ז והוא ענין טוב וחסד וצדקה שתלויי' זב\"ז דוקא כמ\"ש טוב ה' לכל ורחמיו על כל מעשיו דמשום שטוב ה' בעצם ע\"כ ורחמיו על כו' דהא בהא תליא דהתפשטות ריבוי הרחמים תלוי ברב טוב העצמי מטעם הנ\"ל. וכן אנו או' הטוב כי לא כלו רחמיך שמצד רב טובו העצמי לא יכלה כח הרחמים שמתפשט בלי גבול כלל וכן המרחם<sup data-n=\"8220\">315</sup> כי לא תמו חסדיך שמצד הרחמים בטבע מדת הרחמים הגדולים ע\"כ יתמשך כח <span data-k=\"pg\">480</span> ּ החסד בלי גבול כו', וכן אנו או' בברהמ\"ז הזן את העולם כולו בטובו בחן ובחסד וברחמים כו' שזהו הכל לפנים משוה\"ד דוקא שבא מב' המדות האלה ביחד שהוא מדת הטוב והחסד ומדת הרחמים שתלויי' זה בזה כנ\"ל. וכך הי' במע\"ב שהי' רק מצד עצם טוב וחסד ה' כמ\"ש כי אמרתי עולם חסד יבנה<sup data-n=\"8221\">316</sup> כו' כי חפץ חסד הוא ושיתף בזה ממדה\"ר כידוע שהוא הנק' צדיק עליון כמ\"ש אמרו לצדיק כי טוב וכתי' כי צדיק ה' צדקות אהב<sup data-n=\"8222\">317</sup> כו' להחיות רוח שפלים שהוא הי' סיבת הצמצום בעצמו' אוא\"ס להיות רצונו להאציל ולברוא כו', והן ע\"ס דאצי' שנאצלו ע\"י הצמצום דקו\"ח כו', שזהו רק מחמת ב' מדות דטוב ורחמים שהוא לבחי' השפלות דוקא, כי ידוע דאין ערך כלל<sup data-n=\"8223\">318</sup> בין האצי' לגבי עצמות המאציל כו' כמו שאין ערך לנברא לגבי הבורא כו' כמו ויאצל מן הרוח<sup data-n=\"8224\">319</sup> כו' שאין זה רק בחי' הארה דהארה הנבדל כניצוץ קטן הנבדל מן השלהבת כו', וכמו להיות מציאות אור החכ' דאצי' מעצמות המאציל להיות נק' חכים כו' ה\"ז בא ע\"י בחי' צמצום ודילוג הערך ע\"י אותיות דשם הוי' שנק' שם ע\"ב<sup data-n=\"8225\">320</sup> כו' שעי\"ז נמשך אור החכ' דאצי' מן ההעלם דעצמו' לגילוי, וכן להיות מציאות אור הבינה דאצי' להיות נק' מבין כו' מבחי' העלם העצמו' דא\"ס הוא ע\"י שם הוי' דבחי' ס\"ג<sup data-n=\"8226\">321</sup> כו' ועד\"ז בשאר הספי' כידוע, וא\"כ ה\"ז בא ע\"י בחי' שפלות וענוה שמשפיל א\"ע להאיר אור החו\"ב ואור החו\"ג וכה\"ג שזהו רק מצד בחי' צדקה וחסד וטוב כי חפץ חסד הוא כמו החסד וצדקה להחיות רוח שפלים שתלויים זה בזה דוקא כנ\"ל דמצד רב הטוב בעצם יצמצם אור א\"ס א\"ע להאיר ברצונו הפשוט להאציל והיינו להיות מקור לאצי' בכלל וד\"ל.\n<b>אך</b> הנה ידוע בע\"ח דכל ההשתל' דע\"ס דאצי' באו\"כ או\"מ ואו\"פ הכל הוא ע\"פ מא' קו המדה (שנק' בזהר משחתא",[["8215","310","<b>דעביד טיבו יתירה עם ברייתא</b>: ראה זהר ואתחנן רסב, ב. סידור (שער התפילין) יב, א. אמ\"ב שם קלז, א."],["8216","311","<b>מכניס אורחים גם זרים</b>: ראה ב\"מ פו, ב. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670266\" data-slug=\"torat-chaim\" data-id=\"2300670266\">תו\"ח לך פג, ד</a> הערה 57."],["8217","312","<b>שהי' בחי' מותר בנפשו</b>: ראה גם לקמן קעג, ד. פ' יתרו רנט, ב. מאמרי אדה\"א דברים ח\"ב ע' תקלח. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670586\" data-slug=\"torat-chaim\" data-id=\"2300670586\">תו\"ח נח עו, א</a> ובהערה 10."],["8218","313","<b>כעפר ואפר</b>: וירא יח, כז."],["8219","314","<b>מסתעפי'</b>: ו: משתתפי'."],["8220","315","<b>הטוב כי לא כלו רחמיך. . המרחם</b>: נוסח מודים."],["8221","316","<b>כי אמרתי עולם חסד יבנה</b>: תהלים פט, ג."],["8222","317","<b>כי צדיק ה' צדקות אהב</b>: תהלים יא, ז."],["8223","318","<b>דאין ערך כלל</b>: ראה גם לקמן פ' תצוה שכה, ד. שה\"א סט, א. צח, א."],["8224","319","<b>ויאצל מן הרוח</b>: בהעלותך יא, כה."],["8225","320","<b>שם ע\"ב</b>: ראה לעיל פ' וארא פה, ג."],["8226","321","<b>דבחי' ס\"ג</b>: ראה שעה\"י קכח, ב ובהערה 43."]]],[2300540642,"או מתקלא כמ\"ש עד דלא הוה מתקלא<sup data-n=\"8227\">323</sup> כו' והוא בחי' בצד\"ק<sup data-n=\"8228\">322</sup> כידוע) וכללותו הוא בחי' הקו\"ח שהוא שרש כל ההמשכות דאורות מקיפי' ופנימי' שלפני האצי' וע\"ס דאצי' כידוע, וזה הקו נק' קו המודד כל מדידה כמו מי מדד<sup data-n=\"8229\">324</sup> כו' כמו המודד ושוקל במאזנים כו' וכמ\"ש בזהר בענין קנה המדה<sup data-n=\"8230\">325</sup>, וא\"כ זהו הכל בדין וחשבון מדוקדק לא יוסיף ולא יגרע שזהו ענין ובחי' המשפט כמו יכלכל דבריו במשפט<sup data-n=\"8231\">326</sup> כו' והוא היפך החסד וצדקה הנ\"ל שהוא ריבוי השפע לפנים משוה\"ד שבא מצד הרחמים כנ\"ל. אמנם הנה גם בבחי' קו המדה הזה יש מבחי' החסד דוקא רק שכלול מבחי' הדין והצמצום ג\"כ ונק' גבורה שבחסד ולזאת הרי יש בו בחי' ההתכללות דחו\"ג דוקא, וזהו שיש בכח הקו הזה לעשות בחי' ההתכללות בע\"ס דאצי' בג' הקוין חח\"נ<sup data-n=\"8232\">328</sup> כו' לאכללא<sup data-n=\"8233\">327</sup> שמאלא בימינא וימינא<sup data-n=\"8234\">329</sup> כו' כמו להחליף האור דחסד שיאיר בכלי הגבורה כו' וכה\"ג (כמ\"ש במ\"א בענין וי\"ו דוהנורא וכנ\"ל בענין נורא תהלות עושה פלא כו') לפי ששרשו מעצמות אור א\"ס ממש שלפני הצמצום הראשון הנק' מק\"פ<sup data-n=\"8235\">330</sup> כו' שכולל ב' המדות דחו\"ג יחד, וע\"כ נק' קו המדה שכולל ב' הפכים דחו\"ג צמצום והתפשטות וזהו שם אלקים דבראשית ברא אלקי'<sup data-n=\"8236\">331</sup> כו' והוא הנק' משפט שהוא בחי' ת\"ת<sup data-n=\"8237\">332</sup> שכולל ב' <span data-k=\"pg\">רמ</span> ּ הקוין דחו\"ג<sup data-n=\"8238\">333</sup> דהיינו קו האמצעי בכלל שנק' קו היושר בלי נטי' לימין ושמאל רק במדה<sup data-n=\"8239\">334</sup> כו'. וזהו ג\"כ שרש התורה דהיינו שכל בחי' אופן ההתכללו' דחו\"ג שבקו\"ח זה הנק' קו המדה בכלל כנ\"ל הוא אשר נמשך ע\"פ החכמה דתורה הקדומה שקדמה לעולם כמ\"ש ואהי' אצלו אמון אומנא<sup data-n=\"8240\">335</sup> כו' כידוע, והוא מ\"ש בזהר דאסתכל באורייתא וברא עלמא<sup data-n=\"8241\">336</sup> כו' וכמ\"ש כי הוא ציוה<sup data-n=\"8242\">337</sup> כו' חק נתן<sup data-n=\"8243\">338</sup> כו' הכל<sup data-n=\"8244\">339</sup> ע\"פ המשפט דח\"ע דתורה כמ\"ש אם לא בריתי<sup data-n=\"8245\">340</sup> כו' חוקות שמים וארץ כו' וכמא' בראשית בשביל התורה<sup data-n=\"8246\">341</sup> שנק' ראשית כמ\"ש ה' קנני ראשית דרכו<sup data-n=\"8247\">342</sup> בקו המדה הנ\"ל וד\"ל, וא\"כ הרי יובן ג\"כ [ד]כל אופן הצמצום וההתפשטות בע\"ס דאצי' כמו בשם הוי' דחו\"ב וחג\"ת כו', הכל נמשך מבחי' קו המדה הנ\"ל ע\"י התורה הקדומה דוקא הכל במדה ושיעור, והיינו לפי אופן בחי' התכללות המדות דח\"ע דתורה בעצמות המאציל כן נמשך מן ההעלם לגילוי אור דחו\"ב דאצי' ושאר הספי' וא\"כ בחי' התכללות דחו\"ג דתורה הקדומה הוא שרש הראשון לכל ההשתל' דקו\"ח הנ\"ל וד\"ל.",[["8227","323","<b>עד דלא הוה מתקלא</b>: זהר (ספרא דצניעותא) תרומה קעו, ב."],["8228","322","<b>מא' קו המדה. . בצד\"ק</b>: [ בוצינא דקרדוניתא] ראה זהר בראשית טו, א. יח, ב. פקודי רלג, א. מאמרי אדה\"א נ\"ך ע' עא. וש\"נ."],["8229","324","<b>מי מדד</b>: ישעי' מ, יב."],["8230","325","<b>בזהר בענין קנה המדה</b>: פקודי רלג, א."],["8231","326","<b>יכלכל דבריו במשפט</b>: תהלים קיב, ה."],["8232","328","<b>בג' הקווין חח\"נ</b>: נסמן לעיל פ' וארא פד, ד."],["8233","327","<b>הקו. . לאכללא</b>: נסמן לעיל פ' שמות מח, ב."],["8234","329","<b>לאכללא שמאלא בימינא וימינא</b>: נסמן לעיל פ' וארא פה, א."],["8235","330","<b>הצמצום הראשון הנק' מק\"פ</b>: ראה ע\"ח (דרוש עגו\"י) ש\"א ענף ב."],["8236","331","<b>דבראשית ברא אלקי'</b>: בראשית א, א."],["8237","332","<b>משפט. . ת\"ת</b>: ראה ת\"ז בהקדמה (יז, ב). מאמרי אדה\"א דברים ח\"א ע' קח. וש\"נ."],["8238","333","<b><a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670120\" data-slug=\"torat-chaim\" data-id=\"2300670120\">ת\"ת שכולל ב</a>' הקוין דחו\"ג</b>: ראה זהר (רע\"מ) צו כח, סע\"א. תו\"ח בראשית ח, ג ובהערה 52."],["8239","334","<b>במדה</b>: ו: כסדר."],["8240","335","<b>ואהי' אצלו אמון אומנא</b>: משלי ח, ל. ב\"ר בתחלתו."],["8241","336","<b>דאסתכל באורייתא וברא עלמא</b>: ראה זהר תולדות קלד, א. תרומה קסא, א. מאמרי אדה\"א דברים ח\"א ע' רעט."],["8242","337","<b>כי הוא ציוה</b>: תהלים קמח, ה."],["8243","338","<b>חק נתן</b>: תהלים שם, ו."],["8244","339","<b>הכל</b>: ו: ליתא."],["8245","340","<b>אם לא בריתי</b>: ירמי' לג, כה."],["8246","341","<b>בראשית בשביל התורה</b>: נסמן לעיל פ' וארא פא, ג."],["8247","342","<b>ה' קנני ראשית דרכו</b>: משלי יח, כב."]]],[2300540654,"<b>אך</b> א\"כ יש להבין למה נק' התו\"מ בשם [משפט] חסד וצדקה כנ\"ל אחר ששרש התורה הוא בבחי' הדין דקו המדה אע\"פ שהוא בבחי' ההתכללות דחו\"ג שזהו בחי' הת\"ת כנ\"ל, אבל שם צדקה הוא לפנים משוה\"ד כנ\"ל. ואמנם הענין הוא דזהו ההפרש בין תו\"מ שלמטה הנגל[י]ת לנו לשמור ולעשות בפו\"מ לתו\"מ העליונים שקדמו לעולם כנ\"ל, דאע\"פ שתורה הקדומה הי' כלול בעצמו' א\"ס ב\"ה ממש וכמ\"ש בה ואהי' אצלו ממש כנ\"ל, מ\"מ עיקר שלימות האמיתי דח\"ע דתוה\"ק הוא דוקא בת[ו\"מ] הנגלית לנו למטה כשבאה בסוף מעשה בדברים גשמיי' דק\"נ ביה\"ד<sup data-n=\"8248\">343</sup> שירד ה' על ה\"ס וא' אנכי מי שאנכי<sup data-n=\"8249\">344</sup> בחי' סדכ\"ס דלמת\"ב כלל אפי' מחה\"ק כו' הוא שנגלה בסוף מעשה משום דנתחב\"ס דוקא וכמ\"ש סוף דבר כו' כי זה כל האדם דתו\"מ שלמעלה וכן א' אז ראה ויספרה<sup data-n=\"8250\">345</sup> כו' עד ויאמר לאדם<sup data-n=\"8251\">346</sup> הן יראת ה' היא חכמה כו' (וכמ\"ש במ\"א כמו משל דאין חכם כבעל הנסיון<sup data-n=\"8252\">347</sup> כו' וכה\"ג), ולזה הטעם הגם ששרש קו המדה דקו\"ח נמשך מחכ' הקדומה דחש\"מ<sup data-n=\"8253\">348</sup> כנ\"ל אין זה רק להוסיף אור א\"ס באו\"כ דאצי' כפי המדה כנ\"ל. ואע\"פ שכ\"ז הוא בבחי' התיקון דח\"ע דתש\"מ בבחי' ההתכללות דחו\"ג כמו שירד בה\"ס בהתכללו' זו באנכי כו' כמ\"ש מימינו אש דת<sup data-n=\"8254\">349</sup> כו', אבל עיקר שלימות דח\"ע זו בהתכללות הי' בהתלבשות במ\"ע ול\"ת למטה בפו\"מ דוקא מטעם הנ\"ל, וזהו פי' בראשית בשביל התורה שנק' כו' בשביל תורה שלמטה דוקא ובשביל ישראל שמקיימי' התו\"מ בפו\"מ כמא' תנאי הי'<sup data-n=\"8255\">350</sup> כו' וד\"ל. וזהו ההפרש בין תו\"מ הרוחניות דאבות שא' ושמי הוי' לא נודעתי להם<sup data-n=\"8256\">351</sup> ובין תו\"מ בגשמיות דישראל שנק' תורת הוי'<sup data-n=\"8257\">352</sup> מצות הוי'<sup data-n=\"8258\">353</sup> ממש כמו שהוא בשלימות האמיתי דעצמו' ופנימי' דא\"ס ב\"ה ממש וכנ\"ל במ\"ש אל יתהלל חכם כו' כ\"א לעשות חסד ומשפט וצדקה בארץ דוקא כי באלה חפצתי כו' וד\"ל.\n<b>ובזה</b> יובן הטעם שתו\"מ שלנו הבאי' במעשה בגשמיות דוקא הוא שנק' בשם צדקה וחסד כנ\"ל ולא תו\"מ הרוחניי' גם כמו שהם בשרשם בעצמו' דח\"ע הקדומה הנ\"ל שהוא שרש דקו המדה הנ\"ל, וכמ\"ש <span data-k=\"pg\">482</span> ּ ויקם עדות ביעקב<sup data-n=\"8259\">354</sup> דוקא ותורה שם בישראל כו' כשקיבלו התו\"מ בגשמיות דוקא וכמא' רצה הקב\"ה לזכות את ישראל<sup data-n=\"8260\">355</sup> ע\"כ הרבה להם תו\"מ שנא' ה' חפץ למען צדקו<sup data-n=\"8261\">356</sup> [דוקא] יגדיל תורה (תש\"מ מטעם הנ\"ל) ויאדיר (ומ\"ש",[["8248","343","<b>ביה\"ד</b>: או: בי' הדברות."],["8249","344","<b>אנכי מי שאנכי</b>: נסמן לעיל פ' וארא סג, ד."],["8250","345","<b>אז ראה ויספרה</b>: איוב כח, כז."],["8251","346","<b>ויאמר לאדם</b>: איוב שם, כח."],["8252","347","<b>דאין חכם כבעל הנסיון</b>: ראה גם לעיל פ' בא קיט, ב. נסמן לעיל פ' שמות י, ד."],["8253","348","<b>דחש\"מ</b>: או: דתוש\"מ."],["8254","349","<b>מימינו אש דת</b>: ברכה לג, ב."],["8255","350","<b>תנאי הי'</b>: ראה שבת פח, א."],["8256","351","<b>ושמי הוי'. . להם</b>: נסמן לעיל פ' שמות א, ג הערה 42."],["8257","352","<b>תורת הוי'</b>: בא יג, ט."],["8258","353","<b>מצות הוי'</b>: ויקרא ד, ב. יג. כב. ועוד."],["8259","354","<b>ויקם עדות ביעקב</b>: תהלים עח, ה."],["8260","355","<b>רצה הקב\"ה לזכות את ישראל</b>: מכות כג, ב (במשנה) [ושם: לפיכך הרבה]."],["8261","356","<b>ה' חפץ למען צדקו</b>: ישעי' מב, כא."]]],[2300540666,"תתן אמת ליעקב וחסד לאברהם<sup data-n=\"8262\">357</sup>, זהו בחסד ואמת דתו\"מ העליונים כמ\"ש אשר נשבעת לאבותינו<sup data-n=\"8263\">358</sup> מימי קדם מח\"ע הקדומה הנ\"ל במצות הרוחניות שלהם ועכ\"ז שמי הוי' העצמי ממש לא נודעתי כו' מטעם הנ\"ל). וע\"ד דוגמא מצות צדקה וחסד שעושי' ישראל למטה בגשמיות לעני וד\"ל ע\"פ מצות התו' בה[ל]' צדקה דוקא מעוררי' למעלה בחי' מהו\"ע החסד והר\"ר העצמיי' דא\"ס שנק' רחמים גדולים<sup data-n=\"8264\">359</sup> שלמעלה מכל עיקר ומקור ההשתל' דקו\"ח הנ\"ל (שלא הי' אור כזה ע\"י צדקה וחסד דאברהם בחסד עליון הרוחני דאצי' כו') וזהו כללות בחי' ה\"ח דמ\"ע<sup data-n=\"8265\">360</sup>, וכן ע\"י מדה\"ד ביראה ופחד אלקי' בסומ\"ר בגשמיות מעוררים למעלה מבחי' פנימי' ועצמו' דגבו' עליונה שבעצמו' ממש שהן ה\"ג דל\"ת<sup data-n=\"8266\">361</sup> כו'). וזהו ושמרו דרך הוי' פי' דרך להוי' דאצי' היינו בחי' תוס' אור גדול מעצמות המאציל באצי' כמו ע\"י יח\"ע דמצות הרוחניות שהכינו האבות במעשיהם שיבא מן ההעלם לגילוי ביתר מכפי המדה שבבחי' קו המדה דהיינו בבחי' התכללות דחו\"ג שע\"פ תוה\"ק כנ\"ל, ואמנם עיקר השלימות האמיתי בדרך להוי' היינו ע\"י בחי' המעשה בפו\"מ במצות הנעשי' בגשמיות דוקא, וזהו לעשות צדקה ומשפט לעשות בפו\"מ שזהו דוקא שנק' צדקה למעלה מטעם שמעוררים למעלה מבחי' ר\"ר העצמיי' להיות לו דירה בתחתונים דוקא שזהו הבא מבחי' פנימי' ועצמיות דא\"ס שלמעלה הרבה מבחי' הטוב והחסד שהי' בתחלת ההשתל' להאיר ע\"י צמצום העצמו' כנ\"ל וד\"ל.\n<b>ויובן</b> זה בהקדים תחלה שיש ב' מדרגו' ברחמים א' רחמים הבאה בבחי' ההשתל' שיש בה גבול ומדה וגם ערך ויחוס והתפעלות כו', וחילוק מדרגות. והב' רחמים שלמעלה מבחי' ההשתל' שאין בה גבול כלל ולא מצד ערך והשתוות ואין בה חילוק מדרגות בין עליון לתחתון כלל. והענין הוא דרחמים שבבחי' ההשתלשלו' הוא [כ]אחד המדות דחו\"ג כך הרחמים יש בה גבול [לעשות] לפנים משוה\"ד מצד הרחמנות שתכלה כחה אם יגבר כח הדין כמו לרשע ביותר, וגם יש בה ערך ויחוס עם המרחם שאין התפעלות הרחמים נופל רק על מי שיש לו ערך ויחוס עמו כמו רחמנות האדם על אדם כמותו כעני ומדוכא וכה\"ג, אבל על החי גם שיש עליו התפעלות רחמים ג\"כ אך קטן הוא מאד<sup data-n=\"8267\">362</sup> לגבי הרחמים שעל האדם (וכן במין האדם יש חילוק בין איש נכבד ויקר הערך לפחות הערך כעו\"ש<sup data-n=\"8268\">363</sup> וכה\"ג, ובזה יש היפוך שעל השפל יותר יותר יגבר כח הרחמים כמו על ילד קטן ועני ומדוכא יותר מעשיר וגדול כו' לפי שעיקר הרחמים בא במקום שפלות יותר ולפ\"ע הרוממות דמרחם (כמשי\"ת), ועל",[["8262","357","<b>תתן אמת ליעקב וחסד לאברהם</b>: מיכה ז, כ [ושם: חסד — ראה להלן קעב, ג. מאמרי אדה\"א בראשית ע' קעו. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670522\" data-slug=\"torat-chaim\" data-id=\"2300670522\">תו\"ח וירא קז, א</a> בהערה 8]."],["8263","358","<b>אשר נשבעת לאבותינו</b>: המשך הכתוב תתן אמת."],["8264","359","<b>רחמים גדולים</b>: ראה גם בסמוך (קעא, ב) ד\"ה והנה. מאמרי אדה\"א נ\"ך ס\"ע רז ואילך."],["8265","360","<b>ה\"ח דמ\"ע</b>: נסמן לעיל פ' בא צו, א."],["8266","361","<b>ה\"ג דל\"ת</b>: ראה קו\"א לתניא (להבין מ\"ש בפע\"ח) קנח, ב."],["8267","362","<b>מאד</b>: ו: ליתא."],["8268","363","<b>כעו\"ש</b>: כעבד ושפחה."]]],[2300540678,"צומח ודומם ימעט כח הרחמנות יותר באיבודם וקלקולם גם אם הם מעשה ידיו או יקרים ביותר מן הבהמה כאבנים טובות וכלי יקר שאינו אלא היזק ממון כאיבוד כסף וזהב כו'). ולמעלה יובן מזה בבחי' הרחמים העליוני' האלקי' על מע\"ב שנק' מעשה ידיו עכ\"פ כמו דכתיב ורחמיו על כל מעשיו<sup data-n=\"8269\">364</sup> וכה\"ג, שבמדה זו יש שיעור וגבול וערך לפי שבאה מדה זו בבחי' הצמצום דהשתלשלו' כח האלקי להחיות מאין ליש במדות דחו\"ג והרחמים הוא לפנים משוה\"ד <span data-k=\"pg\">רמא</span> ּ כנ\"ל שיש בזה שיעור וגבול להיותו מרחם על הבריות, שגם שמצד עצם מדותיו ית' הן בלי גבול וגם בלתי ערך ויחוס כלל דאין ערך ויחוס כלל דאין ערוך כלל לנברא בע\"ג עם הבורא<sup data-n=\"8270\">365</sup> בלתי בע\"ג כו', מ\"מ מאחר שנתצמצם כחו בעולמות זהו כמדת התפעלות האדם שמרחם על מעשה ידיו שמצד כח יגיעת נפשו שנמשך בפעולתו יתעורר ברחמים על איבודם<sup data-n=\"8271\">366</sup> כו' וכמו בנינוה שחס על אדם ובהמה רבה<sup data-n=\"8272\">367</sup> כו' (וכן בקי\"ס שא' מעשה ידי טובעי' בים<sup data-n=\"8273\">368</sup> ואתם או' שירה כו') שיש בזה חילוקי מדרגות בין אדם לבהמה לפי שנשמת אדם בצלם אלקי' קרוב יותר בערך מן הבהמה כו', ועד\"ז יש חילוקי מדרגות ברחמים העליונים על כל ההשתלשלו' דעולמות דבי\"ע על עליונים ותחתונים שעל עולמות עליונים יותר יומשך הרחמים מצד שקרובים במעלה יותר (ולהיפוך שעל עולם השפל יותר יומשך ברחמים כמו כי רם ה' ושפל יראה<sup data-n=\"8274\">369</sup> כו' כמו שאדם מרחם על העני ושפל יותר מעל עשיר ונכבד כנ\"ל), וגם מצד טעם עיקר הרחמים שבא מסיבת ערך הרוממות וערך השפלות (כמשי\"ת) ג\"כ יחייב שיומשך בחי' הרחמים העליונים על עולם התחתון יותר מעל עולם העליון הרוחני בגעה\"ת וגעה\"ע כו' (לבד בחי' רחמים העצמיי' כרחמי האב על הבן שזהו כמו ע\"ע ממש וגם זה יגבר יותר בהיות הבן בשפלות ביותר (כמשי\"ת) וד\"ל.\n<b>והנה</b> מדרגה הב' ברחמים היינו בחי' הרחמים הגדולים שלמעלה מעלה מכל ההשתלשלות, ולכאורה אין זה מובן דאיך שייך בחי' רחמים לפני ההשתל' דעולמות דאין רחמים שייך רק על דבר הנמשך בהשתלשלו' כמו ורחמיו על כל מעשיו וכה\"ג, אבל קודם שנברא העולם שאין עוד מלבדו<sup data-n=\"8275\">370</sup> איך שייך בחי' הרחמים כו'. אמנם הענין הוא כמ\"ש זכור רחמיך ה'<sup data-n=\"8276\">371</sup> וחסדיך כי מעולם המה, דהיינו מעולם הא\"ס עצמו כמו שהוא במהו\"ע ית' ממש שהוא הנק' רחמים רבים או רחמים גדולים שהן למעלה מבחי' גבול ומדה, כמו כי לא כלו רחמיך<sup data-n=\"8277\">372</sup> וכן א' חסדי ה' כי לא תמנו<sup data-n=\"8278\">373</sup> בבחי' א\"ס ממש, וזהו שאנו או' אלקי",[["8269","364","<b>ורחמיו על כל מעשיו</b>: תהלים קמה, ט."],["8270","365","<b>דאין ערוך. . לנברא בע\"ג עם הבורא</b>: ראה גם לקמן פ' יתרו רנו, ד. רנח, ב. תרומה שיב, א. תצוה שכה, ב. ויקהל תד, ד. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680383\" data-slug=\"torat-chaim\" data-id=\"2300680383\">תו\"ח מקץ רכב, א</a> (ובהנסמן במ\"מ לשם)."],["8271","366","<b>האדם שמרחם על מעשה ידיו. . על איבודם</b>: ראה גם ערכין כד, א. כח, א (במשנה). מאמרי אדה\"א הנחות תקע\"ז ע' נח. וש\"נ. שע\"ת כז, סע\"ב ואילך ובהערה 25."],["8272","367","<b>בנינוה שחס על אדם ובהמה רבה</b>: יונה ד, יא."],["8273","368","<b>מעשה ידי טובעי' בים</b>: ראה מגילה י, ב."],["8274","369","<b>כי רם ה' ושפל יראה</b>: תהלים קלח, ו."],["8275","370","<b>שאין עוד מלבדו</b>: ואתחנן ד, לה."],["8276","371","<b>זכור רחמיך ה'</b>: תהלים כה, ו. ראה גם לעיל פ' וארא סב, ב. וש\"נ."],["8277","372","<b>כי לא כלו רחמיך</b>: נוסח מודים (תפלת העמידה)."],["8278","373","<b>חסדי ה' כי לא תמנו</b>: ראה גם לעיל פ' בא קיב, ד. וש\"נ."]]],[2300540690,"עולם ברחמיך הרבים<sup data-n=\"8279\">374</sup> רחם עלינו ברחמיך העצמיי' דוקא שאין להם גבול ושיעור כלל שלמעלה הרבה מבחי' הרחמים שבאה בבחי' ההשתלשלו' שהן בבחי' גבול ומדה ע\"פ מא' קו המדה המודד כל הע\"ס דחו\"ב וחג\"ת כו'. ואע\"פ שקודם ההשתל' הי' הוא ושמו בלבד והאיך שייך לשון רחמים שאינו אלא על דבר נפרד זולתו, הענין הוא דבמדת הרחמים יש ב' סיבות א' בסיבת התפעלות הרחמים מצד קירוב הערך אל המשפיע כרחמנות האדם על זולתו וכן [על] מעשה ידיו שהן יגיע כפיו וכה\"ג כנ\"ל שאז יש חילוק[י] מדרגות כנ\"ל ונמדד במדה מן הרצון ושכל כו'. אבל הסיבה הב' ברחמים הוא אשר בא מחמת בחי' עוצם הרוממות וההתנשאות כמו מלך רם ונשא על הכל, דהכל כלא חשיב קמי' כגדול כקטן ממש בשוה, שמחמת זה יתפשט בחי' הרחמים ממנו על הכל בלי גבול כלל ובלתי חילוק מדרגות כלל וכלל כשר כעבד ממש בשוה, ואדרבה על השפל ביותר יותר יומשך הרחמים כי בערך עומק רום לא יומשך רק לעמ\"ת<sup data-n=\"8280\">375</sup>, כמו המלך המרומם ביותר שירחם על העני ושפל יותר מעל השר הגדול דזהו טבע <span data-k=\"pg\">484</span> ּ עיקר הגיאות והרוממות לרחם על השפל ולהשפיל גיאי' כו' (משום דלגבי עצם הרוממות גם השר כלא חשיב ממש וגם מה שתופס מקום בעצמו כלא ממש חשיב א\"כ גם גיאות השר שפלות גמור הוא כשפלות העני ויפול הרחמים על שניהם בשוה ממש), וזהו ההפרש בין ההתנשאות שמצד עצמו שמובדל בערך לגמרי שישוה לפניו גיאות השר הגדול עם שפלות העני וירחם על שניהם בשוה ממש כנ\"ל ובין התנשאות על העם שישפיל גיאים ויביט על עני ונכה רוח דוקא כמו כי רם ה' ושפל יראה [וכן] אני מרום וקדוש<sup data-n=\"8281\">376</sup> כו' את מי אשכון<sup data-n=\"8282\">377</sup> כו' שזהו בחי' רוממות והתנשאות דבחי' סובב הכללי ששייך לומר בו בעומ\"ר שעיקרו מאיר בעומ\"ת, אבל למעלה מבחי' עמ\"ר ועמ\"ת שזהו בחי' ההתנשאו' שמצד עצמו ממש שלא יתכן לקרותו גם רם על כל ההשתלשלו' כו' דשם שוין ממש עומ\"ר ועומ\"ת וא\"כ בחי' כח הרחמים שבעצמו' ממש שוה על הגיאי' ושפלים בשוה ממש וד\"ל).\n<b>וכך</b> יובן למעלה בהיות ידוע שאין ערוך כלל בין ההשתל' דנאצלי' ונבראי' כו' לגבי מהו\"ע א\"ס ב\"ה ואפי' העולמות היותר עליונים שלפני הקו\"ח כו' שהן בבחי' מל' דא\"ס שנק' נפלאות או פלא [כו'] (שהוא בחי' מקיף הכללי דמח' הקדומה שמקיף לקו\"ח מראשו לסופו כא' ממש כנ\"ל בענין עושה פלא כו') אין להם ערך כלל לגבי אמתת אור העצמו' דא\"ס ב\"ה שנק' סתימו דכל סתימין, שגם העולמות שנק' סתימי' בבחי' ההעלם דמקיף הכללי גם מהם הוא סתום ונעלם (והוא בחי' ההתנשאו' שמצד עצמו ממש שאין לו שיעור למעלה כו' שזהו למעלה מבחי' עומ\"ר ועומ\"ת דמקיף הכללי הנ\"ל) וכמ\"ש דלית מח'",[["8279","374","<b>אלקי עולם ברחמיך הרבים</b>: ברכת יוצר. ראה גם תו\"ח ויצא קעז, ב ובהערה 17."],["8280","375","<b>עומק רום. . רק לעמ\"ת</b>: נסמן לעיל פג, ב."],["8281","376","<b>אני מרום וקדוש</b>: ישעי' נז, טו [בהוספת תיבת ”אני\" — ראה לקמן רל, ד. פ' משפטים רצט, ב. מאמרי אדה\"א דברים ח\"א ע' רב. וש\"נ. ש\"א לז, ב. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670429\" data-slug=\"torat-chaim\" data-id=\"2300670429\">תו\"ח נח נג, ד</a> הערה 43]."],["8282","377","<b>את מי אשכון</b>: נסמן לעיל פג, ב."]]],[2300540702,"תפיסא בך כלל אפי' מח' הקדומה דמל' דא\"ס שלפני הצמצום כו' (וגם בחי' טה\"ע שנק' שמי השמים שנק' בשם מקיף למקיף עכ\"פ לא יכלכלוך<sup data-n=\"8283\">378</sup> כו' וכמ\"ש אתה עשית את השמים ושה\"ש<sup data-n=\"8284\">379</sup> כו' כידוע דגם מה שאוא\"ס למעלה עד אין קץ ולמטה כו' גם זה אינו אלא בחי' הארה בעלמא מאור העצמו' ממש שאין שם גם בחי' מעלה ומטה שבבחי' א\"ס [שזה] שנק' התנשאו' או התפשטו' כלא חשיב לגבי מהו\"ע ממש וד\"ל). ולפ\"ז הרי יובן שיש ג' מיני רחמים שהן בלי גבול, א' במקיף הכללי שנק' מקיף מוגבל דהיינו עמ\"ר ועמ\"ת הנ\"ל, והב' במקיף למקיף דהיינו מה שלמעלה עד כו', והג' במהו\"ע ית' ממש שלמעלה גם משה\"ש הנ\"ל וד\"ל (וזה נרמז במה שאו' המאיר לארץ<sup data-n=\"8285\">380</sup> כו' ברחמי[ם] שהוא הבא במדה [ו]בבחי' ממלא כו' שמזה מחדש בטובו מע\"ב כנ\"ל [כ]מ\"ש טוב ה' כו' ורחמיו כו', ואח\"כ המלך המרומם לבדו בחי' ההתנשאו' שמצד עצמו בחי' טה\"ע שנק' שה\"ש מקיף למקיף כו', ואח\"כ בחי' טה\"ת מקיף הכללי המוגבל שעליו א' עושה פלא כמו נוטה שמים כו'. וזהו המתנשא מימו\"ע לבד, ואח\"כ או' ברחמיך הרבים שבמהו\"ע ממש שלמעלה גם מבחי' מלך מרומם כו' שרחם עלינו בנ\"י על תו\"מ בפו\"מ שנק' צדקה וכרחמי האב על הבן כו' להיות נמשך למטה מטה ממש בהתלבשות גשמיות שנק' אדון עוזינו צור משגבינו כו' עד משגב בעדינו <span data-k=\"pg\">רמב</span> ּ בעוה\"ז הגשמי שהן ד' מקיפים<sup data-n=\"8286\">381</sup> דאבי\"ע שבמצות הוי' בפו\"מ דוקא (כמשי\"ת וד\"ל). וזהו כימי צאתך מאמ\"צ שעשה נפלאות בגילוי דסדכ\"ס למטה כמו בקי\"ס כנ\"ל, אראנו נפלאות האלה ממש לע\"ל כמו שהוא למעלה שעושה נפלאות גדולות לבדו [בעולמות] שנק' נפלאות בגילוי [ה]העלם דמקיף למקיף הנ\"ל מטעם הנ\"ל וד\"ל.\n<b>וא\"כ</b> הרי יובן מכ\"ז שבחי' הרחמים שבמהו\"ע ית' ממש שנק' רחמיך הרבים אשר מעולם הא\"ס עצמו ממש יאיר בעולמות העליונים שלפני האצי' שנק' נפלאות כמו בעולמות התחתונים כמו בסוף העשי' ממש בשוה. מאחר שמהו\"ע ית' ממש מובדל ומרומם בערך לגמרי מכל מקור ההשתל' גם מעולמות העליונים ביותר כמו מעולמות התחתונים ממש בשוה ע\"כ תגדל הרחמים על עולמות העליונים כמו על [עולמות] התחתונים בשוה, כי קמי' כלא ממש חשיב כגדול כקטן בשפלות ודילוג הערך בלי חילוק מדרגות כלל, דאע\"פ שעיקר הרחמים הוא לפ\"ע הרוממות וערך השפלות ועולמות העליונים יותר גבוהי' מן עולמות התחתונים כערך מעלת החי על הצו\"ד ויותר מזה כמו מעלת הרוחניות על הגשמיות עכ\"פ, אך זהו כשבא בדרך השתלשלות דעו\"ע כו' כמו מעלת האדם ביתרון על החי הקטן כזבוב ויתוש שעכ\"ז יש להם ערך ויחוס שזה ברי' וזה ברי' רק שהאדם בריה גבוה והיתוש ברי' שפילה, אבל למעלה מבחי'",[["8283","378","<b>טה\"ע שנק' שמי השמים. . לא יכלכלוך</b>: מל\"א ח, כז. ראה להלן קעח, ג. וש\"נ."],["8284","379","<b>אתה עשית. . ושה\"ש</b>: נחמי' ט, ו [ושם: שמי השמים — ראה גם לקמן פ' ויקהל תלג, א. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680190\" data-slug=\"torat-chaim\" data-id=\"2300680190\">תו\"ח וישב רז, א</a> הערה 5]."],["8285","380","<b>שאו' המאיר לארץ</b>: בברכת יוצר."],["8286","381","<b>אדון עוזינו. . ד' מקיפים</b>: נסמן לעיל פ' וארא נג, א."]]],[2300540714,"השתלשלות דעו\"ע ה\"ז בדילוג הערך לגמרי עד שהרחמי' על האדם כמו על היתוש והדומם ממש בשוה כי גם האדם כלא ממש כדומם. וכך הוא בחי' דילוג הערך מעצם הרוממות דעצמות א\"ס על כל ההשתל' עד שאין חילוק כלל בין עולם העליון יותר לתחתון ביותר כמו בחי' אצי' ועשי' שוין ממש (ואין זה כערך הרוממות דמלך גבוה על העני ונבזה כו' דמ\"מ יש ערך זע\"ז דשניהם ממין אדם אלא שזה גבוה וזה שפל שיש בזה שיעור ומדה עכ\"פ, אבל ערך שפלות ההשתלשלו' כלא ממש חשיבא בלתי ערך ודמיון כלל (להיותו למעלה גם מבחי' עומ\"ר ועומ\"ת כנ\"ל) ע\"כ הרחמים הוא בלי גבול כלל ועל כולם בשוה ממש ולזה נק' בשם רחמים רבים דוקא כנ\"ל וד\"ל. והוא הנק' ג\"כ בשם י\"ג מדה\"ר שנמשך מבחי' רעוא דכ\"ר<sup data-n=\"8287\">382</sup> ע\"י צמצומי' די\"ג ת\"ד<sup data-n=\"8288\">383</sup> כו' כמ\"ש ויעבור ה' על פניו ויקרא כו', דאע\"פ שי\"ג ת\"ד הן בבחי' ע\"י וא\"א דאצי' שנק' מקור לאצי' ורוממות העצמו' דא\"ס הוא למעלה גם מבחי' מל' שבקו\"ח כנ\"ל, מ\"מ בדרך התלבשות ודילוג גדול יש באור הרחמים די\"ג מדה\"ר בצמצומי' גדולים מבחי' הרחמים העצמיי' שבעצמות א\"ס ממש כמ\"ש ויקרא ה' ה'<sup data-n=\"8289\">384</sup> כו' ונמשכים להאיר בכנ\"י בבחי' פנימי' ועצמיות בכל יו\"כ<sup data-n=\"8290\">385</sup> כידוע כמ\"ש יאר ה' פניו אליך<sup data-n=\"8291\">386</sup> דוקא וד\"ל (ואע\"פ שא' טוב ה' לכל ורחמיו על כל מעשיו, זהו בחי' הרחמים הבאים בבחי' ההשתל' שמאיר לכל מעשיו כמו טוב ה' לכל שבטובו מחדש כל מע\"ב כו', משא\"כ ר\"ר העצמיי' שאינו נמשך רק לבנ\"י כמו רחמי האב על הבן כמ\"ש כי בנים אתם<sup data-n=\"8292\">387</sup> כו' כמשי\"ת). וזהו חנון ורחום הוי'<sup data-n=\"8293\">388</sup> שע\"י שהוא חנון ורחום בעצם למעלה מן ההשתל' כנ\"ל בי\"ג מדה\"ר שלפני האצי' שנק' י\"ג ת\"ד דא\"א שעי\"ז נמשך שם הוי' בתוס' אור להיות נק' חכים כו' בשם ע\"ב<sup data-n=\"8294\">389</sup> דחכ'<sup data-n=\"8295\">390</sup> דאצי' <span data-k=\"pg\">486</span> ּ מן ההעלם לגילוי (כמ\"ש בע\"ח דאור אבא מקבל ממזל [הח'] ונוצר<sup data-n=\"8296\">391</sup> כו') ועד\"ז מאיר בשאר הספי', ואח\"כ א' טוב ה' לכל כו' שהוא רחמים שבאה בבחי' ההשתל' וד\"ל.\n<b>ומעתה</b> יתורץ הקושיא הנ\"ל איך שייך לשון רחמים לפני ההשתלשלו' דאין עוד מלבדו כו', דבאמת בחי' ר\"ר דעצמו' א\"ס ממש א\"א שיבא בעולמות בבחי' גילוי אור כלל רק בבחי' מקיף בהעלם גדול מאד על כל ההשתלשלו' בשוה ממש מאחר שבא מצד עצם הרוממות דא\"ס עצמו שמובדל ומרומם לגמרי כנ\"ל, רק אפס קצהו נמשך בצמצום ומדה עד להיות מרחם על הבריות וכמו ורחמיו על כל מעשיו מצד צמצום",[["8287","382","<b>רעוא דכ\"ר</b>: נסמן לעיל פ' שמות ה, ג."],["8288","383","<b>די\"ג ת\"ד</b>: זהר (ספרא דצניעותא) תרומה קעז, א. ב."],["8289","384","<b>ויעבור ה' על פניו ויקרא. . ה' ה'</b>: תשא לד, ו."],["8290","385","<b>די\"ג מדה\"ר. . בכל יו\"כ</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380717\" data-slug=\"likkutei-torah\" data-id=\"4001380717\">לקו\"ת דברים א, ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380925\" data-slug=\"likkutei-torah\" data-id=\"4001380925\">נצבים נא, ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381037\" data-slug=\"likkutei-torah\" data-id=\"4001381037\">האזינו עח, ג</a>. מאמרי אדה\"ז תקס\"ו ע' שנז. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670161\" data-slug=\"torat-chaim\" data-id=\"2300670161\">תו\"ח לך צה, ב</a>. מאמרי אדה\"א דברים ח\"א ע' פא וע' שלב. ח\"ב ס\"ע תכב ואילך. ח\"ג ע' תשסד וע' תתצא. דרושי חתונה ח\"ב ע' תקנ. לעיל קסא, ד. בסמוך בפנים (קעב, ב). קעד, ד."],["8291","386","<b>יאר ה' פניו אליך</b>: נשא ו, כה."],["8292","387","<b>כי בנים אתם</b>: נסמן לעיל פה, ג."],["8293","388","<b>חנון ורחום הוי'</b>: תהלים קמה, ח."],["8294","389","<b>בשם ע\"ב</b>: נסמן לעיל פ' וארא פד, ד."],["8295","390","<b>בשם ע\"ב דחכ'</b>: נסמן לעיל פד, ד."],["8296","391","<b>דאור אבא. . ונוצר</b>: נסמן לעיל פ' שמות לו, א."]]],[2300540726,"אורו להיות מקור להשתלשלו' כנ\"ל וד\"ל, אבל לכנ\"י נמשך מבחי' ר\"ר הנ\"ל בגילוי אור כמו בי\"ג מדה\"ר ביו\"כ כנ\"ל וכמ\"ש זכור רחמיך ה' כו' וכמו חנון ורחום כו', והוא מטעם שנק' בנים וכמא' ישראל עלה במח'<sup data-n=\"8297\">392</sup> כו' בבחי' פנימיות ועצמיות כמ\"ש הבן יקיר לי<sup data-n=\"8298\">393</sup> כו' המו מעי לו רחם כו' וכרחמי האב על הבן ממש שהוא בבחי' פנימי' ועצמיות ממש שלמעלה מבחי' הרחמים הבא בבחי' ההשתל' כרחמיו על כל מעשיו וכה\"ג, וכמו שאנו רואים שבכל צרתם לו צר<sup data-n=\"8299\">394</sup> ממש דוקא בנש\"י בגופי' בהיותם בלחץ ודחק ושפלות עצומה מאויביהם כו' כמו ותעל שועתם<sup data-n=\"8300\">395</sup> כו' (וכאשר אנו או' אבינו אב הרחמן<sup data-n=\"8301\">396</sup> רחם עלינו כו' וכן אב הרחמן המהולל בפה עמו<sup data-n=\"8302\">397</sup> [שע\"י] שהוא אבינו אב הרחמן יכול להיות מהולל בפה עמו דוקא בשבחי' שמשבחים לשם הוי' דע\"ס דאצי' שיאיר מעצמות המאציל להיות נק' חכים ומבין כו' שלא יכלו להלל כן זולתם שאין להם שרש בעצמו' דא\"ס רק מבחי' הצמצום דשם אלקי' כו' ואח\"כ משובח ומפואר גם בעולמות העליוני' שהן מלאכי' שנק' חסידיו ועבדיו<sup data-n=\"8303\">398</sup> כו', כי הרי מצד עצמו' א\"ס הרי נק' יחיד לבדו למעלה מבחי' המדות וספי' כמ\"ש אנת הוא חד ולא בחושבן<sup data-n=\"8304\">399</sup> י\"ס וכמו שא' ולאו מכא\"מ כלל כנ\"ל ורק מצד בחי' טובו ורחמנותו<sup data-n=\"8305\">400</sup> מחדש השפע מעצמות המאציל לנאצלים ומאצי' לבריאה כו'. ואמנם בחי' טוב ורחמים זה אינו בא רק במדה ושיעור לפ\"ע הצמצום דהשפעה זו שנמשך מבחי' חיצוני' האור דעצמו' הא\"ס אחר העלם וצמצום העצמו' כנ\"ל, אבל בחי' ר\"ר דעצמותו ממש אינם מעוררים רק נש\"י בלבד שעלו במח' [ו]נק' בנים ואו' אבינו אב הרחמן כו' ואח\"כ נמשך בחי' הטוב והרחמים על כל ההשתל' עד שמאיר לארץ ברחמים כו' להיות מחדש בטובו, וזהו שע\"י י\"ג מדה\"ר דיו\"כ לישראל נמשך השפע דחסד ורחמים גם לכל העולמות עד ע\"ש<sup data-n=\"8306\">401</sup> כו' וד\"ל.\n<b>ובכ\"ז</b> יובן בתוס' ביאור מ\"ש אשר יצוה את בניו ושמרו כו', דהנה אנו אומרי' אבינו אב הרחמן רחם עלינו ותן בלבנו בינה להבין ולהשכיל לקיים את כל דברי תלמוד תורתך כו' והאר עינינו בתורתיך ודבק לבנו במצותיך כו', דלכאו' אין [ל]זה הבנה ע\"ד הפשוט דמה שייך רחמים לענין זה שיתן בלבנו בינה כו' לקיים כו' שזה תלוי בבחירת האדם דוקא כמ\"ש ראה נתתי<sup data-n=\"8307\">402</sup> כו' ובחרת בחיים<sup data-n=\"8308\">403</sup> וכתיב סוף דבר כו' האלקים ירא כו' והכל בידי שמים<sup data-n=\"8309\">404</sup> כו', אך בקשה זאת היא לעורר בחי' ר\"ר העצמיי' דפנימי' ועצמו' א\"ס ממש כנ\"ל שהוא בחי' רחמי האב על <span data-k=\"pg\">רמג</span> ּ הבן",[["8297","392","<b>ישראל עלה במח'</b>: נסמן לעיל פ' שמות לב, ב."],["8298","393","<b>הבן יקיר לי</b>: ירמי' לא, יט."],["8299","394","<b>שבכל צרתם לו צר</b>: ראה גם לעיל פ' וארא נא, ד. וש\"נ."],["8300","395","<b>ותעל שועתם</b>: שמות ב, כג."],["8301","396","<b>אבינו אב הרחמן</b>: ברכת (אהבת עולם) ק\"ש."],["8302","397","<b>אב הרחמן המהולל בפה עמו</b>: נוסח ברוך שאמר."],["8303","398","<b>משובח ומפואר. . מלאכי'. . חסידיו ועבדיו</b>: ראה גם לעיל סא, א. וש\"נ."],["8304","399","<b>אנת הוא חד ולא בחושבן</b>: ת\"ז בהקדמה (יז, א)."],["8305","400","<b>טובו ורחמנותו</b>: ו: רחמנותו."],["8306","401","<b>ע\"ש</b>: נסמן לעיל לז, ג."],["8307","402","<b>ראה נתתי</b>: נצבים ל, טו."],["8308","403","<b>ובחרת בחיים</b>: נצבים ל, יט."],["8309","404","<b>והכל בידי שמים</b>: ברכות לג, ב."]]],[2300540738,"כנ\"ל וכמא' רצה הקב\"ה לזכות את ישראל כו' כמ\"ש ה' חפץ למען צדקו, צדקו ממש שהן המצות בכלל שנק' צדקה כנ\"ל ולא רצה לזכות לאחרים זולתם כמ\"ש וזרח משעיר למו<sup data-n=\"8310\">405</sup> כו' שגם שהיו רוצים לקבל התו\"מ<sup data-n=\"8311\">406</sup> לא נתן להם רק לישראל שנק' בנים כנ\"ל מצד בחי' ר\"ר העצמיי', וע\"כ חפץ בהם דוקא למען צדקו ורחמנותו עליהם שבבחי' א\"ס ממש שלמעלה הרבה מבחי' החסד והרחמים שבא בבחי' ההשתל' דסובב הכללי וממלא כו' כנ\"ל. וזהו למעלה גם מר\"ר שמבקשים רחם עלינו להיות אדון עוזינו ומשגב בעדינו להציל מכל קטרוגי' למעלה ולמטה, אך שבאמת מה שנמשך להיות אדון עוזינו כו' זהו בא ע\"י קיום התו\"מ בפ\"מ דוקא שעי\"ז דוקא נמשך ר\"ר העצמיי' הנ\"ל ונתלבש למטה להיות בבחי' מקיף ושומר לישראל כצור ומשגב ומגן ממש כמו צור חיינו מגן ישענו כו' כמ\"ש על התורה בשכבך תשמור עליך<sup data-n=\"8312\">407</sup> כו' ומצוה מגינא ומצלא<sup data-n=\"8313\">408</sup> כו'. וזהו שמבקשים אבינו אב הרחמן דוקא כמ\"ש לע\"ל כי אתה אבינו<sup data-n=\"8314\">409</sup> אתה ממש בבחי' ר\"ר העצמיי' הנ\"ל כי אברהם לא ידענו וישראל<sup data-n=\"8315\">410</sup> כו', דאע\"פ שא' תתן אמת ליעקב וחסד לאברהם שהן בחי' התו\"מ העליוני' כמו שהן בשרשם הראשון כנ\"ל שנק' חסד ואמת שזהו בחי' אמת דתוה\"ק וחסד דמצות שבמהו\"ע ית' שנק' מצותיו כו' כנ\"ל דהאבות קיימו כל התו\"מ ברוחניות כו' עכ\"ז במצות הנגלות לנו לשמור ולעשות בפו\"מ מגיע במהו\"ע ית' ממש כנ\"ל עד שעל ידם נעשה שלימות האמיתי בח\"ע דחש\"מ כנ\"ל שזהו בראשית בשביל התורה שלמטה דוקא, וכן א' אל יתהלל חכם בח\"ע דתשמ\"ע כ\"א בזאת יתהלל כו' השכל וידוע אותי ממש לעשות חסד כו' בארץ דוקא כי באלה חפצתי כמ\"ש ה' חפץ למען צדקו ממש יגדיל כו' וד\"ל.\n<b>וזהו</b> שאו' אבינו אב הרחמן כו' ותן בלבנו בינה כו' לקיים את כל ד\"ת שבע\"פ דוקא שה[י]א בבחי' בינה שבא' לקיום המעשה בפו\"מ דוקא, כי בתושב\"כ שהיא בחכ' לא ידוע אופן פרטי המעשה דמ\"ע ובסומ\"ר [ד]ל\"ת עדיין וכמ\"ש במ\"א שז\"ש א\"ח עט\"ב<sup data-n=\"8316\">411</sup> ששרש תושבע\"פ בחי' מקבל למעלה מתושב\"כ המשפיע לפי שנתחב\"ס דוקא כמ\"ש סוף דבר כו', וע\"כ או' לקיים דברי תלמוד תורתך דוקא ואח\"כ והאר עינינו בתורתיך ודבק כו' וד\"ל. וזהו אשר יצוה את בניו לפי שבחי' חסד דאברהם ששמר כל המצות העליונות ברוחניות עי\"ז יש חיבור וקשר לעשות דרך [ל]הוי' למעלה להוסיף אור בע\"ס דאצי' (כמ\"ש בפ' לך לך<sup data-n=\"8317\">412</sup> ) וזהו ניתן בירושה גם לבנים<sup data-n=\"8318\">413</sup> וז\"ש ושמרו דרך הוי' שעל ידם יוכל להיות ג\"כ כל יחו\"ע הללו באצי'. אך העיקר הוא לעשות צדקה דמצות בעשי' גשמיות שזהו ע\"י ישראל דוקא שהרבה",[["8310","405","<b>וזרח משעיר למו </b>[או: ליתא]: ברכה לג, ב."],["8311","406","<b>שגם שהיו רוצים לקבל התו\"מ</b>: כ\"ה גם בהכת\"י."],["8312","407","<b>בשכבך תשמור עליך</b>: משלי ו, כב."],["8313","408","<b>ומצוה מגינא ומצלא</b>: ראה סוטה כא, א. וראה גם ש\"א יב, א. ובהנסמן במ\"מ לשם."],["8314","409","<b>כי אתה אבינו</b>: ישעי' סג, טז."],["8315","410","<b>כי אברהם לא ידענו וישראל</b>: המשך הכתוב כי אתה אבינו."],["8316","411","<b>א\"ח עט\"ב</b>: משלי יב, ד. ראה לעיל פ' וארא עב, א. מאמרי אדה\"א שמות ח\"ב ע' שעו. וש\"נ."],["8317","412","<b>דאברהם. . בפ' לך לך</b>: <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670306\" data-slug=\"torat-chaim\" data-id=\"2300670306\">תו\"ח לך פד, ג</a>."],["8318","413","<b>לבנים</b>: ו: לבנ\"י."]]],[2300540750,"להם תו\"מ בגשמיות שזהו עיקר בחי' הצדקה שאינה רק כשנתקבל במקבל בפו\"מ להחיות רוח שפלים כו', וכך כל המצות שנעשים ע\"י ישראל נק' צדקה בפו\"מ שנעשה ונמשך גילוי רצה\"ע הפנימי' בארץ דוקא, וז\"ש וצדקה תהי' לנו דוקא כי נשמור כו' וכמ\"ש והנגלות לנו<sup data-n=\"8319\">414</sup> דוקא כו', ובזה עיקר שלימות השפע דמשפיע צדקה וחסד זה שנק' צ\"ע המשפיע לתו\"מ כשיבאו למטה ממש כמ\"ש ה' חפץ למען צדקו ממש שלמעלה מהשפעה דצ\"ע בחסד <span data-k=\"pg\">488</span> ּ וטוב ורחמים להיות מחדש בטובו כל ההשתלשלו' כנ\"ל, עד דמבחי' ר\"ר העצמיי' שנמשך לישראל ע\"י תו\"מ בפו\"מ נמשך י\"ג מדה\"ר ביו\"כ גם לע\"ש כו' להיות טוב ה' לכל ורחמיו על כל מעשיו וד\"ל. וזהו שגם ישראל שנק' מקבלי' [ומקיימים ל]תו\"מ [מ\"מ] גם הם נק' בשם <sup data-n=\"8320\">415</sup>צדקה צדיקי' בחי' משפיעי' כמ\"ש ועמך כולם צדיקים<sup data-n=\"8321\">416</sup> לעולם ירשו ארץ שהוא ארץ החיים העליוני' דעוה\"ב לפי שקיימו כל התו\"מ בפו\"מ דוקא כמא' כ\"י יש להם חלק<sup data-n=\"8322\">417</sup> כו'<sup data-n=\"8323\">418</sup> לפי שישראל הן העושי' ומקיימי'<sup data-n=\"8324\">419</sup> למצות הרי הן בחי' צדיקי' שהוא בחי' משפיע לבחי' הצדקה, כדוגמא שהקב\"ה נק' צ\"ע כמ\"ש כי צדיק ה' צדקות אהב שהוא מה שמשפיע לאור בתו\"מ למטה כמ\"ש אור זרוע לצדיק<sup data-n=\"8325\">420</sup> כו' וכתיב אמרו לצדיק כי טוב כו' ואין טוב<sup data-n=\"8326\">421</sup> כו' שזהו מה שזורע צדקות דמצות, כך ישראל נק' צדיקי' בחי' משפיעי' מאחר שמקיימי' ועושי' למצות הללו להמשיך בחי' פנימי' רצה\"ע שבמצות העליונות ממש כמ\"ש אשר קדשנו במצותיו<sup data-n=\"8327\">422</sup> ממש כו' וד\"ל. וזהו הטעם שישראל נק' אחים וריעים להקב\"ה כמ\"ש למען אחיי וריעיי<sup data-n=\"8328\">423</sup> כו', וזהו לעשות צדקה לעשות לבחי' הצדקה כמו זורע צדקות<sup data-n=\"8329\">424</sup> כמ\"ש זרעו לכם לצדקה וקצרו<sup data-n=\"8330\">425</sup> כו' וכה\"ג וד\"ל.\n<b>ומעתה</b> יש להבין עדיין מה שגם תו\"מ שלנו בגשמיות נק' בשם צדקה ומשפט מהו ענין ובחי' המשפט שהוא בחי' הדין והיושר גם שכלול מחו\"ג כנ\"ל אבל אין בו לפנים משוה\"ד כלל, ומבואר למעלה שזהו ההפרש בין תו\"מ הרוחניות גם כמו שהן בשרשם בתורה הקדומה שבא בבחי' מדה ושיעור כמו במא' קו המדה שמודד כל אור כו' אף שהוא בבחי' ההתכללו' דחו\"ג כנ\"ל ובין תו\"מ שלנו בגשמיות שנק' בשם צדקה דוקא שבא מצד בחי' הר\"ר העצמיי' הנ\"ל כמ\"ש למען צדק\"ו ממש כו' כדי להיות לו דירה בתחתונים דוקא משום דנתחב\"ס דוקא כנ\"ל, וא\"כ למה א' לעשות צדקה ומשפט דקאי בתו\"מ הנגלות לנו לשמור ולעשות בפו\"מ דוקא, וכן מ\"ש משפט וצדקה ביעקב אתה עשית ביעקב דוקא כמ\"ש ויקם עדות ביעקב שזהו קיום המצות בפו\"מ איך נק' משפט שהוא בחי'",[["8319","414","<b>והנגלות לנו</b>: נצבים כט, כח."],["8320","415","<b>צדקה</b>: או: ליתא."],["8321","416","<b>ועמך כולם צדיקים</b>: ישעי' ס, כא."],["8322","417","<b>כ\"י יש להם חלק</b>: סנהדרין ר\"פ חלק (צ, א)."],["8323","418","<b>כו'</b>: ו: לעוה\"ב."],["8324","419","<b>ומקיימי'</b>: ו: ליתא."],["8325","420","<b>אור זרוע לצדיק</b>: תהלים צז, יא."],["8326","421","<b>ואין טוב</b>: ראה ס' האמונה והבטחון להרמב\"ן( ) ספ\"ב [אלא הקב\"ה]. יומא לח, ב [אלא צדיק]. ברכות ה, א [אלא תורה]."],["8327","422","<b>אשר קדשנו במצותיו</b>: נוסח ברכת המצות. ראה גם מאמרי אדה\"ז תקס\"ב ח\"א ע' קפו. דרך מצותיך ע' קסח."],["8328","423","<b>למען אחיי וריעיי</b>: תהלים קכב, ח."],["8329","424","<b>זורע צדקות</b>: ברכת יוצר."],["8330","425","<b>זרעו לכם לצדקה וקצרו</b>: נסמן לעיל פ' וארא פב, א."]]],[2300540762,"הדין היפוך בחי' הצדק\"ה כו' (ומ\"ש אתה עשית היינו אתה ממש מפני שמה שנמשך אור רצה\"ע דמצות למטה ממש שהוא מן ההעלם דעצמו' ממש לגילוי להיות לו דירה בתחתוני' דוקא זהו מבחי' מהו\"ע ממש מבחי' צדקתו ורחמנותו העצמי' ע\"כ א' משפט וצדקה ביעקב דוקא אתה בעצמך עשית שהוא להיות גילוי מהו\"ע ית' למטה דוקא כמו שיהי' לע\"ל בעוה\"ב בשכר המצות וע\"כ יאמרו לע\"ל כי אתה אבינו וכמ\"ש אבינו אב הרחמן כו' כנ\"ל וד\"ל). אך הנה באמת ידוע שגם התורה שלמטה נק' בשם משפט דוקא כמ\"ש בזהר עמ\"ש מלך במשפט יעמיד ארץ<sup data-n=\"8331\">426</sup> במשפט דאוריי' דוקא שנק' משפט כמו אלה העדות והחוקים והמשפטי'<sup data-n=\"8332\">427</sup>, וכן ואלה המשפטים אשר תשים<sup data-n=\"8333\">428</sup> כו', וא' משפטי ה' אמת<sup data-n=\"8334\">429</sup> כו', וכן כי כל דרכיו משפט כו' וכה\"ג רבות בכתובי', וע\"כ נק' שופט כל הארץ<sup data-n=\"8335\">430</sup> בדין ומשפט דתורה גם על ע\"ש דנוגה כו' כמא' יב\"ש הוי היום<sup data-n=\"8336\">431</sup> ג\"ש יושב ועוסק בתורה כו' ג\"ש יושב ודן את כל העולם שדין זה במשפט התורה<sup data-n=\"8337\">432</sup> דוקא, כמו שא' כי לא שלם עון האמורי<sup data-n=\"8338\">433</sup> כו' הרי דקדק <span data-k=\"pg\">רמד</span> ּ עליהם בדין ומשפט שבתורה, וכן בחטאת סדום, ובמצרים שא' ובכל אלקי מצרים אעשה שפטים<sup data-n=\"8339\">434</sup> כו', וכ\"ש על ישראל בכלל ובפרט עד שא' שאדם נידון בכל יום<sup data-n=\"8340\">435</sup> כו' שהוא בדין ומשפט דתורה דוקא. וגם להיות שאנו רואים בעצם אור החכמה דתורה בא' בבחי' משפט שהוא קו המשקולת<sup data-n=\"8341\">436</sup> לדון לחסד או לדין ובבחי' ממוצע שזהו בחי' הת\"ת כמא' והת\"ת זו מ\"ת<sup data-n=\"8342\">437</sup> כו' כנ\"ל שמדות דתו' באי' [בבחי' התכללות] בבחי' התיקון וכמו כל דיני התו\"מ באו\"ה טו\"ט כשר פסול חייב זכאי, שהכל הוא [ב]קו המשקולת שנמדד ונשקל במדות עליונות דח\"ע באופן ההמשכו' דחו\"ג לטו\"ט ואו\"ה באופן כך יהי' טהור ומותר וכשר ובאופן כך יהי' פסול וטמא כו' כמ\"ש יורו משפטיך ליעקב<sup data-n=\"8343\">438</sup>, שמפני זה נק' תור\"ה ל' הורא\"ה<sup data-n=\"8344\">439</sup> כמ\"ש להבדיל בין<sup data-n=\"8345\">440</sup> כו'. וכ\"ז בבחי' ה\"ג בל\"ת בסומ\"ר שכלול מחו\"ג וממוצע במדה ושיעור שהוא ע\"פ מא' קו המדה כמו גם בלאוי\"ן שאינם עפ\"י שכל וטעם כשעטנז וכלאים וכה\"ג שנק' חוקים, וכ\"ש במ\"ע בועשה טוב שגם שהן בבחי' ה\"ח בגילוי המשכת אלקו' למטה באו\"כ מקיפי' ופנימי' שנק' קדושה כמ\"ש אשר קדשנו במצותיו כו' גם זה ניתן במדה ושיעור דוקא כמו בדיני טו\"ת וסוכה ולולב ושבת ויו\"ט וכה\"ג, וגם במצות הצדקה עצמה הכל בדקדוק ושיעור כך וכך יוכשר",[["8331","426","<b>בזהר. . מלך במשפט יעמיד ארץ</b>: וכ\"ה בשם הזהר במאמרי אדה\"א בראשית ע' תל. שמות ח\"ב ע' תצא. ראה גם לעיל פ' שמות כב, א. פרשתינו קלד, ד. לקמן פ' משפטים רצא, ב. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670040\" data-slug=\"torat-chaim\" data-id=\"2300670040\">תו\"ח בראשית ז, ב</a> ובהערה 20."],["8332","427","<b>אלה העדות והחוקים והמשפטי'</b>: ואתחנן ד, מה."],["8333","428","<b>ואלה המשפטים אשר תשים</b>: משפטים כא, א."],["8334","429","<b>משפטי ה' אמת</b>: תהלים יט, י."],["8335","430","<b>שופט כל הארץ</b>: ע\"פ וירא יח, כה."],["8336","431","<b>יב\"ש הוי היום</b>: ראה ע\"ז ג, ב."],["8337","432","<b>ג\"ש יושב ודן. . במשפט התורה</b>: ראה גם לעיל פ' שמות כב, א. תו\"ח בראשית ז, סע\"א ואילך."],["8338","433","<b>כי לא שלם עון האמורי</b>: לך טו, טז."],["8339","434","<b>ובכל אלקי מצרים אעשה שפטים</b>: בא יב, יב."],["8340","435","<b>שאדם נידון בכל יום</b>: ר\"ה טז, א."],["8341","436","<b>קו המשקולת</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670435\" data-slug=\"torat-chaim\" data-id=\"2300670435\">תו\"ח (בראשית) יד, ד</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670453\" data-slug=\"torat-chaim\" data-id=\"2300670453\">טו, רע\"ב</a>. (<a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670383\" data-slug=\"torat-chaim\" data-id=\"2300670383\">לך) פו, ב</a>. (<a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670163\" data-slug=\"torat-chaim\" data-id=\"2300670163\">וירא) קי, ד</a>. ועוד."],["8342","437","<b>והת\"ת זו מ\"ת</b>: דהי\"א כט, יא. ברכות נח, סע\"א."],["8343","438","<b>יורו משפטיך ליעקב</b>: ברכה לג, י."],["8344","439","<b>תור\"ה ל' הורא\"ה</b>: ראה גם לעיל יא, א. וש\"נ."],["8345","440","<b>להבדיל בין</b>: שמיני יא, מז."]]],[2300540774,"למצוה וא\"ל אינה מצוה כלל וכמ\"ש מימינו א\"ש [ד\"ת] כו' שכלול מחו\"ג ע\"פ דקדוק ושיעור, ובכלל היינו ב' דברות דאנכי ולא יהי' שכלולי' מכל מ\"ע ול\"ת<sup data-n=\"8346\">441</sup>. ושרש הענין מבואר למעלה שכל עיקר ושרש הח\"ע דתורה בא' בבחי' בירור וצירוף דוקא כמ\"ש כל אמרת אלוה צרופה<sup data-n=\"8347\">442</sup> אל תוסף<sup data-n=\"8348\">443</sup> כו' ונק' חכ' ברורה מכבר וכמ\"ש במ\"א ע\"פ אי\"ה סופר אי\"ה שוקל כו' ולזה נק' בשם ס' הישר<sup data-n=\"8349\">444</sup>, וכן א' כי ישרים דרכי ה'<sup data-n=\"8350\">445</sup> כי ישר ה' כו' וכה\"ג שהוא בלי נטי' [ל]ימין ושמאל כלל, ואע\"פ שכל התורה היא לאכללא שמאלא בימינא<sup data-n=\"8351\">446</sup> כו', אמנם התכללות זו הוא במדה וגבול דוקא, (ואע\"פ שהתו\"מ כמו שהן למעלה במהו\"ע ית' נק' משל הקדמוני וכה\"ג הרי היא בלי גבול ומדה כלל כמ\"ש ארוכה מארץ מדה<sup data-n=\"8352\">447</sup> ורחב\"ה [מני ים] כו' וכן א' לכל תכלה <sup data-n=\"8353\">448</sup>כו' רחב\"ה מצות\"ך מא\"ד כו' עכ\"ז כשבאה למטה באבי\"ע באה במדה בשיעורי' וגבולי' דוקא כמ\"ש במ\"א) (ואע\"פ שמבואר למעלה שזהו דוקא בבחי' תורה הקדומה שנמשך במא'<sup data-n=\"8354\">449</sup> קו המדה כמו מי מדד כו' שעפי\"ז דוקא נמדד ג\"כ<sup data-n=\"8355\">450</sup> אופן התכללות דחו\"ג בע\"ס דאצי' באו\"כ מקיף ופנימי כו' כנ\"ל שזהו בראשית בשביל חש\"מ<sup data-n=\"8356\">451</sup> דוקא כמ\"ש דאסתכל באורייתא כו', הנה בהכרח לומר דמדה ושיעור זה ניתן גם בתורה שלמטה הנגלית לנו בעולם העשי' מאחר דאוריי' סתים וגליא<sup data-n=\"8357\">452</sup> שזהו בבחי' פנימי' וחיצוניות דאדם כמ\"ש וזאת תורת האד\"ם<sup data-n=\"8358\">453</sup> כידוע, א\"כ ודאי כמו שניתן שיעור ומדה באורות הפנימי' שהן ח\"ע ומדות עליונות דתש\"מ בבחי' פנימי' דאדם העליון באו\"כ דאצי' כך ניתן מדה זו עצמה בחיצוניות דאדם התחתון למטה בתו\"מ שלנו, כמו שמצות שלנו הן בבחי' דוגמא למצות העליונות שנק' רמ\"ח אברים דמלכא<sup data-n=\"8359\">454</sup> כידוע, כך התורה שלנו בבחי' חכ' ומדות דכשר ופסול כו' כדוגמא לתוש\"מ דאצי' ולמעלה בחי' <span data-k=\"pg\">490</span> ּ תורה הקדומה כו' וכמ\"ש במ\"א ע\"פ הרא[י]ני את מראי\"ך<sup data-n=\"8360\">455</sup> כו' וכמ\"ש אז ראה ויספר\"ה כו' ויאמר לאדם התחתון הן כו' בלי נטי' [ל]ימין ושמאל כלל וד\"ל (וראי' לזה ממה שכל מצות נק' בשם מצות הוי' ממש כמו שהוא למעלה ממש שנק' מצותי כו' וכן תורת הוי' משפטי הוי' כו' וכה\"ג, וכשפוגם ע\"י ביטול מ\"ע פוגם [בזה] בשם הוי' העליון ממש וכ\"ש בפגם דל\"ת שא' ולא תחללו את שם קדשי<sup data-n=\"8361\">456</sup> כו' וכמ\"ש הפושעים בי בגופא דמלכא<sup data-n=\"8362\">457</sup> ממש כו' לפי שאין לחלק כלל בין",[["8346","441","<b>דאנכי ולא יהי'. . מ\"ע ול\"ת</b>: נסמן לעיל פ' שמות יז, ג הערה 722."],["8347","442","<b>כל אמרת אלוה צרופה</b>: משלי ל, ה. ראה גם <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670435\" data-slug=\"torat-chaim\" data-id=\"2300670435\">תו\"ח בראשית יד, ד</a> ובהערה 49. שה\"א עד, ב. מאמרי אדה\"א נ\"ך ע' עא ואילך. לקמן פ' ויקהל תיז, א."],["8348","443","<b>אל תוסף</b>: משלי שם, ו."],["8349","444","<b>נק' בשם ס' הישר</b>: ראה גם לעיל י, ג. וש\"נ."],["8350","445","<b>כי ישר ה'</b>: תהלים צב, טז."],["8351","446","<b>התורה. . לאכללא שמאלא בימינא</b>: נסמן לעיל פ' בא קיח, ד."],["8352","447","<b>ארוכה מארץ מדה</b>: איוב יא, ט. ראה גם לעיל פ' שמות לו, ב. לקמן רלד, ג. פ' תרומה שיד, ב. סידור שער הציצית ה, ד. אמ\"ב שם פח, ב ואילך. וראה גם מאמרי אדה\"א במדבר ח\"א ע' קמח ואילך."],["8353","448","<b>כו'</b>: ו: ראיתי קץ."],["8354","449","<b>במא'</b>: ו: בבחי'."],["8355","450","<b>ג\"כ</b>: ו: כל."],["8356","451","<b>חש\"מ</b>: או: תש\"מ."],["8357","452","<b>דאוריי' סתים וגליא</b>: זהר אחרי עא, ב. עג, א."],["8358","453","<b>וזאת תורת האד\"ם</b>: ראה גם לעיל פ' שמות מו, ב. וש\"נ."],["8359","454","<b>למצות. . רמ\"ח אברים דמלכא</b>: נסמן לעיל מו, ב."],["8360","455","<b>הרא[י]ני את מראי\"ך</b>: שה\"ש ב, יד. ראה מאמרי אדה\"ז תקס\"ט ע' קט."],["8361","456","<b>ולא תחללו את שם קדשי</b>: אמור כב, לא."],["8362","457","<b>הפושעים בי בגופא דמלכא</b>: נסמן לעיל ו, ב."]]],[2300540785,"בחי' פנימי' לחיצוניות בתור\"ת האדם וע\"כ הוזהרנו בבל תוסיף ובל יגרע<sup data-n=\"8363\">458</sup> מן התו\"מ ימין ושמאל [כלל] רק כמו שהתו\"מ למעלה ממש מטעם הנ\"ל וד\"ל) (ואע\"פ שהתו\"מ באי' בבחי' ההשתל' דאבי\"ע ויש מסך מפסיק בין אצי' לבריאה<sup data-n=\"8364\">459</sup> עד עוה\"ז השפל אבל אין הצמצומי' ומסכים הללו מבדילים כלל לעשות שינוי בתו\"מ בתוס' וגרעון וראי' ממ\"ת שירד ה' על ה\"ס כו' וד\"ל), ואע\"פ שמבואר למעלה דתו\"מ שלנו בגשמיות דק\"נ כו' זהו בחי' שלימות האמיתי דח\"ע דתורה הקדומה כו' כמו משל שאין חכם כבעל הנסיון כו' כנ\"ל וע\"כ נק' בשם צדקה דוקא כו' כנ\"ל, הנה אדרבה מטעם זה ודאי יחייב יותר לומר שיהי' בחי' הבירור והצירוף ע\"פ דקדוק ושיעור ומדה דוקא בתו\"מ שלנו יותר מתו\"מ שלמעלה ברוחניות דאצי' ולמעלה כו', מאחר שבאה התורה<sup data-n=\"8365\">460</sup> למטה בהתלבשות בדברים גשמיי' בק\"נ לברר לעה\"ד טו\"ר שבודאי עיקר הבירור הוא להבדיל הרע מן הטוב בתכלית כדי שלא יהי' תוס' יניקה לחיצונים וע\"ז היסוד הן כל המצות ל\"ת כמו לא תאכל חו\"ד<sup data-n=\"8366\">461</sup> וכל מאכל אסור ולהבדיל מכל טומאה כמ\"ש להבדיל כו', וגם בבחי' המשכ' הקדושה דמ\"ע בא במדה ושיעור שבאופן זה דוקא יומשך הקדושה במצוה זו וא\"ל לא יומשך קדושה כלל שזהו בחי' בירור הטוב מן הרע בכלל כידוע, וכללות אופני הענין בבירור זה בעה\"ד טו\"ר שנק' טהרה וקדושה בסומ\"ר וע\"ט זהו ע\"פ בחי' הבירור הראשון דח\"ע דתוה\"ק דוקא רק שבבירור זה בעה\"ד למטה להיותו בא בסוף מעשה בגשמיות דנוגה עי\"ז נשלם שלימות דח\"ע מטעם הנ\"ל וד\"ל.\n<b>וזהו</b> הטעם שדוקא תו\"מ שלנו בגשמיות נק' משפט וצדק\"ה כמ\"ש משפט וצדק\"ה ביעקב כו', וכן א' לעשות חסד ומשפט וצדקה בארץ כו', דצדק\"ה הוא בחי' ה\"ח דרמ\"ח מ\"ע להיות לו דירה בתחתונים להמשיך גילוי אלקות במקום השפל דוקא כנ\"ל, ואמנם צ\"ל ע\"י בחי' משפט שהוא בחי' הדין והיושר במשקל ומדידה נכונה דוקא כדי שלא יתערב הרע בטוב ויקבלו גם החיצוני' יניקה מן הקדושה ויפגום אור הקדושה האלקי' כו', וזהו משפט וצדקה משפט תחלה בבחי' קו המדה דח\"ע הקדומה כמו שהתו\"מ הן למעלה בלי נטי' ימין ושמאל כלל כמו כי ישרים דרכי ה' כו', וכמ\"ש משפטי ה' אמ\"ת צדקו כו', ואח\"כ נמשך גילוי אלקות במצות שנק' צדק\"ה כנ\"ל, וכ\"ש במצות ל\"ת שזהו בחי' הטהרה לבער הרע ולהבדילו מן הטוב בתכלית כנ\"ל שהוא בבחי' ה\"ג דקו המדה כו' שצ\"ל בדקדוק יותר והן דקדוקי סופרים<sup data-n=\"8367\">462</sup> כו' ו[כ]גזירת י\"ח דבר<sup data-n=\"8368\">463</sup> וכה\"ג שעשו שמירה יתירה כידוע וד\"ל <span data-k=\"pg\">רמה</span> ּ (וזהו שבאברהם א' שיצוה לבניו ושמרו דרך הוי' לעשות צדק\"ה ומשפט, צדק\"ה תחלה ואח\"כ משפט, לפי שזהו בחי' הילוך אור השפע דתו\"מ העליוני' מעצמו' א\"ס לאצי' שנק'",[["8363","458","<b>בבל תוסיף ובל יגרע</b>: פ' ראה יג, א. ואתחנן ד, ב. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300141191\" data-slug=\"likkutei-sichot\" data-id=\"1300141191\">לקו\"ש</a> ה' מנ\"א (כרך יד) ע' 179 הערה 6."],["8364","459","<b>מסך מפסיק בין אצי' לבריאה</b>: נסמן לעיל פ' בא צו, ד."],["8365","460","<b>התורה</b>: ו: התו\"מ."],["8366","461","<b>לא תאכל חו\"ד</b>: ראה ויקרא ג, יז."],["8367","462","<b>דקדוקי סופרים</b>: סוכה כח, א."],["8368","463","<b>ו[כ]גזירת י\"ח דבר</b>: ראה שבת יג, ב."]]],[2300540796,"דרך להוי' ומאצי' לבי\"ע שז\"ש לעשות כו' שיהי' קשר וחיבור ליחו\"ע דאצי' במעשה המצות למטה כנ\"ל ע\"כ הזכיר צדקה תחלה שהן בחי' ה\"ח דמ\"ע שנמשכו מצד בחי' ר\"ר העצמיי' כנ\"ל וכמ\"ש למען צדק\"ו כו' ואח\"כ משפ\"ט לברר העה\"ד טו\"ר למטה (כמו אנכי תחלה ואח\"כ לא יהי' לך), וכן אז ראה ויספרה הכינה וגם חקרה במו\"ד עד שבא' התורה למעשה ויאמר לאדם כו' שזהו מלמעלה למטה מן המשפיע למקבל קדם מ\"ע לל\"ת כמ\"ש הן יראת ה' כו' וסומ\"ר בינה, אבל מלמטה למעלה א' תחלה סומ\"ר ואח\"כ ועשה טוב<sup data-n=\"8369\">464</sup> דטהרה קדם לקדושה, וכך הוא בקבלת התורה ומצות בכנ\"י למטה שזהו מלמטה למעלה א' משפט וצדקה ביעקב אתה עשי\"ת תחלה משפט בסומ\"ר דל\"ת ואח\"כ [וע\"ט] צדקה דמ\"ע (וז\"ש ועוז מלך משפט אהב<sup data-n=\"8370\">465</sup> כו' וד\"ל).\n<b>והנה</b> באמת אין כל זה מתיישב בפשט הכתוב במ\"ש צדקה ומשפט דמשמע שהן ענין א' ולא שהן ב' הפכים דחו\"ג כנ\"ל. ויש להקדים לזה שיש בצדקה בחי' משפט, דהנה הגם שבאה הצדקה מחמת ר\"ר ביותר להחיות רוח שפלים ויכול להשפיע כל אשר לו שלא ישאר לחיי עצמו כלום הנה הרי אמרו ע\"ז להיפך דחייך קודמי'<sup data-n=\"8371\">466</sup> לחיי חבירו ואין זה דין ודת התורה להניח חיי עצמו כדי להחיות חבירו כמו שא' שנים שהיו מהלכים בדרך<sup data-n=\"8372\">467</sup> ואין לא' רק קיתון א' של מים ישתו שניהם ימותו בצמא כו' ע\"ז א' חייך קודם לחיי חבירך, ולכאו' זהו נגד מדת הצדקה שהיא לרחם על חבירו יותר מעל עצמו, אלא צ\"ל שיש חילוק בזה דדוקא בענין חיי עצמו שצריך לחיות נפשו בלבד הוא שקודם לחיי חבירו ואין בזה דין הצדקה שימות הוא ברעב או [ב]צמא ויחי' לחבירו, אבל בבחי' המותרות על חיי נפשו כגון שיאכל לשובע או שיתענג במעדנים בבשר ויין ובבגדי כבוד ובפיזור הון על כו\"ז<sup data-n=\"8373\">468</sup> ומרגליות וכלי יקר ובנין היכלות ופלטרי' ולהתגדל בהרחבה, ע\"ז ודאי עיקר דין הצדקה שיניח כל המותרות על חיי נפשו ויתן לעניים להחיות רוח שפלים בלחם ולבוש כי ודאי הרי חיי נפש חבירו קודם לבחי' הוצאו' המותרות שמוציא על עצמו ובניו. וא\"כ צריך אדם לבא בדקדוק וחשבון ומשפט על כל מה שמוציא הוצאה יתירה על חיי נפשו המצומצם שזהו חלק העניים הצריכי' לפיקוח נפשם להחיותם ואין זה שלו כלל וצריך ליתן הכל לצדקה (אע\"פ שבדין הצדקה לא יבזבז יותר מחומש<sup data-n=\"8374\">469</sup> דאל\"כ לא ימצא מי שיהי' לו עושר וברכה לחיות חיי ריוח מאחר שגם העשירים צריכי' לחיות חיי צער כעני כו' אבל בנפשו יהי' בעיניו כעני שא\"צ רק להחיות את נפשו והמותר על חיי נפשו חיי חבירו קודם וכמו אברהם כו' (כמ\"ש במ\"א) שאברהם הי' מותר בעצמו והכל נתן לעניים), אבל זה ודאי אינו בדין עכ\"פ שיהי'",[["8369","464","<b>סומ\"ר. . ועשה טוב</b>: תהלים לד, טו."],["8370","465","<b>ועוז מלך משפט אהב</b>: התחלת הכתוב דמשפט וצדקה ביעקב אתה עשית (תהלים צט, ד)."],["8371","466","<b>דחייך קודמי'</b>: נסמן בהערה הבאה."],["8372","467","<b>שנים שהיו מהלכים בדרך</b>: ראה ב\"מ סב, א. אגה\"ק סט\"ז."],["8373","468","<b>כו\"ז</b>: כסף וזהב."],["8374","469","<b>לא יבזבז יותר מחומש</b>: כתובות נ, א. ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300271231\" data-slug=\"likkutei-sichot\" data-id=\"1300271231\">לקו\"ש בחוקותי (כרך כז) ע' 217</a> ואילך. וש\"נ."]]],[2300540806,"האדם מתענג בתענוג או\"ש<sup data-n=\"8375\">470</sup> ולבוש יקר ובית גדול ופיזור רב על מותרות כמרגליות וקישוטי היכלות ופלטרי' ולהתעדן בתפנוקי עלמא וחבירו ימות <span data-k=\"pg\">492</span> ּ ברעב ולא יהי' חיי חבירו יקרי' וחשובים בעיניו יותר מתענוגי' הגשמיי' שיתענג בהם להרחיב לבו, וכאשר יתבונן האדם וירגיש בחיי נפשות העניים הרי ודאי ידקדק ע\"ע במדת הדין ומשפט בנפשו היטב הדק שלא יסתפק ויוציא רק על מה שצריך מן ההכרח לחיי גופו וב\"ב בצמצום ולא יוציא בחי' מותרות כלל, רק מה שיוותר על סיפוק צרכיו יתן לצדקה להחיות רוח שפלים שהוא פיקוח נפשות או לדבר מצוה רבה כהספקת ת\"ח והוצאת בניו לת\"ת ומצות פ\"ש<sup data-n=\"8376\">471</sup> ועל מצות הכנסת כלה וכה\"ג. וא\"כ הרי צדקה זו היא באה במקום השפע' המותרות, וזהו עיקר מצות הצדקה שתלוי' במניעת המותרות, דמי שמתנהג בגד[ו]לות להוציא על מותרות גוזל בזה חיי העניים שהי' נותן כ\"ז לצדקה ומי שממעט המותרות ונותן לצדקה זהו שנק' בעל צדקה כידוע. ונמצא שעיקר בחי' הצדקה תלוי בבחי' משפט שהוא הדקדוק על עצמו לספק א\"ע בצמצום כדי הצריך לחיותו בלבד שנק' משפט כמו יכלכל דבריו במשפט וא\"כ המשפט וצדקה הכל א', ועל הרוב סיבת ריבוי המותרות באה מצד בחי' הרוממות וההתנשאות שמתנהג בגדולו' והרחבה ע\"כ אין הפיזור תופס מקום כלל ומשפיע גם למי שאינו ראוי כראוי ומוציא הוצאות על מותרות התענוגי' כנ\"ל, אבל מי שהוא במדת השפלות והענוה יכלכל עצמו במשפט בצמצום ומניח המותרות להחיות חיי שפלי' ולכל דבר מצוה וקדושה ולא ישפיע במקום שאינו נצרך עד שידקדק בשיעור וחשבון על כל דבר כו' וד\"ל.\n<b>והנמשל</b> ודוגמא מכ\"ז יובן למעלה בבחי' צדקה ומשפט העליון כו'. בהיות מבואר למעלה בשרש סיבת הצדקה למעלה שבאה מחמת התעוררות ר\"ר כו', ושרש הר\"ר בא מצד בחי' עצם הרוממות וההתנשאות עד שאין כל ההשתל' תופס מקום כלל וכלל וא\"כ הרי מחמת זה יכול להיות שאור חסד העליון יומשך ויצא גם לק\"נ, כמו דור אנוש היו ניזוני' בחסדו<sup data-n=\"8377\">472</sup> כו' משום דקמי' ממש כחשיכה כאורה<sup data-n=\"8378\">473</sup> כו' והכל שוין לפניו ממש בהעדר תפיסת מקום בשוה עליון על הכל עם התחתון מכולם כנ\"ל (שאין זה גם לא כערך הזבוב לגבי האדם<sup data-n=\"8379\">474</sup> כו'), וכמו שממית בידים תתפש<sup data-n=\"8380\">475</sup> והיא בהיכל[י] מלך שאינו תופס מקום כלל ויכול להיות שוה ומשוה הכל, וכמו שמטעם זה ביקש משה שלא תשרה שכינה כו', עד שגם הע\"ש דק\"נ מקבלים משם ממש בשוה עם פנימי' דקדושה כמו שמאברהם",[["8375","470","<b>או\"ש</b>: אכילה ושתי'."],["8376","471","<b>פ\"ש</b>: פדיון שבוים."],["8377","472","<b>דור אנוש היו ניזוני' בחסדו</b>: נסמן לעיל פ' שמות כד, ד."],["8378","473","<b>כחשיכה כאורה</b>: תהלים קלט, יב."],["8379","474","<b>לא כערך הזבוב לגבי האדם</b>: ראה גם לעיל קעא, ד. מאמרי אדה\"א שמות כאן (ס\"ע קיג). קונטרסים ע' רנא ובהנסמן בהנ\"ל."],["8380","475","<b>שממית בידים תתפש</b>: משלי ל, כח. ראה גם לעיל קלה, א. לקמן פ' פקודי תמב, ד. ש\"א מח, ב."]]],[2300540815,"יצא ישמעאל<sup data-n=\"8381\">476</sup> בחי' מותרי החסדי' דקדושה ומיצחק עשו<sup data-n=\"8382\">477</sup> כו' וא' לו ישמעאל יחיה לפניך<sup data-n=\"8383\">478</sup> וגם יצחק רצה לברך לעשו<sup data-n=\"8384\">479</sup> כו' (וכידוע בענין הצפרנים ושערות שהן מותרות דחו\"ג הפנימי' וע\"כ צריך נט\"י לצפרנים<sup data-n=\"8385\">480</sup> (וכמו שא' וגלחה את ראשה<sup data-n=\"8386\">481</sup> ועשתה את צפרני' כו') וגם גילוח שער בלוים<sup data-n=\"8387\">482</sup> שהן מבחי' הגבורות דקדושה), וכל שהרוממות בעצם יותר יותר ירבה שפע המותרות (וראי' מזמן הגלות דאסתלק למעלה<sup data-n=\"8388\">483</sup> ברוממות העצמות, משפיע בחי' ריבוי מותרות לע\"ש ונק' מלך הגוים<sup data-n=\"8389\">484</sup> וכמ\"ש במ\"א עמ\"ש אלביש שמים קדרו\"ת<sup data-n=\"8390\">485</sup> כו' וד\"ל). ולזה הטעם צ\"ל בחי' משפט למעלה שידקדק בשיעור וחשבון במשפט שלא יומשך בחי' מותרות כלל רק למקום הקדושה כמו רק בתו\"מ שישראל עושי' נמשך להם <span data-k=\"pg\">רמו</span> ּ בחי' ר\"ר הנ\"ל שנק' צדקה להחיות רוח שפלים כו' כנ\"ל, כמו שלמטה אדם מדקדק בבחי' מדת משפט בנפשו שלא ישפיע מותרות לחיצוני' חיות נפשו רק להחיות רוח שפלים ולדבר מצוה וקדושה כו', ועי\"ז יעורר האדם בחי' משפט זה גם למעלה שלא יומשך מרב חסד העצמו' בבחי' מותרות [לחיצוני'] כישמעאל ואדום בזמן הגלות כנ\"ל. וזהו עיקר בחי' צדקה למעלה שנמשך מבחי' צ\"ע שיש בזה מבחי' משפט דוקא שהוא לדקדק על דבר המותרות שבמקום זה יומשך בחי' הצדקה למי שצריך שהוא בסט' דקדושה דוקא כנ\"ל בצדקה ומשפט באדם למטה שבאתעדל\"ת נעשה אתעדל\"ע<sup data-n=\"8391\">486</sup> כידוע וד\"ל.\n<b>ובכ\"ז</b> יובן מטעם הנ\"ל למה הזכיר מדת משפט בצדקה כמ\"ש לעשות צדקה ומשפט לפי שהצדקה צ\"ל ע\"י בחי' משפט כדי שיומשך רק להחיות רוח שפלים זהו ע\"י בחי' משפט הוא הדקדוק בדין ומשפט שלא יומשך בחי' מותרות לחיצוני' כנ\"ל (וזהו שא' משפט וצדקה ביעקב דוקא אתה עשית מפני שבאתעדל\"ת נעשה אתעדל\"ע כנ\"ל ע\"כ צ\"ל ביעקב משפט קודם לצדקה שהוא מה שידקדק אדם בנפשו בבחי' משפט שלא ימש[י]ך בחי' מותרות שלא יעורר אתעדל\"ע להשפיע בחי' מותרות אלא להחיות רוח שפלים במקום מותרות כנ\"ל ומלמעלה למטה נק' צדקה ומשפט צדקה מחמת ר\"ר ואח\"כ משפ\"ט כנ\"ל וד\"ל) (אך<sup data-n=\"8392\">487</sup> עדיין אין זה מתיישב שהרי קריאת שם משפט קאי על התורה דוקא שנק' משפט אמת כנ\"ל והמצות נק' צדק\"ה, ולפי הנ\"ל אין משפט זה רק מניעת השפע דמותרות לבד שאין זה עיקר התורה כו'. ואמנם הנה באמת הרי מבואר במ\"א בענין שפע המותרות למעלה שזהו בא מחמת בחי' ההבדלה והבירור דוקא בין בחי' פנימי' לחיצוני' דשרש בחי'",[["8381","476","<b>שמאברהם יצא ישמעאל</b>: נסמן לעיל פ' בא קיז, ג."],["8382","477","<b>ומיצחק עשו</b>: נסמן לעיל שם."],["8383","478","<b>לו ישמעאל יחיה לפניך</b>: לך יז, יח."],["8384","479","<b>יצחק רצה לברך לעשו</b>: תולדות כז, ג ואילך."],["8385","480","<b>נט\"י </b>[ו: נטילה]<b> לצפרנים</b>: ראה סידור שער נט\"י ק, ג. מאמרי אדה\"א דברים ח\"ב ע' תקלח. וש\"נ."],["8386","481","<b>וגלחה את ראשה</b>: תצא כא, יב. ראה מאמרי אדה\"א שם ע' תקלא וע' תקלז."],["8387","482","<b>גילוח שער בלוים</b>: בהעלותך ח, ז. ראה ביאוה\"ז קרח צד, ג. מאמרי אדה\"א ויקרא ח\"ב ע' תנד. וש\"נ."],["8388","483","<b>מזמן הגלות דאסתלק למעלה</b>: נסמן לעיל פ' שמות לט, א הערה 72."],["8389","484","<b>מלך הגוים</b>: ירמי' י, ז. ראה גם לעיל פ' וארא סד, א."],["8390","485","<b>אלביש שמים קדרו\"ת</b>: ישעי' נ, ג. ראה גם לעיל קלה, ב."],["8391","486","<b>שבאתעדל\"ת נעשה אתעדל\"ע</b>: נסמן לעיל פ' שמות מא, א."],["8392","487","<b>(אך</b>: סיום הסוגר ראה להלן הערה 512."]]],[2300540824,"המותרות נמשך מבחי' החיצוני' דוקא. ואמנם גם זה אמת דמחמת עוצם הרוממות דוקא בא סיבת ריבוי המותרות כמו אהוריי[ר]' דר' עתיר<sup data-n=\"8393\">488</sup> כו' כמלך גדול שנמשך מותרות שלו היוצא בדרך פיזור יותר מהון רב דעשיר גדול שזהו לפ\"ע הרוממות כיד<sup data-n=\"8394\">489</sup> המלך כו' (וכן מותרות דחכ' הוא לפ\"ע ריבוי אור הפנימי' דחכ' כמשלי שלמה וכשיחת ת\"ח<sup data-n=\"8395\">490</sup> כו' וכה\"ג). אך גם בבחי' עצם רוממות העצמו' דא\"ס [ב\"ה] הובדל שם בחי' הפנימי' מן החיצוני' כידוע בענין נעילה דיו\"כ שהוא בחי' החותם<sup data-n=\"8396\">491</sup> כו' שיבחר בישראל כמו יבחר לנו<sup data-n=\"8397\">492</sup> כו' כמא'<sup data-n=\"8398\">493</sup> דישראל עלו במח' שזהו בבחי' פנימי' ועצמיות וע\"ש דנוגה<sup data-n=\"8399\">495</sup> בבחי' חיצוני'<sup data-n=\"8400\">494</sup> וע\"כ נמשך רב שפע מותרות לע\"ש כמא' מאריך אף<sup data-n=\"8401\">496</sup> כו' רק בחי' הפנימי' נמשך לישראל ע\"י תומ\"צ דוקא. וזהו שביקש משה שלא תשרה שכינה בע\"ש הגם דקמי' כחשיכה כו' כנ\"ל מצד בחי' ההבדלה הנ\"ל שז\"ש המבדיל בין קדש לחול בין אור לחושך<sup data-n=\"8402\">497</sup> כו'. ולפ\"ז הרי בחי' המותרות נבדל מן הפנימי' להיות בבחי' חיצוני' ואחוריי' וזהו חלקם וגורלם של ע\"ש כמ\"ש אשר חלק ה' כו', וא\"כ יש מזה לכאורה סתירה גדולה לענין הנ\"ל בפי' משפט למעלה שלא יומשך בחי' מותרות כלל כו'.\n<b>אך</b> הענין הוא דזהו באמת עיקר בחי' משפט למעלה שהוא בחי' ח\"ע דתוה\"ק הנ\"ל שהוא בחי' מקור להבדלה זו בין פנימי' לחיצוני' ושלא יומשך ריבוי מותרות בחיצוני' ביתר מכפי <span data-k=\"pg\">494</span> ּ המדה וכנ\"ל דגם שמצד עצם הרוממות הי' מאיר גם בחושך כמו באור כו' אבל שם דוקא הוברר ע\"פ חכ' העצמי' שלא יומשך בחי' מותרות רק בדקדוק ושיעור להיות קץ שם לחשך וכמ\"ש ויבדל בין האור ובין החשך<sup data-n=\"8403\">498</sup> כו', וזהו עיקר ענין כל התורה ש\"מ להיות בא במשפט דקו המדה למדוד כל פנימי' וחיצוני' כו' עד שלא יהי' שרש יניקה [ל]נוגה דאבי\"ע רק מחיצוני' דחיצוני' דכלים דע\"ס דאבי\"ע וגם זה במדה וגבול דוקא, והיינו כל ענין התורה שלמטה שנמשך האור הפנימי' דרצה\"ע בחכ' ומדות בדקדוקי' ושיעורי' בכלים מכלים שונים בלי נטי' ימין ושמאל להיות עי\"ז תכלית ההבדלה בין פנימי' לחיצוני' עד שלא יהי' צד יניקה לע\"ש דק\"נ רק במדה מבחי' אחוריי' דאחוריי' כו' שהן שרש ענין הל\"ת ודקדוקי סופרים כנ\"ל, ולישראל נמשך רק מבחי' הפנימי' ע\"י תו\"מ שלמטה ע\"כ באה התו\"מ בשיעור ודקדוק גדול מאד, וגם כל שפע חיותם החיצוני' אינו בא כ\"א ע\"י קיום התו\"מ בדקדוק כמו שהוא",[["8393","488","<b>אהוריי[ר]' דר' עתיר</b>: ב\"מ פה, א. שבת קיג, ב."],["8394","489","<b>כיד</b>: ו: ליתא."],["8395","490","<b>וכשיחת ת\"ח</b>: ראה סוכה כא, ב. הנסמן לקמן פ' משפטים רצא, ב."],["8396","491","<b>נעילה דיו\"כ. . החותם</b>: ראה פע\"ח (שער יוהכ\"פ) שער כז, פ\"ה. (שער הלולב) שכ\"ט, פ\"ד. לקמן רלג, ב. סידור שער יו\"כ רנ, ד. דרושים לחתונה קלה, ב. עט\"ר שער ר\"ה ע' יז."],["8397","492","<b>יבחר לנו</b>: תהלים מז, ב."],["8398","493","<b>כמא'</b>: ו: כמ\"ש במ\"א."],["8399","495","<b>דנוגה</b>: ו: ליתא."],["8400","494","<b>דישראל. . פנימי' וע\"ש דנוגה. . חיצוני'</b>: ראה גם לעיל קלה, א ובהערה 113."],["8401","496","<b>מאריך אף</b>: סנהדרין קיא, סע\"א."],["8402","497","<b>המבדיל בין. . אור לחושך</b>: נוסח הבדלה. ראה גם שע\"ת קיג, ג."],["8403","498","<b>ויבדל בין האור ובין החשך</b>: בראשית א, ד [בדילוג השם]."]]],[2300540833,"למעלה כמ\"ש אם בחוקתי תלכו<sup data-n=\"8404\">499</sup> אז דוקא ונתתי גשמיכם<sup data-n=\"8405\">500</sup> כו' וכן והי' א\"ש<sup data-n=\"8406\">501</sup> כו' וא\"ל וחרה אף<sup data-n=\"8407\">502</sup> כו' וכמ\"ש את הברכה<sup data-n=\"8408\">503</sup> כו' לפי שמקבלי' מבחי' הפנימי' דוקא, משא\"כ לע\"ש שאינם מקבלים רק מהחיצוני' כנ\"ל ולא ניתן להם התו\"מ וכמ\"ש אשר חלק כו' ונמשך להם השפע שלא ע\"פ התורה מבחי' המותרות אבל דוקא במדה וגבול (כמו בע' פרי החג<sup data-n=\"8409\">504</sup> שמקבלים מחיצוני' דקרבנות החג) (וכמ\"ש בזהר בענין שעיר המשתלח<sup data-n=\"8410\">505</sup> ובענין קוצא דשערי דתפילין<sup data-n=\"8411\">506</sup> ), וכמ\"ש הללו את ה' כל גוים<sup data-n=\"8412\">507</sup> כי גבר עלינו דוקא חסדו ע\"כ יוצא גם להם בחי' מותרות ועכ\"ז ואמת ה' בחי' הפנימי' דאמיתת אור העצמו' הוא לישראל דוקא כמ\"ש בכמה מקומות כמו יאר ה' פניו אליך דוקא ישא ה' פניו אליך<sup data-n=\"8413\">508</sup> דוקא דבחי' פניו היינו בחי' הפנימי'<sup data-n=\"8414\">509</sup> הוא מאיר אליך דוקא, וכן בי\"ג מדה\"ר שהוא מבחי' הפנימי' דרעוא דכ\"ר כו' וכתי' ויעבור ה' על פניו ויקרא כו' שנמשך ביו\"כ לישראל דוקא, והוא מצד בחי' ר\"ר העצמיי' הנ\"ל כרחמי האב על הבן כו' כנ\"ל כמ\"ש ה' חפץ למען צדקו מחמת ר\"ר הנ\"ל הרבה להם דוקא תו\"מ כו' וד\"ל (וזה הי' בזמן בהמ\"ק דוקא אבל בזמן הגלות נמשך לע\"ש ריבוי המותרות שלא ע\"פ דקדוק ומשפט דתוה\"ק הנ\"ל מצד שאין בירור והבדלה למעלה ע\"י תוש\"מ מאחר שעברו על התו\"מ למטה ונבל\"ע ישראל בגוים<sup data-n=\"8415\">510</sup> לקבל מהם ועל ידם השפע כו' שזהו ענין גלות השכינה בע\"ש שא' אשר שלט האדם<sup data-n=\"8416\">511</sup> באדם לרע לו כו' להוציא בלעו מפיו כו' כמ\"ש במ\"א). ובזה יתורץ הקושיא הנ\"ל במ\"ש צדקה ומשפט דשם משפט זה קאי על התורה דוקא שעי\"ז יהי' מניע' השפע דמותרות להיות רק במדה וצמצום בחיצוני' דחיצוני' דוקא, והכל עולה לסגנון א' עם הנ\"ל בפי' ענין משפט וד\"ל<sup data-n=\"8417\">512</sup>).\n<b>ובזה</b> יובן יותר המשך הפסוק הזה דמשפט וצדקה ביעקב כו' דמתחלה א' ועוז מלך משפט אהב שהוא בבחי' מל' דא\"ס לפני הצמצום דקו\"ח ששם הוא בחי' עוז מלך בבחי' רוממות והתנשאות דמצד עצמו ממש כנ\"ל (ולמעלה יותר הוא במהו\"ע ית' ממש שלמעלה גם משה\"ש כנ\"ל), שהוא אוהב משפט דתוה\"ק <span data-k=\"pg\">רמז</span> ּ להיות בחי' בירור והבדלה בין פנימי' לחיצוני' ולהיות נמשך הפנימי' בבחי' ההתכללות דחו\"ג במיצוע טוב שנק' ישר כמ\"ש למעלה באריכות. וז\"ש אתה כוננת מישרי\"ם<sup data-n=\"8418\">513</sup> דוקא כי כבר כוננת בחי' מישור ומיצוע בדרכי ה' דמצות העליונות כמ\"ש אז ראה ויספר\"ה כו' כנ\"ל, ומפני בחי' ר\"ר העצמיי' לישראל",[["8404","499","<b>אם בחוקתי תלכו</b>: בחוקותי כו, ג."],["8405","500","<b>ונתתי גשמיכם</b>: בחוקותי שם, ד."],["8406","501","<b>והי' א\"ש</b>: עקב יא, יג."],["8407","502","<b>וחרה אף</b>: שם יא, יז."],["8408","503","<b>את הברכה</b>: פ' ראה יא, כז."],["8409","504","<b>בע' פרי החג</b>: סוכה נה, ב."],["8410","505","<b>בענין שעיר המשתלח</b>: ראה זהר אמור קא, ב ואילך. מאמרי אדה\"ז תקס\"ב ח\"א ע' לח וע' מא. ד\"ה ביום השמ\"ע תקס\"ב ס\"ד (לא נדפס לע\"ע). מאמרי אדה\"א נ\"ך ע' תקיג וש\"נ."],["8411","506","<b>קוצא דשערי דתפילין</b>: נסמן לעיל פ' בא קכז, א."],["8412","507","<b>הללו את ה' כל גוים</b>: תהלים קיז, א."],["8413","508","<b>ישא ה' פניו אליך</b>: נשא ו, כו."],["8414","509","<b>פניו. . הפנימי'</b>: נסמן לעיל פ' בא קכז, ב."],["8415","510","<b>ונבל\"ע ישראל בגוים</b>: נסמן לעיל קלד, א."],["8416","511","<b>אשר שלט האדם</b>: נסמן לעיל פ' שמות ל, ד."],["8417","512","<b>וד\"ל)</b>: התחלת הסוגר ראה לעיל הערה 487."],["8418","513","<b>אתה כוננת מישרי\"ם</b>: המשך הכתוב ועוז מלך — תהלים צט, ד."]]],[2300540842,"שנק' בנים חפץ למען צדקו כו' ע\"כ משפט וצדקה שהן התו\"מ שלמטה אתה עשית בעצמך שיהי' בהם כח ועוז לברר לעה\"ד טו\"ר ממש בסומ\"ר כו', שזהו לברר לרפ\"ח ניצוצי'<sup data-n=\"8419\">514</sup> שנפלו למטה ממש בק\"נ שזהו לאהפכא חשוכא כו' ולאכפייא כו' שעי\"ז נעשה שלימות האמיתי למעלה בחשמ\"ע<sup data-n=\"8420\">515</sup> כנ\"ל, ע\"כ הזכיר משפט תחלה כדי לעורר למעלה בבחי' צדקה דמצות למעלה שבאה מחמת ר\"ר שיהי' נמשך במשפט דקו המדה עפ\"י התוה\"ק שלא יומשך מותרות רק בגבול ושיעור (ומלמעלה למטה הזכיר צדקה קודם [למשפט] שמפני בחי' ר\"ר בעצם הרוממו' יומשך גם בחיצוני' כמו בפנימי' (כנ\"ל דהר\"ר הללו שבמהו\"ע ממש שוה ומשוה גיאות והתנשאות דעומ\"ר עם שפלות דעומ\"ת לפי ששוין לפניו ממש אך ע\"י בחי' משפט משפיל א\"ע לעשות צדקה לשפלי' דוקא ולהשפיל גיאי' כו' (כמשי\"ת). וזהו שאנו או' בש\"ע מלך אוהב צדקה ומשפט שזהו מלמעלה למטה ומשם נמשך לעשות משפט וצדקה ביעקב דוקא, לפי שבחי' פנימי' זאת דר\"ר העצמיי' הנ\"ל שנעשה במשפט דתוה\"ק הנק' צדק\"ה העליונה לא נמשך רק ביעקב דוקא כנ\"ל כמ\"ש יאר ה' פניו אלי\"ך דוקא דגם בעצם הרוממו' הובררו להיות בבחי' הפנימי', וגם שעל ידם יוברר גם מבחי' החיצוני' לפנימי' שהוא בחי' המותרו' דע\"ש דנוגה (כמו כל דבר מותר וכשר וטהור שיעלה למעלה לקרבנו' וכה\"ג במצות הנעשי' כטו\"ת בקלף וצמר גשמי וכן סוכה ולולב וגם כל יגיעת האדם בפרנסה בלחם ולבוש יעלה הכל למעלה רק האסור והטמא וגזל וכה\"ג יובדל כו', וגם מהרע עצמו כטמא יטהר כמו בע\"ת האמיתי' כידוע שזהו היפוך החשך עצמו לאור שלמעלה יהופך גם בחי' החשך העליון לאור שלמעלה ממשפט דתורה המבדיל הנ\"ל וד\"ל).\n<b>ובכ\"ז</b> יובן ג\"כ יותר המשך דברי הפסוק הנ\"ל במ\"ש באברהם כי ידעתיו אשר יצוה את בניו כו' לעשות צדקה ומשפט למען הביא על אברהם את אשר דבר עליו, ותחלה א' ואברהם היו יהי'<sup data-n=\"8421\">516</sup> לגוי גדול ועצום ונברכו בו כל גויי הארץ כי ידעתיו למען אשר יצוה את בניו כו', דהנה ידוע בשרש בחי' אברהם למעלה שהי' לבבו נאמן לפני ה' בנסיונות ובפרט אחר המילה שכרת עמו הברית לתת לזרעו<sup data-n=\"8422\">517</sup> ז' אומות<sup data-n=\"8423\">518</sup> דא\"י כו', לפי שהוא בחי' ה\"ח המגולי' בחסד בה\"א דאברה\"ם שנגלה בו מבחי' פנימי' ועצמו' דא\"ס ב\"ה שנמשך בקו\"ח בבחי' הגילוי [מן ההעלם] להיות קשר וחיבור תמיד מעצמות המאציל בע\"ס",[["8419","514","<b>לרפ\"ח ניצוצי'</b>: נסמן לעיל פ' שמות לו, ג."],["8420","515","<b>בחשמ\"ע</b>: או: בתשמ\"ע."],["8421","516","<b>ואברהם היו יהי'</b>: וירא יח, יח."],["8422","517","<b>אחר המילה שכרת עמו הברית לתת לזרעו</b>: ראה תו\"ח ח\"ש קכה, ג: (נחמי' ט, ז-ח) אתה. . בחרת באברם כו' ושמת שמו אברהם. . לבבו נאמן לפניך ע\"י מילה. . שעי\"ז וכרות עמו הברית לתת את ארץ הכנעני. ראה לך יז, ח. בחיי שם פסוק כד. כד הקמח מצות מילה בסופה. וראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370534\" data-slug=\"torah-or\" data-id=\"3901370534\">תו\"א מג\"א קיט, ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1301670107\" data-slug=\"likkutei-sichot\" data-id=\"1301670107\">לקו\"ש לך (כרך לה) ע' 45</a> ואילך ובהנסמן שם."],["8423","518","<b>ז' אומות</b>: וכ\"ה בתו\"א וב<a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670145\" data-slug=\"torat-chaim\" data-id=\"2300670145\">תו\"ח שם</a>. מאמרי אדה\"ז תקס\"ב ח\"א ע' קסח. דר\"מ צה, א. בנחמי' שם נזכרו ו' אומות. וראה גם סידור יעב\"ץ בתפלת שחרית (ויברך דוד) החוי לא נזכר כאן. כי הם הגבעונים. . וכרתו להם ברית להניחם בארצם."]]],[2300540851,"דאצי' בכל בחי' יחו\"ע דתו\"מ העליוני' שבקו המדה בבחי' ההתכללו' דתיקון כמ\"ש ששמע בקולי וישמור<sup data-n=\"8424\">519</sup> מצותי חוקתי כו' (שזהו כל עיקר ענין ס' בראשית שנק' ס' הישר שהוא מקור לתו\"מ הנגלות בס' האחרי' כמ\"ש בפ' לך לך<sup data-n=\"8425\">520</sup> ובפ' ח\"ש<sup data-n=\"8426\">521</sup> ), וממנו נמשך בירושה לבנ\"י להיות על ידו קשר וחיבור דתו\"מ הרוחניי' לבא בהתלבשות למטה בגשמיות עד שיהיו הכל בבחי' הבדלה הנ\"ל גם בעולם העשי' להיות <span data-k=\"pg\">496</span> ּ יניקה לע\"ש מחיצוני' הכלים דע\"ס דעשי', וזהו ע\"י קיום התו\"מ בא\"י דוקא שהוא מה שכרת עמו הברית ליתן לזרעו ז' אומות דא\"י שהוא לברר לז\"מ דתהו שהי' בהן [בחי'] השבירה ונפילה דרפ\"ח ניצוצי' כו' בבחי' ב\"ן דנוגה ובקיום התו\"מ בא\"י<sup data-n=\"8427\">522</sup> נתבררו ונמשך משם השפע לכל הע\"ש כנ\"ל וד\"ל. וז\"ש ואברהם היו יהי' לגוי גדול ועצום באמצעות הבירור דרפ\"ח כו' בא\"י<sup data-n=\"8428\">523</sup> ונברכו בו כל כו' ומפרש האיך יהי' זה, ואו' כי ידעתיו למען אשר יצוה את בניו ואת ביתו אחריו ושמרו דרך הוי' ביחו\"ע דאצי' ומאצי'<sup data-n=\"8429\">524</sup> לבי\"ע עד קיום התו\"מ בפו\"מ לעשות צדק\"ה ומשפט בבחי' הבירור והתיקון בעה\"ד טו\"ר בתכלית שנעוץ תחב\"ס דוקא כנ\"ל וד\"ל. וזהו למען הביא ה' על אברהם את אשר דיבר עליו והיכן דיבר עליו הוא שא' לו והקימותי את בריתי ביני<sup data-n=\"8430\">525</sup> כו' ונתתי לך ולזרעך אחריך<sup data-n=\"8431\">526</sup> כו' את כל ארץ כנען לאחוזת עולם כו' שהוא א\"י בשלימות הבירורי' דרפ\"ח כו' מז' אומות כנ\"ל, שעי\"ז דוקא יהי' שלימות האמיתי דעוה\"ב בשכר המצות לע\"ל בא\"י דוקא כמ\"ש ועמך כולם צדיקי' במצות בפו\"מ ע\"כ לעולם ירשו ארץ שהוא בחי' ארץ החיים<sup data-n=\"8432\">527</sup> בעוה\"ב שנק' ארץ חפץ כו', וזהו אשר דיבר עליו שתהי' א\"י לאחוזת עולם בעוה\"ב והוא שנק' ברכת אברהם דוקא כמ\"ש יצחק ליעקב דוקא ויתן לך את ברכת אברהם<sup data-n=\"8433\">528</sup> כו' (כמ\"ש בפ' תולדות<sup data-n=\"8434\">529</sup> ) וזה הי' כשציוה לו על המילה וא\"ל והי' שמך אברהם כי אב המון גוים כו'. וזהו שאו' אחר וכרות עמו הברית כו' ותקם את דבריך<sup data-n=\"8435\">530</sup> כי צדיק אתה, פי' צדיק כמ\"ש כי צדיק ה' צדקות אהב כו' שזהו בחי' אור הזרוע לצ\"ע [ב]מצות שנק' צדקה והוא בחי' שם מ\"ה דמברר לב\"ן<sup data-n=\"8436\">531</sup> ע\"י תו\"מ שעי\"ז נק' ישראל ג\"כ צדיקים כמ\"ש ועמך כולם צדיקי' שיורשים הארץ בחי' שם ב\"ן<sup data-n=\"8437\">532</sup> כו' (וד\"ל כמשי\"ת), ומפני כי צדיק אתה כמ\"ש ה' חפץ למען צדקו בבחי' ר\"ר העצמיי' הנ\"ל ע\"כ ותק\"ם את דברי\"ך להוריש לבנ\"י ז' האומות כו' שהוא בירור דרפ\"ח מעולם התהו שז\"ש ותקם שהקים דב\"ר הנופ\"ל<sup data-n=\"8438\">533</sup> (כמ\"ש במ\"א).",[["8424","519","<b>ששמע בקולי וישמור</b>: תולדות כו, ה [ושם: עקב אשר שמע אברהם בקולי וישמור משמרתי]."],["8425","520","<b>בפ' לך לך</b>: <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670306\" data-slug=\"torat-chaim\" data-id=\"2300670306\">תו\"ח שם פד, סע\"ג</a> ואילך."],["8426","521","<b>ובפ' ח\"ש</b>: תו\"ח שם קלה, סע\"א ואילך."],["8427","522","<b>ובקיום התו\"מ בא\"י</b>: ראה רמב\"ן תולדות כו, ה. אחרי יח, ה. ואתחנן ד, ה. וראה גם הנסמן במאמרי אדה\"א קונטרסים ע' רסו. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670088\" data-slug=\"torat-chaim\" data-id=\"2300670088\">תו\"ח בראשית ח, א</a>. ובהערה 9."],["8428","523","<b>בא\"י</b>: ו: באמרו."],["8429","524","<b>דאצי' ומאצי'</b>: ו: דעצמו' המאציל."],["8430","525","<b>והקימותי את בריתי ביני</b>: לך יז, ז."],["8431","526","<b>ונתתי לך ולזרעך אחריך</b>: שם יז, ח."],["8432","527","<b>ארץ החיים</b>: נסמן לעיל פ' שמות ז, א."],["8433","528","<b>ויתן לך את ברכת אברהם</b>: תולדות כח, ד."],["8434","529","<b>כמ\"ש בפ' תולדות</b>: ראה <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680272\" data-slug=\"torat-chaim\" data-id=\"2300680272\">תו\"ח תולדות קנג, ב</a>. קסב. א."],["8435","530","<b>ותקם את דבריך</b>: נחמי' ט, ח."],["8436","531","<b>שם מ\"ה דמברר לב\"ן</b>: נסמן לעיל ד, ב."],["8437","532","<b><a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680190\" data-slug=\"torat-chaim\" data-id=\"2300680190\">הארץ בחי' שם ב</a>\"ן</b>: ראה גם לקמן פ' ויקהל תטו, א. מאמרי אדה\"ז תקס\"ה ח\"א ע' קט (נוסחא שני'). מאמרי אדה\"א בראשית ע' שז. ויקרא ח\"ב ע' תצד. דברים ח\"ג ע' תתקיג. תו\"ח וישב רז, א."],["8438","533","<b>ותקם שהקים דב\"ר הנופ\"ל</b>: ראה מאמרי אדה\"א שמות ח\"ב ע' תקנו."]]],[2300540860,"<b>אך</b> עדיין י\"ל מ\"ש אשר דיבר עליו מהו לשון עלי\"ו למעלה ממנו שהוא ענין עליי' גדולה לשרש נשמת אברהם למעלה ממקור חוצבו הרבה (וכמ\"ש אנכי מג\"ן לך<sup data-n=\"8439\">534</sup> שכרך הרבה מאד ונק' מגן אברהם<sup data-n=\"8440\">535</sup> ), הענין הוא כידוע בשרש בחי' אברהם שהי' עבודתו באוי\"ר בהתכללות שהוא בחי' רו\"ש כמ\"ש התהלך לפני<sup data-n=\"8441\">536</sup> כו', ופי' התהלך זהו בחי' רו\"ש בדביקות והתלהבות הנפש וחוזר ושב בבחי' המשכו' האור בכלי וזה הי' ענין המסעות שלו בארץ כנען דוקא כמ\"ש הלוך ונסוע הנגבה<sup data-n=\"8442\">537</sup> וא' בזהר שהי' הולך מדרגא לדרגא בעילוי אחר עילוי כו' והכל בבחי' רו\"ש<sup data-n=\"8443\">*538</sup> דוקא, ואמנם אוי\"ר ברו\"ש זה הי' בקיום תו\"מ ברוחניות בעובדות שלו בא\"י דוקא כמ\"ש וישמור משמרתי מצותי כו' שזהו בחי' צדקה ומשפט שיצוה את בניו ושמרו כו' שיעשו בגשמיות כנ\"ל שע\"י ירושה זו דוקא יש קשר וחיבור מרוחניות דיחו\"ע במצות מעשיות להיות נתחב\"ס כו', ומפני דאוי\"ר זו שבבסוף מעשה בתו\"מ יגיע למעלה הרבה מאוי\"ר בדביקות והתלהבות שהי' לאברהם בעצם שרש<sup data-n=\"8444\">538</sup> נשמתו מטעם המבואר למעלה שע\"י תו\"מ <span data-k=\"pg\">רמח</span> ּ דוקא תעלה הנשמה לידבק במהו\"ע ית' שנק' אדון הנפלאות סדכ\"ס כו' שלא תגיע לזה ע\"י כל דביקות באוי\"ר במס\"נ כו', לזאת זכה אברהם ע\"י קיום המצות ברוחניות באוי\"ר להעלות נפשו ביתרון מעלה הרבה משרש נשמתו באור החכ' וחסד דאצי' שמשם שרש מדריגת האוי\"ר דנשמתו (וכמו שכר המצות באוי\"ר בעוה\"ב שהוא גילוי אור העצמו' ממש שאינו בא רק ממצות מעשיות בפו\"מ דוקא) וזהו למען הביא ה' על אברהם את אשר דיבר עליו להעלותו למעלה משרשו הראשון וד\"ל.\n<b>והנה</b> הגם שמצות הצדקה בגשמיות להחיות רוח שפלים שקולה כנגד כל המצות<sup data-n=\"8445\">539</sup> לפי שכוללת כל המצות שמטעם זה נק' כללות המצות בשם צדקה כמ\"ש לעשות צדקה וכן וצדקה תהי' לנו כו', אבל באמת גם בכל מצוה ומצוה בפרט יש בחי' הצדקה שבכללות המצות ונק' ג\"כ כל מצוה בפרט בשם צדקה כמו צדקה תרומם גוי, הרי ע\"י מצות צדקה בפרט תרומם גוי, וכך [גם] ע\"י מצוה א' בפרט וכמ\"ש אני בצדק אחזה פניך<sup data-n=\"8446\">540</sup> כך גם ע\"י מצוה א' אחזה פניך, לפי שאין לחלק בין הפרט לכלל בענין המצות במה שנק' [בשם] צדקה כמ\"ש בצדקה תכונני<sup data-n=\"8447\">541</sup> כו', ומטעם זה כמו שהמקיים כל המצות נק' בשם צדיק שהוא העושה הצדקה כמו כי צדיק ה' צדקות אהב",[["8439","534","<b>אנכי מג\"ן לך</b>: לך טו, א."],["8440","535","<b>מגן אברהם</b>: ראה גם לעיל פ' וארא סב, ב. וש\"נ."],["8441","536","<b>התהלך לפני</b>: לך יז, א. ראה מאמרי אדה\"א ויקרא ח\"ב ע' תשפ."],["8442","537","<b>הלוך ונסוע הנגבה</b>: לך יב, ט. ראה זהר שם פ, א. פד, א."],["8443","*538","<b>הלוך ונסוע. . רו\"ש</b>: ראה גם מאמרי אדה\"ז תקס\"ה ח\"ב ע' תרל. ע' תרלז. ע' תרמג. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370327\" data-slug=\"torah-or\" data-id=\"3901370327\">תו\"א יתרו עג, ד</a>. לקמן פ' פקודי תמט, א."],["8444","538","<b>בעצם שרש</b>: או: בשרש עצם."],["8445","539","<b>הצדקה. . שקולה כנגד כל המצות</b>: ב\"ב ט, א."],["8446","540","<b>אני בצדק אחזה פניך</b>: תהלים יז, טו."],["8447","541","<b>בצדקה תכונני</b>: ישעי' נד, יד."]]],[2300540869,"כך כ\"י נק' צדיקים כמ\"ש ועמך כולם צדיקים ואע\"פ שאחד מישראל א\"א שיקיים כל המצות<sup data-n=\"8448\">542</sup> כמו ישראל במצות כהונה שאינו כהן וכה\"ג, וא\"כ מה שנק' כאו\"א מישראל בשם צדיק כמ\"ש ועמך כולם צדיקים זהו מפני שא\"א שלא יקיים א' מישראל אחת מן המצות כמצות ק\"ש ותפילין ומצות מילה יש בכאו\"א שמטעם זה גזרו אומר דכ\"י יש להם חלק לעוה\"ב אפי' פ\"י [לפי] שמלאים מצות<sup data-n=\"8449\">543</sup> כו' ונק' צדיקי' לעוה\"ב כו' וד\"ל.\n<b>ולהבין</b> טעם הדבר הנה ידוע בשרש ענין המצות למעלה שהן בבחי' ציור אדם כמ\"ש בזהר דרמ\"ח פקודין נק' רמ\"ח אברי' דמלכא וכמארז\"ל ועשיתם אותם כאילו עשאוני<sup data-n=\"8450\">544</sup> ברמ\"ח אברים כו', וביאור הענין הנה עד\"מ האברים הם בחי' כלים מוגבלים להכיל האור וחיות הנפש בכל אבר לפי מזגו ותכונתו ובלתי האור וחיות אין לו קיום במציאות כלל, ובהכרח ש[י]הי' התלבשות חיות הנפש בהן בתמידות ועי\"ז הן חיים וקיימים ובהסתלקות האור וחיות הרוחני שבדם הוא הנפש נשארו כדומם בלי חיות כלל כמו הסתלקות הצורה מן החומר כידוע, כך הוא ענין המצות שהם בחי' כלים לאורות העליונים כמו אברי האדם לגבי אור וחיות הנפש כמו ע\"י מצות צדקה וחסד ביד הוא בחי' הכלי לאור וחיות המלובש ביד, כך למעלה זהו בחי' כלי לחסד דאצי' להיות האור דחסד דאצי' מלובש בכלי ונק' דרועא ימינא<sup data-n=\"8451\">545</sup> דקוב\"ה כו', והוא בחי' הארת אא\"ס שבע\"ס דאדם העליון דאצי' שמאיר בכלי החסד בבחי' יד ימין כמו ימין ה' רוממה<sup data-n=\"8452\">546</sup> כו', וכל המצות שהן בבחי' החסד כלולים בקו הימין הזה דחח\"ן כידוע וד\"ל. ועד\"ז כל המצות שהן בחי' כלים בכלל לאור הגבו' דאצי' נק' בחי' דרועא שמאלא בכלל שזהו בבחי' קו השמאל דבג\"ה דאצי', וכל המצות שכלולים מחו\"ג שזהו בבחי' הת\"ת הן בחי' כלים לאורות דת\"י דקו האמצעי וזהו ענין ג' דברים שהעולם עומד עליהם<sup data-n=\"8453\">547</sup> כו' כמ\"ש במ\"א וד\"ל. וזהו שנק' המצות בכלל בשם צדקה להיות שעל ידם <span data-k=\"pg\">498</span> ּ נמשך בחי' האור והחיות דעצמות אור הא\"ס בג' קוין דאדם דאצי' שזהו בחי' ירידה ושפלות להחיות רמ\"ח אברים כו' כמו בדוגמא במצות שלמטה שאדם התחתון עושה דכתיב אלה המצות אשר יעשה אותם האדם וחי בהם<sup data-n=\"8454\">548</sup> דהיינו מבחי' אור וחיות האלקי ש[י]איר באור בכלי בנר\"נ שבו ואם חסר מצוה א' חסר אור וחיות לאבר א'<sup data-n=\"8455\">*549</sup> כו' כמ\"ש במ\"א, וא\"כ גם העושה מצוה א' נק' צדקה בפרט ומי שעושה המצות נק' בשם צדיק",[["8448","542","<b>שאחד מישראל א\"א שיקיים כל המצות</b>: ראה הל' ת\"ת לאדה\"ז פ\"א, ה\"ד. מאמרי אדה\"ז תק\"ע ע' קמו וע' קסא. אוה\"ת ש\"ש ע' ב'קטו. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300181201\" data-slug=\"likkutei-sichot\" data-id=\"1300181201\">לקו\"ש קרח (כרך יח) ע' 192</a> ובהערה 55. מסעי ע' 415 הערה 39. י\"ב י\"ג תמוז (כרך ב) ע' 590. וראה גם קרית ספר להמבי\"ט בהקדמה פ\"ז. שו\"ת הצ\"צ חאבה\"ע (מהדורת תשנ\"ה) סתנ\"ט (מז, ב)."],["8449","543","<b>פ\"י. . שמלאים מצות</b>: ערובין יט, א."],["8450","544","<b>ועשיתם אותם כאילו עשאוני</b>: נסמן לעיל פ' שמות יז, ג."],["8451","545","<b>צדקה וחסד ביד. . דרועא ימינא</b>: ת\"ז בהקדמה (יז, א). ראה גם מאמרי אדה\"א שמות ח\"א ע' צט. וש\"נ."],["8452","546","<b>ימין ה' רוממה</b>: תהלים קיח, טז."],["8453","547","<b>ג' דברים שהעולם עומד עליהם</b>: אבות פ\"א, מ\"ב. ראה גם דרך חיים ע' נד."],["8454","548","<b>אלה המצות. . וחי בהם</b>: חיבור ב' כתובים בחוקותי כז, לד. אחרי יח, ה. ראה גם הנסמן במאמרי אדה\"א ויקרא ח\"א ע' תא. ש\"א צד, ב. שה\"א סח, ב הערה 18. לעיל קמו, ד. קנו, א. לקמן פ' יתרו רנט, ג. רסא, א. תרומה שיד, ב. תצוה שיח, ג. ויקהל תיט, ד. פקודי תנ, א."],["8455","*549","<b><a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380901\" data-slug=\"likkutei-torah\" data-id=\"4001380901\">ואם חסר מצוה א</a>' חסר. . לאבר א'</b>: ראה שערי קדושה להרח\"ו ח\"א ש\"א. מאמרי אדה\"ז תקס\"ה ח\"ב ע' תתעט. לקו\"ת נצבים מה, ג."]]],[2300540878,"שעושה צדקה זו כנ\"ל כמו שהמקיים כל המצות שנק' בשם צדיק בכלל מטעם הנ\"ל וד\"ל.\n<b>אך</b> הנה עדיין יש להבין דלכאורה יש סתירה לענין הנ\"ל במצות שהן בבחי' אברים כו', דהלא מבואר בזהר ג\"כ דהמצות הן בבחי' לבושי' ע\"פ ואברהם זקן בא בימים<sup data-n=\"8456\">549</sup> ביומין עילאין כו' ואי חסר מצוה א' חסרא לבושא חדא כו'. ועוד דהלא בחי' אברים דמלכא היינו בחי' או\"כ דע\"ס דאדם דאצי' שכבר נאצלו בבחי' ציור אדם וכמ\"ש אפיק' י' תקונין<sup data-n=\"8457\">550</sup> וקרית לון י\"ס כו' עד חסד דרועא ימינא כו', ובאמת הרי ידוע ששרש המצות למעלה היינו כמו [מה] שהקב\"ה מניח תפילין ומתעטף בציצית כו' ועושה צדקה וכמו שא' תפילין דמארי עלמא<sup data-n=\"8458\">551</sup> מה כתיב בהו כו' והן הנק' מצות\"י וכמו שאו' שקדשנ\"ו במצותי\"ו, והן המצות העליונות שקיימו האבו\"ת כאברהם שקיים כל התורה כו' כמ\"ש וישמור משמרתי מצותי<sup data-n=\"8459\">552</sup> כו' וא\"כ זהו בחי' מקיפי' דלבושי' ע\"ג האדם העליון כמו מצות תפילין בראש שהן בחי' מקיפי' דד' מוחי' ע\"ג הראש וכן מקיף דטלית שא' לבושי' כתלג [חיוור]<sup data-n=\"8460\">553</sup> כו' וכה\"ג במצות הצדקה שעושה ביד שנק' דרועא כו' שע\"ז א' אלה המצות שיעשה אותם האד\"ם דלעילא כו'. אך הענין הוא דשניהם אמת דע\"י בחי' המקיפי' ולבושים דמצות העליונות נמשך בחי' תוס' אור גדול מעצמות אור הא\"ס בקו\"ח בע\"ס דאדם ברמ\"ח אברים דמלכא כו' וכמ\"ש וחי בהם באדם התחתון כו', וע\"כ גם בחי' המצות העליונות נק' בשם צדקה כמו כשמניח תפילין נמשך בחי' מקיפי' דעצמו' א\"ס במוחי' דז\"א בבחי' בליטה ע\"ג הראש כמ\"ש כי שם הוי' נק' עליך<sup data-n=\"8461\">554</sup> בתפילין שבראש באדם התחתון שדומה לעליון כו', וכך הוא במצות הצדקה ביד ימין בחי' חסד דרועא ימינא במל' דאצי' שנק' דל<sup data-n=\"8462\">557</sup> שזהו ח\"ס דלי\"ת<sup data-n=\"8463\">556</sup>, וכן צדק ה'<sup data-n=\"8464\">555</sup> למאן דלית לי' מגרמי' כלום<sup data-n=\"8465\">558</sup> עי\"ז נמשך אור המקיף דחסד דא\"ס בחסד דז\"א, וכה\"ג בכל פרטי המצות שהן בציור רמ\"ח אברים דמלכא, ובכללות נק' המקיים כל המצות בשם צדיק עליון כמ\"ש כי צדיק ה' צדקות אהב כו'. וגם בדרך פרט בכל מצוה ומצוה הרי נמשך מעצמות א\"ס בבחי' מקיף ולבוש להיות תוס' אור בכלי עד שזהו כמו יריד' התלבשות מעצם הנפש בצמצום האור וחיות דאברי האדם להחיותם ולקיימם ובלעדי זה אין להם קיום כלל, וע\"כ נק' בשם צדק\"ה למעלה שמבלעדי האר' המקיף מאור א\"ס ע\"י הטו\"ת העליוני' וכה\"ג אין לבחי' או\"כ דאצי' המוגבלי' קיום כלל וכמא' אי אנת תסתלק מנייהו<sup data-n=\"8466\">559</sup> אשתארו כגופא בלא נשמתא כו' וד\"ל.",[["8456","549","<b>ואברהם זקן בא בימים</b>: ח\"ש כד, א. ראה זהר ח\"ש קכט, א. ויחי רכד, א. לקמן פ' משפטים רעח, ד. רפה, ב. ש, ב. תצוה שעד, ד. ויקהל שצה, ד. תלא, ג. מאמרי אדה\"א ויקרא ח\"ב ע' תשמט. וש\"נ. דברים ח\"ג ע' תתיב. הנחות תקע\"ז ע' שכח. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680101\" data-slug=\"torat-chaim\" data-id=\"2300680101\">תו\"ח ויחי רלז, א</a> ובהערה 6."],["8457","550","<b>אפיק' י' תקונין</b>: ראה ת\"ז בהקדמה (יז, א)."],["8458","551","<b>תפילין דמארי עלמא</b>: ברכות ו, א."],["8459","552","<b>וישמור משמרתי מצותי</b>: תולדות כו, ה."],["8460","553","<b>לבושי' כתלג [חיוור]</b>: דניאל ז, ט."],["8461","554","<b>כי שם הוי' נק' עליך</b>: תבוא כח, י."],["8462","557","<b>במל'. . שנק' דל</b>: ראה פע\"ח (שער הלולב) שכ\"ט, פ\"ג לר\"י מערבי ד\"ה וזהו פירוש. מאמרי אדה\"א ויקרא ח\"ב ע' תקסט. וש\"נ. דברים ח\"ג ע' תתעב. וש\"נ."],["8463","556","<b>חסד. . ח\"ס דלי\"ת</b>: ראה ת\"ז תכ\"ב (סז, רע\"ב). מאמרי אדה\"א שמות ח\"ב ע' תרמג. וש\"נ."],["8464","555","<b>הצדקה. . צדק ה'</b>: ראה זהר אחרי עב, א. מאמרי אדה\"א שמות כאן ע' קכה. וש\"נ."],["8465","558","<b>במל'. . דלית לי' מגרמי' כלום</b>: נסמן לעיל פ' וארא נה, ג."],["8466","559","<b>אי אנת תסתלק מנייהו</b>: ראה ת\"ז בהקדמה (יז, ב). וראה גם לעיל פ' שמות כח, ד."]]],[2300540887,"<b>ונמצא</b> דשני העניני' [ב]מצות העליונות אמת שהן בבחי' כלים והן בבחי' לבושי' ומקיפי'. וכך הוא במצות שלמטה באדם התחתון שנק' בשם צדקה להחיות רוח שפלים שהוא מצד <span data-k=\"pg\">רמט</span> ּ שמעוררים לכח אור החסד וטוב ור\"ר דעצמות המאציל להחיות ולקיים לבחי' רמ\"ח אברים דמלכא למעלה כנ\"ל שנק' צדקה וחסד למעלה ומשם יורד האור וחיות האלקי הזה גם למטה במצות שלנו להחיות רוח שפלים דנשמות שבגופי' לקיימם באור וחיות חדש בבחי' המקיפי' דנר\"נ דאדם התחתון, כמו במצות תפילין שמניח האדם למטה בראשו נמשך מבחי' מקיפי' דד' מוחי' דשם הוי' העליון על ד' מוחי' שבראשו ע\"י ההתלבשות בד\"פ<sup data-n=\"8467\">560</sup> בפ' קדש בבחי' מקיף דמוח החכ' כו', וזהו כי שם הוי' נקרא עליך ממש, וכה\"ג במצות ציצית בד' כנפות בל\"ב חוטי' שהוא האר' אור מקיף הכללי בל\"ב נ\"ח<sup data-n=\"8468\">561</sup> דמל' דאצי' בנשמת האדם בכלל כשמתעטף בטלית על ראשו כו', וכך הוא במצות הצדקה שאדם עושה שהוא כדוגמא דמצות צדק\"ה העליונה להחיות רוח שפלים לעני ודל כו', וכללות המצות שלנו נק' צדקה מטעם זה בכלל כמ\"ש וצדקה תהי' לנו כו' שזהו מפני שהוא צדקה וחסד מצ\"ע להיות בחי' המשכ' גילוי אוא\"ס באו\"כ דאבי\"ע עד למטה ממש באדם שע\"כ א' וחי בהם ממש ומבלעדי זה אין לו קיום כלל כנ\"ל במצות העליונות שנק' רמ\"ח אברים דמלכא וד\"ל.\n<b>ומטעם</b> זה יובן ג\"כ מה שישראל נק' צדיקים ע\"י קיום המצות כנ\"ל שמי שמקיים כל המצות נק' בשם צדיק דוקא ולא בשם אחר (ומעלת שם צדיק אינו אלא מי שעושה הצדקה שנק' בעל צדקה להחיות רוח שפלים דוקא והוא מבחי' הטוב והרחמי' יתירה עד שמניח כל עצמו ונותן לזולתו כמ\"ש צדיק חונן ונותן<sup data-n=\"8469\">562</sup>, וע\"ז שיבחו הכתוב כמו וצדיק יסוד עולם<sup data-n=\"8470\">563</sup> כמו היסוד לבנין כך כל בנין שפע העולמות תלוי בבחי' צדיק דוקא שעושה הצדקה בכל עת להשפיע לדלים ביתר מכפי המדה (ולמעלה היינו בחי' צ\"ע שנק' יסוד עול\"ם להשפיע למל' הנק' ד\"ל ונק' חי העולמי' כידוע), וכן א' ברכות לראש צדיק<sup data-n=\"8471\">564</sup> וכה\"ג, אבל לא מטעם שהוא צדיק בדינו שאין זה שאינו עושה עול וגזל לבד ונק' צדי\"ק שאין בזה מעלה יתירה כ\"כ ולמה יקרא מפני זה יסוד עולם, ולפי משמעות שבחי' שם צדיק מועטי' המה כמו בראת צדיקי'<sup data-n=\"8472\">565</sup> וכמו בני עלי' שאינם רק ל\"ו צדיקי'<sup data-n=\"8473\">566</sup> דחזו אפי שכינה כו', ועכ\"ז א' ועמך כולם צדיקים מצד מעשה המצות שנק' צדקה וישראל הן העושי' המצות ואפי' פ\"י מלאים מצות",[["8467","560","<b>דד' מוחי'. . בד\"פ</b>: נסמן לעיל פ' בא קכו, ב."],["8468","561","<b>בל\"ב חוטי'. . בל\"ב נ\"ח</b>: ראה לעיל פ' וארא נו, ב. וש\"נ."],["8469","562","<b>צדיק חונן ונותן</b>: תהלים לז, כא [ושם: וצדיק — ראה ש\"א כז, א. מאמרי אדה\"א שמות ח\"א ע' רכא]."],["8470","563","<b>וצדיק יסוד עולם</b>: משלי י, כה."],["8471","564","<b>ברכות לראש צדיק</b>: משלי שם, ו."],["8472","565","<b>בראת צדיקי'</b>: ב\"ב טז, א."],["8473","566","<b>בני עלי'. . ל\"ו צדיקי'</b>: ראה סוכה מה, ב. הנסמן לעיל פ' בא קב, ב."]]],[2300540896,"כרמון ע\"כ כולם נק' צדיקים), כי הנה מבואר למעלה בשרש המשכ' גילוי אא\"ס ברמ\"ח אברי' דמלכא בבחי' או\"כ דאצי' שהוא בחי' צדקה וחסד בכלל (כמו יריד' והמשכת מקיפי' דנפש להחיות חיות האברי' ולקיימם וא\"ל לא יתקיימו כנ\"ל), ולפי שהשפעה והמשכה זו למעלה באה ע\"י קיום המצות למטה דוקא (כמא' כאלו עשאוני כו' שהרי מצד עצמו לאו מכל אינון מדות כלל רק דאפיק י' תקוני' וקרא לון י\"ס כו') ע\"כ נק' המקיים כל המצות בשם צדיק שנק' בעל צדקה וחסד לפי שהוא המשפיע לבחי' צדקה וחסד העליון להמשיך תוס' גילוי אוא\"ס ברמ\"ח אברי' דמלכא במדת הטוב והרחמים שבעצמות המאציל שנק' צ\"ע למעלה כנ\"ל, וע\"כ א' ועמך כולם צדיקי' לעולם ירשו ארץ שהוא <span data-k=\"pg\">500</span> ּ העוה\"ב שהוא גילוי אור העצמו' דא\"ס ממש כמ\"ש וא' ביום ההוא<sup data-n=\"8474\">567</sup> הנה אלקינו זה קוינו לו כו' (כמשי\"ת), רק עכשיו בחי' אור זה דמצות למעלה בהעלם כמת\"ן בסת\"ר<sup data-n=\"8475\">568</sup> (כמ\"ש במ\"א).\n<b>והנה</b> אחר כ\"ז יתורץ הקושיא הנ\"ל בענין יריד' הנשמה האלקי' בגוף גשמי בעוה\"ז שירידה זו לצורך עליי' שתעלה למעלה ממקור חוצבה הראשון גם בנשמות גבוהות כנשמת משה והאבות וכה\"ג דהיינו דוקא ע\"י מצות מעשיות ובעוה\"ז שנק' סוף מעשה שנעוץ תחב\"ס דוקא, והוא בחי' צדקה ומשפט דתו\"מ בעוה\"ז שעי\"ז דוקא נק' האדם בשם צדיק שהוא העושה לבחי' הצדקה דמעשה המצות ובעוה\"ז דוקא שעי\"ז מעורר לבחי' צ\"ע דהיינו לבחי' מהו\"ע ית' שמשפיע בבחי' חסד וצדקה להיות קיום וחיות לאו\"כ דאצי' ע\"י מצות הוי' שלמעלה כנ\"ל שבאתעדל\"ת דמצות שלמטה דוקא נעשה אתעדל\"ע זו, וע\"כ בזה תעלה הנשמה לידבק במהו\"ע ית' ממש שא\"א שתגיע לזה ע\"י כל אוי\"ר ברו\"ש גם בהיותה בשרשה ומקור חוצבה (וגם האבות שלא קיימו המצות בגשמיות אלא ברוחניות הרי היו עי\"ז שרש ומקור למצות הגשמיות כנ\"ל במ\"ש אשר יצוה כו' ושמרו לעשות צדקה כו'), ומטעם זה הוא שנק' הנשמה מהלך בהיותה בגוף דוקא ע\"י קיום התו\"מ שתהלך ותעלה בלי שיעור כלל עד מהו\"ע ית' ממש וכן בהסתלקות' מן הגוף א' ילכו מחיל אל חיל כו', משא\"כ קודם בואה לעוה\"ז בגוף הי' בבחי' עומד כנ\"ל. וכ\"ז מצד בחי' ר\"ר העצמיי' שנמשך לישראל כמ\"ש למען צדקו כו' ע\"כ הרבה להם תו\"מ כו' שהוא להיות בחי' התלבשות אא\"ס ברמ\"ח אברים כו' והוא ע\"י בחי' הבירור והבדלה דפנימי' ועצמו' כנ\"ל וד\"ל.\n<b>אך</b> הנה עדיין יש להבין בטעם יריד' זו דנשמה בעוה\"ז השפל בגוף חומרי בשביל עלי' כנ\"ל, אם העיקר הוא מצד קיום",[["8474","567","<b>וא' ביום ההוא</b>: ישעי' כה, ט."],["8475","568","<b>דמצות. . כמת\"ן בסת\"ר</b>: ראה מאמרי אדה\"א שמות ח\"א ע' ס. וש\"נ. ש\"א נה, ב ובהערה 8. תו\"ח ויצא קסה ג ובהערה 49."]]],[2300540904,"התו\"מ בגשמיות דנתחב\"ס דוקא כדי להיות לו דירה בתחתוני' דוקא כנ\"ל, הלא מבואר למעלה שהמשכ' התו\"מ למטה זהו אינו בא רק מחמת בחי' ר\"ר העצמיי' דאב על הבן כו', כמ\"ש למען צדק\"ו כו', וא\"כ בחי' ר\"ר הללו הרי כבר הי' מתעורר מעצמו' על הנשמות בהיותם בשרשם ומקורם דוקא שנק' בנים שנמשכו מיחוד פנימי דאו\"א ולמעלה יותר כמו שישראל עלו במח' הקדומה כמ\"ש כי אתה אבינו וכן אבינו אב הרחמן כנ\"ל, ולמה אין התעוררו' זו דר\"ר הנ\"ל [אינה] רק [על] נשמות שבגופי' דוקא, ואם מפני שנתרחקו יותר ע\"כ יותר יומשך הר\"ר במקום שפל ביותר הלא קמי' שוין עומ\"ר ועומ\"ת כנ\"ל. ועוד דהלא ריחוק זה נעשה מלמעלה שהוריד אותם למטה בגופי' מאחר שירידה זו הי' לצורך עלי' מה שייך בזה טעם ענין התעורר' ר\"ר שמפני זה ניתן להם התו\"מ כו'. אך הענין הוא בענין<sup data-n=\"8476\">569</sup> ענין ירידה זו דנשמות בגופי' הוא כדי שיבאו לכלל רחמנות יתירה שיפול עליהם התעוררות ר\"ר הנ\"ל הרבה יותר משהי' עליהם בהיותם במקורם, והענין הוא דבהיות הנשמו' במקורם נק' בנים ונק' צדיקים ע\"י אוי\"ר בדביקו' אמיתי' שלהם כמו ברא\"ת צדיקי\"ם כו' (וכמו במי נמלך בנשמתן של צדיקים<sup data-n=\"8477\">570</sup> וכה\"ג) ובירידתם בגוף בעוה\"ז נעשי' בחי' בע\"ת<sup data-n=\"8478\">571</sup> אמיתי', ואפי' נשמות הגבוהות כנשמת משה והאבות שהי' <span data-k=\"pg\">רנ</span> ּ שרשם בבחי' דחכ' ומדות דאצי' בבחי' צ\"ג כאשר ירדו למטה בגופי' נק' בשם בע\"ת, כמו גם במשה שא' כי טו\"ב הוא בטי\"ת רבתי<sup data-n=\"8479\">572</sup> שהי' טוב וצ\"ג גם בהיותו בגוף הוצרך לבוא לבחי' התשובה<sup data-n=\"8480\">573</sup>, והוא לפי שחומר מחושך הנה\"ט וחומריות העוה\"ז מחשיך ומסתיר על אור הנשמה האלקי' עד שבא יבא לבחי' מרירות עצומה מאד על ריחוקו העצום מאור פני הוי' כמו שהי' עומד לפני ה' בשרשו ומקורו, וצריך לבא לבחי' לב נשבר וכובד ראש שהוא עוצם ההכנעה והשפלות בעצמו כדי לטהר ולזכך גופו בתכלית להיות בר לבב<sup data-n=\"8481\">574</sup> גם ביצה\"ר שבגופו לאהפכא חשוכא לנהורא<sup data-n=\"8482\">575</sup> כו', שאין זה כ\"א ע\"י התעוררות יתירה שמעורר ר\"ר על נפשו בצעקתו במר נפשו כענין מ\"ת בוכי'<sup data-n=\"8483\">576</sup> אנן בעינן למהוי קדם מלכא כו' לבלתי ידח<sup data-n=\"8484\">577</sup> כו' וכה\"ג שאז נק' תשובה שישוב אל ה' בכל לבו, וכתי' וישוב אל ה' וירחמה\"ו<sup data-n=\"8485\">578</sup> שמעורר בחי' ר\"ר העליוני' שבמהו\"ע ית' ממש וכמ\"ש בזהר דבע\"ת משכי לי' לקודב\"ה בחילא יתיר<sup data-n=\"8486\">579</sup> כו' מצד בחי' העלא' דבחי' או\"ח ממקום שפלות והכנעה יתירה שזה עולה למעלה יותר מאוי\"ר בדביקו' אמיתי' באה\"ר בתענוגי' שהי' לנשמה בהיותה צרורה ודבוקה באור פני ה' במקור חוצבה כו', שזהו שארז\"ל במקום שבע\"ת עומדי'<sup data-n=\"8487\">580</sup> צ\"ג א\"י לעמוד שלא יוכלו להגיע לשם כלל והיינו משום דמשכי לי' בחילא יתיר לעורר ר\"ר העצמי' שלא יעוררו צ\"ג בשרשם כלל, וע\"כ עיקר התגלות והמשכות הי\"ג מדה\"ר",[["8476","569","<b>בענין</b>: ו: בעיקר."],["8477","570","<b>במי נמלך בנשמתן של צדיקים</b>: ראה ב\"ר פ\"ח, ז. רו\"ר פ\"ב, ג."],["8478","571","<b>הנשמו'. . ובירידתם. . נעשי' בחי' בע\"ת</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370284\" data-slug=\"torah-or\" data-id=\"3901370284\">תו\"א כאן סג, ג</a>. מאמרי אדה\"א שמות כאן ע' קיח. וש\"נ. הנחות תקע\"ז ע' פ. וש\"נ. דברים ח\"ד ע' א'קעט."],["8479","572","<b>במשה. . בטי\"ת רבתי</b>: נסמן לעיל פ' שמות מג, ד הערה 48."],["8480","573","<b>במשה. . התשובה</b>: ראה בסמוך (קעז, ב)."],["8481","574","<b>בר לבב</b>: תהלים כד, ד. ראה גם לעיל פ' וארא עז, ד. וש\"נ."],["8482","575","<b>לאהפכא חשוכא לנהורא</b>: ראה זהר בהקדמה ד, א."],["8483","576","<b>מ\"ת בוכי'</b>: נסמן לעיל פ' שמות ב, ב."],["8484","577","<b>לבלתי ידח</b>: שמו\"ב יד, יד."],["8485","578","<b>וישוב אל ה' וירחמה\"ו</b>: ישעי' נה, ז."],["8486","579","<b>דבע\"ת. . בחילא יתיר</b>: נסמן לעיל פ' שמות לז, א."],["8487","580","<b>במקום שבע\"ת עומדי'</b>: נסמן לעיל פ' שמות מא, א הערה 175."]]],[2300540911,"ביו\"כ הוא לבע\"ת דוקא לסלוח העוונות כו' מצד בחי' הר\"ר שעליהם יותר מתפשט מעומק פנימית הרצון שנק' רעוא דכ\"ר שלא יאיר כ\"כ בנשמות הצדיקי', וזהו שלא יוכלו לעמוד שם כלל.\n<b>וראי'</b> לכ\"ז הוא ממה שגזרו או' דאין עומדין להתפלל אלא מתוך כובד ראש<sup data-n=\"8488\">581</sup> דוקא שהוא גודל עוצם ההכנעה והשפלות מחמת הריחוק העצום מאשר ירדה הנשמה [ונתלבשה] בחומר תאוות הגופניי' שעי\"ז יעורר ר\"ר על נפשו ויוכל לעלות בעליות הסולם דתפלה באוי\"ר שלימה כמ\"ש מי יעלה בהר ה'<sup data-n=\"8489\">582</sup> כו', וזהו דין המשנה בגזירה שוה לכל נפש גם לצדיק כמו לחוטא שלא יוכל גם הצדיק להתפלל לפני ה' בקירוב כ\"א ע\"י כובד ראש דוקא בתחלה (וכמו במשה שא' תפלה למשה<sup data-n=\"8490\">583</sup> אי\"ש האלק\"י' מעו\"ן את\"ה כו' שזהו כמו שהי' הנשמה במח' הקדומה העצמי' ופנימי' דא\"ס בטרם שנאצלו הע\"ס דאצי' שנק' הרי\"ם כו' ומעולם<sup data-n=\"8491\">584</sup> כו' תש\"ב אנוש עד דכ\"[א]<sup data-n=\"8492\">585</sup> בתשובה שלימה בלב נשבר ונדכה ותאמר שובו בני אדם בהעלא' דאו\"ח שיעלה לקדמותו<sup data-n=\"8493\">586</sup> ממש למעלה מבחי' או\"י שהוא מה שהי' הנשמה במח' תחלה מטעם הנ\"ל ביריד' הנשמה בגוף שמתעורר בר\"ר על שירדה בבירא עמיקתא כו' וד\"ל). ולפ\"ז הרי יובן שזהו טעם ירידת הנשמה בעוה\"ז בגוף גשמי כדי שתבא ע\"י ירידה זו לבחי' תשובה לעורר ר\"ר העצמיי' בחילא יתיר כנ\"ל מפני שאז הרחמנות עליה ביותר ותעורר ר\"ר בלב נשבר מאד, משא\"כ קודם בואה לגוף בעוה\"ז לא הי' עליה התעוררו' ר\"ר הנ\"ל כ\"כ להיותה בבחי' צ\"ג באוי\"ר בדביקו' אמיתי'. וזהו טעם ענין ירידה זו לצורך עלי' דוקא, והוא מה שתעלה הנשמה ע\"י תשובה בהתעוררות ר\"ר הנ\"ל למעלה הרבה יותר ממקור חוצבה דהיינו בבחי' ר\"ר דעצמו' הא\"ס שנק' <span data-k=\"pg\">502</span> ּ רחמים גדולים כמ\"ש ברחמים גדולים אקבצך<sup data-n=\"8494\">587</sup> שאין ישראל נגאלי'<sup data-n=\"8495\">588</sup> אלא ע\"י תשובה דוקא כידוע שזהו עלי' גדולה שלא עלתה לזה רק מסיבת הירידה וד\"ל.\n<b>ואע\"פ</b> שמבואר למעלה דדוקא ע\"י קיום התו\"מ בגשמיות בעוה\"ז תגיע ותעלה הנשמה למעלה במהו\"ע ית' שנק' סדכ\"ס דלמת\"ב כלל שלא היתה מגעת ע\"י אוי\"ר ודביקות בעצם שרשה כו', והוא מפני שירדה למטה בעוה\"ז שנעוץ תחב\"ס שמעורר בזה דוקא בחי' ר\"ר שנק' צדקה וחסד דמצות כו', וא\"כ יריד' הנשמה בשביל קיום התו\"מ הי' לצורך עלי' כנ\"ל ומה יש יתרון מעלה בבע\"ת שגדולי' מצ\"ג דמשמע גם מצ\"ג במצות מעשיות שעושים למטה בעוה\"ז בגופי' כו'. הענין הוא",[["8488","581","<b>דאין עומדין. . ראש</b>: ברכות ל, ב."],["8489","582","<b>מי יעלה בהר ה'</b>: תהלים כד, ג."],["8490","583","<b>תפלה למשה</b>: תהלים צ, א."],["8491","584","<b>בטרם. . הרים כו' ומעולם</b>: תהלים שם ב."],["8492","585","<b>תש\"ב אנוש עד דכ\"[א]</b>: שם צ, ג."],["8493","586","<b>דאו\"ח שיעלה לקדמותו</b>: נסמן לעיל פ' שמות מ, סע\"ד."],["8494","587","<b>ברחמים גדולים אקבצך</b>: ישעי' נד, יז [ושם: וברחמים — ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381144\" data-slug=\"likkutei-torah\" data-id=\"4001381144\">לקו\"ת שה\"ש ג, סע\"ד</a>. מאמרי אדה\"א שמות כאן (ע' קיח)]."],["8495","588","<b>שאין ישראל נגאלי'</b>: נסמן לעיל פ' שמות לז, א הערה 37."]]],[2300540918,"דבזה יתרון מעלה דתשובה שמעורר למקור הר\"ר הנ\"ל דהיינו למעלה ממקור הרחמים שיבא לכלל ר\"ר ואז יהי' עי\"ז הירידה וצמצום של רצה\"ע במצות להיות התלבשות אח\"כ<sup data-n=\"8496\">589</sup> ברמ\"ח אברים דמלכא כנ\"ל, וע\"כ מעלת בע\"ת גדולה גם מצדיק במצות שלמטה כמ\"ש דצ\"ג א\"י לעמוד במקום בע\"ת דהיינו צ\"ג שלמטה כו', לפי שבע\"ת גורמי' התעוררו' העצמו' דא\"ס שהוא מקור הראשון להתעורר בר\"ר שלו להיות מזה סיבת ההשפעה של בחי' הצדקה וחסד דמצות הנ\"ל וד\"ל. ומזה הטעם אין מע\"ט בלא תשובה מקודם כמ\"ש יפה שעה א'<sup data-n=\"8497\">590</sup> בתשובה ומע\"ט בעוה\"ז מכל חיי העוה\"ב, דגם שהעוה\"ב הוא משכר המצות<sup data-n=\"8498\">591</sup> אבל ע\"י תשובה דוקא עולי' במהו\"ע ית' ממש שלמעלה גם מחיי העוה\"ב כמא' אין זולתך לחיי העוה\"ב כידוע דביו\"ד נברא העוה\"ב כו', וכן א' תכלית חכמה תשובה ומע\"ט<sup data-n=\"8499\">592</sup> דוקא (וגם [ע\"י] תשובה בלא מע\"ט לא יומשך גילוי א\"ס למטה כלל כ\"א ע\"י המצות כנ\"ל). וזהו שגם משה שהי' צ\"ג במצות לא זכה לתשובה כ\"א קודם מותו<sup data-n=\"8500\">593</sup> דהיינו לתשו\"ע שהוא המקור דר\"ר הנ\"ל כמו ישוב ירחמינו<sup data-n=\"8501\">594</sup> וא' בזהר מאן אתר מהאי ע\"ס<sup data-n=\"8502\">595</sup> כו', וכן מלכא משיחא אתא לאתבא<sup data-n=\"8503\">596</sup> צ\"ג בתשו' כדי להעלותם עם המע\"ט שלהם למקור הר\"ר דמצות כו'. וא\"כ הרי עיקר תכלית הירידה דנשמה שהיא לצורך [ה]עלי' הגדולה היינו ע\"י התשובה בב' טעמי', א' מצד המרירות שבתשו' שעולה בבחי' או\"ח למעלה מאו\"י דמצות גם בגשמיות שזהו עיקר ענין הירידה הגדולה כו' וכל שהירידה יותר העלי' שלה יותר, והוא טעם הב' <sup data-n=\"8504\">597</sup>מה שתעלה במהו\"ע ית' [ממש] שלמעלה ממקור הרחמי' שעי\"ז נמשך ומתעורר בר\"ר להשפיע בחי' צדקה העליונה הנ\"ל ויהי' נק' צדיק (וכדוגמא שלמטה שלא נק' צ\"ג באוי\"ר וקבלת עומ\"ש שלימה במצות בק\"ש ותפלה כ\"א ע\"י כובד ראש תחלה דוקא וכמ\"ש תשב אנוש כו') וד\"ל (וזהו שאמרו תכלית חכ' תשובה ומע\"ט היינו תכלית השלימות דח\"ע דתורה הקדומה שירדה בח\"ת בתו\"מ הנגלות לנו ע\"י תשובה מקודם וזהו תשו' ומע\"ט מטעם הנ\"ל) (ובזה יתורצו כל הקושיות דלעיל בענין ירידה צורך עלי' כו').\n<b>והנה</b> אחר כל הנ\"ל יובן בתוס' ביאור מ\"ש אשירה לה' כי גאה [גאה] כו', דהנה לכאו' יש לדקדק במ\"ש תחלה אז ישיר משה ובנ\"י<sup data-n=\"8505\">598</sup> כו' הרי הזכיר משה ובנ\"י יחדיו ידובקו<sup data-n=\"8506\">599</sup> והול\"ל אז ישירו משה ובנ\"י וא' ישיר לשון יחיד דמשמע מזה דהעיקר בשירה <span data-k=\"pg\">רנא</span> ּ זאת הוא משה ובנ\"י נטפלו ונכללו עמו כו' ועכ\"ז א' ויאמרו לאמר ויאמרו לשון רבים, אך הנה בסיפא חזר וא' לשון יחיד באמרו אשירה לה' כו' דקאי במשה שהוא יחיד או גם בבנ\"י",[["8496","589","<b>אח\"כ</b>: ו: אא\"ס."],["8497","590","<b>יפה שעה א'</b>: ראה גם לעיל פ' וארא סו, א. וש\"נ."],["8498","591","<b>שהעוה\"ב הוא משכר המצות</b>: נסמן לעיל פ' שמות ז, א."],["8499","592","<b>תכלית חכמה תשובה ומע\"ט</b>: ראה בסמוך (בסיום הקטע). לעיל פ' וארא סה, ד ואילך. וש\"נ."],["8500","593","<b>משה. . זכה לתשובה. . קודם מותו</b>: ראה לעיל פ' שמות לז, א. וש\"נ."],["8501","594","<b>ישוב ירחמינו</b>: מיכה ז, יט. ראה זהר ויקרא טז, א. מאמרי אדה\"א דברים ח\"א ע' כג. וש\"נ. ח\"ב ע' תקכד."],["8502","595","<b>ע\"ס</b>: א: א\"ס. ו: עת\"ס עתיקא סתימאה."],["8503","596","<b>מלכא משיחא אתא לאתבא</b>: נסמן לעיל פ' שמות מא, ב."],["8504","597","<b>מה</b>: ו: ליתא."],["8505","598","<b>אז ישיר משה ובנ\"י</b>: בשלח טו, א."],["8506","599","<b>ידובקו</b>: ו: ליתא."]]],[2300540925,"שנתאחדו עמו והן כאיש א' לומר בלשון יחיד אשירה כו'. והנה ידוע ומבואר במ\"א (בס' ש\"א<sup data-n=\"8507\">600</sup> ) דמשה ובנ\"י הן ב' מדרגות דאו\"י ואו\"ח שהן ב' הפכי' דחו\"ג, דאו\"י הן התו\"מ ששרשם בבחי' החסדים דוקא שיורד מגבוה לנמוך מן המשפיע אל המקבל וכמו במ\"ת שירד ה' על ה\"ס וא' אנכי<sup data-n=\"8508\">601</sup> כו', וזהו בחי' ומדרגה דמשה שהוא שרש התו\"מ כמ\"ש תורה צוה לנו משה<sup data-n=\"8509\">602</sup> כו' כי משה ידבר והאלקי'<sup data-n=\"8510\">603</sup> כו', ונק' מחוקק<sup data-n=\"8511\">604</sup> כו' כידוע. ושרש בנ\"י הוא בבחי' או\"ח מלמטה למעלה מן המקבל אל המשפיע שהוא בבחי' ההעלא' דגבורו' כו'. והיינו ב' מדרגות הנ\"ל בצ\"ג ובע\"ת, דצ\"ג הן בבחי' או\"י דתו\"מ מלמעלה למטה ובע\"ת הן בבחי' ההעלאה דאו\"ח מלמטה למעלה והן כמו ב' הפכי' דאש ומים כו'. ועכ\"ז בשירת הים א' אז ישיר משה ובנ\"י גם [ש]המה ב' הפכי' דחו\"ג נכללו יחדיו יודבקו והיו לאחדים ממש עד שא' בזה לשון יחיד אז ישיר כו', והוא מפני שבחי' ההעלא' דאו\"ח דבנ\"י נכללו באו\"י דתו\"מ דמשה ע\"כ משה הוא העיקר בשירה זו כמ\"ש אז ישיר משה כו', וכן בסיפא א' אשירה לה' כו' לשון יחיד דגם שכנ\"י היו או' השירה עם משה יחד כמ\"ש ויאמרו לאמר כו' נכללו עמו יחד כאיש א' ממש, והיינו מטעם ענין הנ\"ל בבחי' תשובה ומע\"ט שנכללי' כא' ממש (דאין תשובה בלא מע\"ט ואין מע\"ט בלא תשובה), וכל יריד' הנשמה בגוף הוא להיות מצ\"ג בע\"ת כדי שיעלו למעלה יותר שזהו הירידה לצורך עלי' כנ\"ל. אך א\"כ הי' צ\"ל בהיפוך שיהיו בנ\"י עיקר בשירה זאת כנ\"ל שהרי יש יתרון מעלה בבע\"ת מצ\"ג עד שאין צ\"ג יכולים לעמוד במקום בע\"ת כנ\"ל. אבל הענין הוא לפי שמבואר למעלה דקי\"ס הי' הכנה למ\"ת דוקא ואם לא קי\"ס לא היו יכולים לעמוד בקבלת התורה פב\"פ בה\"ס, וז\"ש הפך ים ליבשה כו' שם נשמחה בו שהוא בחי' ההעלא' דנש\"י למעלה מעלה במהו\"ע ית' ממש שנק' סדכ\"ס כו' בחי' אדון הנפלאות שז\"ש כי גאה גאה כו' כנ\"ל, וזהו נשמחה בו ממש, וע\"י בחי' העלאה זו הוא שגרם בחי' הירידה וההמשכה מלמעלה למטה במ\"ת ש[שם] א' ביום חתונתו וביום שמח\"ת לבו בשמחה דמשפיע במקבל כו' כנ\"ל, וא\"כ הרי בקי\"ס הי' להיפוך שבחי' העלי' הי' לצורך הירידה דהיינו כמו בחי' ההעלא' דאו\"ח דבע\"ת הי' לצורך בחי' הירידה דאו\"י דמ\"ת שהוא בחי' צ\"ג (וכך יכול להיות ענין תשובה ואח\"כ מע\"ט שזהו עלי' בשביל ירידה משא\"כ תשו' אחרי מע\"ט שזהו לעשות מצדיק בע\"ת כנ\"ל שנק' ירידה בשביל עלי' יותר כנ\"ל) וכמו<sup data-n=\"8512\">605</sup> ענין הספי' קודם מ\"ת<sup data-n=\"8513\">606</sup> שהוא בחי' הבירור והעלא' דז' מדות רעות דק\"נ שיובררו ע\"י הספי' ויוכללו בז' מדות דקדושה ואז יוכל להיות בחי' הירידה וההמשכה דמ\"ת שהיא בפנימי' אבא כידוע).",[["8507","600","<b>בס' ש\"א</b>: בס' שער האמונה — פמ\"ג ע, ב ואילך."],["8508","601","<b>שירד ה'. . וא' אנכי</b>: יתרו יט, כ. כ, ב."],["8509","602","<b>תורה צוה לנו משה</b>: ברכה לג, ד."],["8510","603","<b>משה ידבר והאלקי'</b>: יתרו יט, יט."],["8511","604","<b>משה. . ונק' מחוקק</b>: ראה גם לעיל פ' שמות יב, ד. וש\"נ."],["8512","605","<b>וכמו</b>: אוצ\"ל: (וכמו."],["8513","606","<b>הספי' קודם מ\"ת</b>: נסמן לעיל פ' בא קכא, ג."]]],[2300540932,"<b>והענין</b> הוא כידוע שבקי\"ס היו ישראל בבחי' ההעלא' דתשובה שלימה מקירות לבם ועצם נקודת נפשם וכמ\"ש ופרעה הקריב וא' הקריב את לבם לאביה\"ם שבשמי\"ם<sup data-n=\"8514\">607</sup> ממש בהעלא' דמס\"נ האמיתי <span data-k=\"pg\">504</span> ּ במהו\"ע ית' ממש, לפי שהיו בבחי' מיצר ולב נשבר ונדכ[א] בתכלית מרדיפת פרעה וחילו אחריהם בים וכמו מן המיצר קראתי<sup data-n=\"8515\">608</sup> כו' כבע\"ת אמיתי שקורא מן המיצר בעומק לבו, ע\"כ א' הקריב את לבם שמחמת המיצר דפרעה הוא שהקריב את לבם עד שמס\"נ ממש לאביה\"ם שבשמים כמו אליך ה' נפשי אשא<sup data-n=\"8516\">609</sup> אליך ממש כידוע וד\"ל (ואע\"פ שא' להם משה ה' ילחם לכם<sup data-n=\"8517\">610</sup> ואתם תחרישון וא' בזהר לא תתערו מידי<sup data-n=\"8518\">611</sup> כו', היינו שלא יעוררו בהעלאת מ\"ן בכוונה שבלב ומוח בדיבור ומח' ושכל לפי שה' עצמו ילחם לכם מלמעלה מכל ההשתל' שאין העלאת מ\"ן מגיע לשם כלל וכלל ע\"כ א' ואתם תחרישון בדיבור ולא תתערו מידי במ\"ת<sup data-n=\"8519\">612</sup> (כמשי\"ת בסמוך בענין סוס ורוכבו כו'), אבל בקירת נקודת לבם ונפשם היו בבחי' ביטול [ה]מציאות במס\"נ האמיתי רק לה' לבדו כמשז\"ל הקריב את לבם ממש כנ\"ל וד\"ל), ובחי' ההעלא' הזאת מן המיצר מעומק לבם עלה בבחי' או\"ח למעלה לעורר מקור הר\"ר הנ\"ל (כמו ממעמקים קראתיך הוי'<sup data-n=\"8520\">613</sup> בעשי\"ת כמ\"ש במ\"א שגורם יריד' והמשכה מעומקא דלבא<sup data-n=\"8521\">614</sup> וז\"ש קראתיך הוי' בירידה והמשכה ממעמקי' כו') וזהו<sup data-n=\"8522\">615</sup> במ\"ת שא' אנכי הוי' אלקיך מבחי' שם הוי' העצמי דתו\"מ העליוני' כו') נעשה עי\"ז המשכה הפנימי' ועצמיות דתו\"מ שה' חפץ למען צדקו כו' כנ\"ל. וזהו שקי\"ס הי' הכנה למ\"ת כנ\"ל, ולפי שעיקר בחי' העלא' זאת אינה רק בשביל הירידה דמ\"ת בגילוי אור העצמו' דא\"ס באמרו אנכי הוי' אלקיך כו', ע\"כ עיקר השירה הזאת הי' על שם משה שהוא שרש להמשכת התו\"מ מעצמו' א\"ס ב\"ה כמ\"ש משה ידבר כו' וא' אנכי עומד<sup data-n=\"8523\">616</sup> כו'. וע\"כ א' אשירה לה' לשון יחיד לפי שנכללו בנ\"י במשה בהיות שהי' התגברות דאו\"י על או\"ח כי עיקר המכוון בהעלאה דאו\"ח דתשו' אינו רק בשביל המשכ' דאו\"י בתו\"מ (אע\"פ שאו\"ח חוזר לקדמותו למעלה ממקור הרחמים כנ\"ל להביאו לבחי' התעוררות ר\"ר בצדקה דמצות כנ\"ל, עכ\"ז העיקר הוא בהמשכ' דצדקה וחסד בתו\"מ דוקא כמו בבחי' רו\"ש שעיקר המכוון בבחי' רצוא בשביל בחי' שוב וכמ\"ש בזהר ע\"פ הסיבי עינייך כו' דמוקדי' לי'<sup data-n=\"8524\">617</sup> כו' (וכמ\"ש במ\"א) (וראי' לזה הוא ממ\"ש תחלה ויאמינו בהוי' ובמשה עבדו<sup data-n=\"8525\">618</sup> שהוא מצות האמונה בהוי' שכוללת כל התו\"מ שניתן ע\"י משה עבדו וכמא' תרי\"ג מצות ניתנו למשה [בסיני] בא חבקוק והעמידן על א'<sup data-n=\"8526\">619</sup> צדי\"ק באמונת\"ו יחי'<sup data-n=\"8527\">620</sup> שזהו בחי' או\"י שאחר [בחי'] או\"ח, ואמונה זו בשם הוי' ומשה עבד הוי' שזהו בהמשכת שם הוי' דתו\"מ בא להם דוקא אחר",[["8514","607","<b>ופרעה הקריב. . לאביה\"ם שבשמי\"ם</b>: נסמן לעיל קלח, ג."],["8515","608","<b>מן המיצר קראתי</b>: תהלים קיח, ה."],["8516","609","<b>אליך ה' נפשי אשא</b>: תהלים כה, א. ראה גם לעיל פ' וארא עו, ד."],["8517","610","<b>ה' ילחם לכם</b>: בשלח יד, יד."],["8518","611","<b>לא תתערו מידי</b>: נסמן לעיל קנז, ב."],["8519","612","<b>במ\"ת</b>: א: במח'. בו: ליתא."],["8520","613","<b>ממעמקים קראתיך הוי'</b>: תהלים קל, א. ראה גם סידור (שער האלול) רכו, ד. רכט, ג. מאמרי אדה\"א ויקרא ח\"ב ע' תקיג. דברים ח\"ג ע' א'פז."],["8521","614","<b>דלבא</b>: בו: דכולא."],["8522","615","<b>וזהו</b>: אוצ\"ל: (וזהו."],["8523","616","<b>אנכי עומד</b>: ואתחנן ה, ה."],["8524","617","<b>הסיבי עינייך כו' דמוקדי' לי'</b>: ראה לעיל פ' וארא פד, סע\"א ואילך. וש\"נ."],["8525","618","<b>ויאמינו בהוי' ובמשה עבדו</b>: בשלח יד, לא."],["8526","619","<b>תרי\"ג מצות. . על א'</b>: נסמן לעיל פ' שמות יז, ב."],["8527","620","<b>צדי\"ק באמונת\"ו יחי'</b>: חבקוק ב, ד [ושם: וצדיק — ראה שה\"א ח, ב הערה 3]."]]],[2300540939,"שראו את היד הגדולה כו' וייראו את הוי' בבחי' ביטול [ב]מציאות בהעלא' דאו\"ח דתשו' מן המיצר כנ\"ל אזי ויאמינו בה' כו' וע\"כ א' אז ישיר משה דוקא וד\"ל. וזהו שא' אשירה להוי' כו' בבחי' שיר ורינה דוקא כידוע שהשיר בא ע\"י שמחה והשיר גורם השמחה, ושירת הים ודאי הי' מחמת שמחה גדולה כמ\"ש הפך ים ליבשה כו' שם נשמחה בו ממש כנ\"ל (אע\"פ שא' שם נשמחה בו דמשמע לע\"ל דקאי אדסמיך לי' בנהר יעברו ברגל שזהו העבר' השני' בנהר פרת שיהי' ע\"י משיח כמ\"ש עד יעבור כו' (כמ\"ש במ\"א בש\"א<sup data-n=\"8528\">621</sup> ) והוא בעוה\"ב, אך בקי\"ס הי' מעין העוה\"ב שלמעלה ממ\"ת שהרי <span data-k=\"pg\">רנב</span> ּ א' זה אלי<sup data-n=\"8529\">622</sup> כו' לנוכח כמו וא' הנה אלקינו זה בעוה\"ב ע\"כ אמר הפך ים כו' שם נשמחה בו ממש ועכ\"ז הי' עיקר קי\"ס הכנה רק למ\"ת מטעם הנ\"ל, וז\"ש שם נשמחה בו במ\"ת שא' נעשה ונשמע<sup data-n=\"8530\">623</sup> כו' כמו שמחה ש\"מ רק ממה שא' ונעשה רצונו וד\"ל).\n<b>וביאור</b> הענין הנה יש להקדים מ\"ש במ\"א בענין מ\"ש ויספו ענוים בהוי' שמחה<sup data-n=\"8531\">624</sup> שהן צ\"ג שנק' ענוים<sup data-n=\"8532\">625</sup> כידוע שהן מוסיפים בשם הוי' שמחה העליונה ע\"י ששמחים בשמחה ש\"מ שנק' מצות הוי', ואביוני אדם הן בע\"ת<sup data-n=\"8533\">626</sup> שחסירים מכל מצוה ונתקלקל צלם אלקים שלהם בפגם העוונות ונק' אביונ\"י אד\"ם כאביון שאין לו חיות כלל וכמת יחשב<sup data-n=\"8534\">627</sup>, ואמנם מחי' נפשו בלבד כדי חיותו בצמצום שמוצא טרף לנפשו שתכלה נפשו אליו כו'. וכך הוא הבע\"ת שיתמרמר בנפשו שריקן מכל אור וחיות האלקי מתו\"מ ונתרחק מאד בעוונות שעשה ע\"כ יצעק במר נפשו להחיותו, וזהו בבחי' ההעלא' והסתלקות בבחי' או\"ח מצד המיצר שלו בנקודת עומק לבו כו' ולכך א' ואביוני אד\"ם שהן בע\"ת בקדוש ישראל יגילו למעלה משם הוי' שנק' קדוש ישראל כמו קדוש הוי'<sup data-n=\"8535\">628</sup> כו' שלמעלה משם הוי' דתו\"מ כמ\"ש במ\"א בענין קדושי\"ם תהיו ע\"י תו\"מ יכול כמוני<sup data-n=\"8536\">629</sup> ת\"ל כי קדוש אני קדושתי למעלה מקדושתכם כו' שהוא התשובה שמגיע למהו\"ע ית' ממש שלמעלה גם מקדושת המצות דצ\"ג וכנ\"ל דצ\"ג א\"י לעמוד במקום ומדריג' דבע\"ת כו'. והנה בקי\"ס היו בנ\"י בבחי' ההעלא' דבחי' או\"ח במס\"נ מן המיצר ולחץ דפרעה וחילו עד שמחמת זה הקריבו לבם לה' בתשובה שלימה שזהו כמו בחי' אביוני אדם הנ\"ל שבקדוש ישראל יגילו, ובחי' משה שהי' צ\"ג בשרשו הי' בבחי' או\"י דתו\"מ שהוא בבחי' המשכה מן ההעלם לגילוי מלמעלה למטה שזהו ע\"י בחי' השמחה דוקא כמו בשמחה",[["8528","621","<b>העבר' השני'. . ע\"י משיח. . עד יעבור. . בש\"א </b>[ו: ליתא. אב: כבפנים]: בשלח טו, טז. שער האמונה פט, ב."],["8529","622","<b>בקי\"ס. ֿ. העוה\"ב. . זה אלי</b>: בשלח טו, ב. ראה גם להלן קפד, ד."],["8530","623","<b>נעשה ונשמע</b>: משפטים כד, ז."],["8531","624","<b>ויספו ענוים בהוי' שמחה</b>: ישעי' כט, יט. ראה ד\"ה זה במאמרי אדה\"א נ\"ך ע' כז ואילך. וש\"נ. לקמן פ' תצוה שכד, ד."],["8532","625","<b>צ\"ג שנק' ענוים</b>: ראה גם לקמן פ' תצוה שכד, ד. שע\"ת ב, א. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680425\" data-slug=\"torat-chaim\" data-id=\"2300680425\">תו\"ח תולדות קנח, ב</a>. מאמרי אדה\"א דברים ח\"ג ע' א'צח."],["8533","626","<b>ואביוני אדם הן בע\"ת</b>: ראה גם לעיל פ' שמות ט, א. וש\"נ."],["8534","627","<b>כאביון. . וכמת יחשב</b>: ראה גם לעיל ו, ב הערה 277."],["8535","628","<b>קדוש הוי'</b>: ישעי' ו, ג."],["8536","629","<b>קדושי\"ם תהיו. . יכול כמוני</b>: קדושים יט, ב. ויק\"ר פכ\"ד, ט. ראה מאמרי אדה\"א בראשית ע' רכו. וש\"נ. שמות ח\"ב ע' תקצד."]]],[2300540946,"ש\"מ למטה, שע\"ז א' ויספו ענוים שהן צ\"ג בתו\"מ בהוי' שמחה העליונה שישמח שם הוי' העליון במעשה המצות שלהם שהוא גורם ירידה והתלבשו' אוא\"ס בע\"ס דאצי' בתוס' אור מן ההעלם לגילוי, כמו ע\"ד דוגמא מן השמחה למטה שאנו רואים בחוש שהשמחה גורמת בחי' התפשטות וגילוי אור פני' צהובי' דהיינו מצד שבחי' פנימי' האור והחיות דנפש עצמה מתגלה בפנים ע\"י השמחה ומתפשט גם בכל האברים שבגוף, וראי' לזה מן הצער ויגון שגורם כיווץ הלב והעדר הגילוי אור היפך ההתפשטו' עד שפניו רעים וחשוכים כמו שא' לו מדוע פניך רעים<sup data-n=\"8537\">630</sup> אין זה כ\"א רוע לב, ובהיפוך שמחה ובשורה טובה ישמח הלב ויהי' בו בחי' התפשטו' ויאיר פניו ברוב אורה ושמחה, כנראה באדם השמח בדבר מה כמו גם בהמצא' שכל חדש יאירו פניו מאד כמו צהבו פניו דר\"א<sup data-n=\"8538\">631</sup> שמצא תוספתא חדתא וכמו צהבו פניו דר'<sup data-n=\"8539\">632</sup> וכה\"ג (וגם בכל האברים בא' בחי' התפשטו' כעובדא דאספסיינוס<sup data-n=\"8540\">633</sup> שא\"ל שמועה טובה תדשן עצם<sup data-n=\"8541\">634</sup> כו'). וכך יובן למעלה בבחי' אדם העליון דאצי' אע\"פ שאין לו גוף כו' דברה תורה כלשון בנ\"א<sup data-n=\"8542\">635</sup> וכמו ישמח ה' במעשיו<sup data-n=\"8543\">636</sup> וכ\"ש שישמח ה' במעשה הצדיקים, ובחי' שמחה זו עושה בחי' התגלות אור הפנימי' ועצמיות בפני אדם העליון כמו במ\"ת שהאיר פניו אלינו כמ\"ש חכמת אדם תאיר פניו<sup data-n=\"8544\">637</sup> כו', והיינו מפני שהי' בבחי' שמחה כמ\"ש וביום שמחת לבו, וכן יאר <span data-k=\"pg\">506</span> ּ ה' פניו אל הצדיקי' בשמחה ש\"מ שלהם כמ\"ש ויספו ענוים כו' עד שגורם למעלה בחי' תוס' אור בכלים שהן רמ\"ח אברים כו' ע\"י השמחה עליונה שבעצמות המאציל שישמח ה' במעשיהם לפי שנתחב\"ס דוקא כידוע וד\"ל. וכ\"ז בצ\"ג אבל בע\"ת בקדוש ישראל עצמו יגילו למעלה משמחה דשם הוי' כנ\"ל שהוא בבחי' ההעלאה דאו\"ח למעלה במהו\"ע ית', כענין וישמחו ב\"ך ישרא\"ל מקדשי<sup data-n=\"8545\">638</sup> כו' וכן נשמחה בו ממש, כך יגילו בקדוש ישראל עצמו כו' וד\"ל.\n<b>ואמנם</b> הנה מבואר למעלה שבקי\"ס הי' בחי' ההתכללות דאו\"ח ואו\"י דהיינו כמו תשובה ומע\"ט יחדיו יודבקו ונכללו כא' ממש והיינו שבחי' או\"י דתו\"מ גבר על בחי' או\"ח דתשו' מן המיצר כו', והוא שא' אשירה להוי' דוקא כי גאה גאה כו', פי' אשירה בשיר ושמחה לשם הוי' בשמחה דצ\"ג שמוסיפי' שמחה בשם הוי' למעלה כנ\"ל, אך הי' כלול בזה בחי' הגילה וחדוה דבע\"ת שהן בנ\"י שעלו מן המיצר אל המרחב כשראו את היד הגדולה כו' וכמ\"ש מן המיצר קראתי י\"ה ענני במרחב כו',",[["8537","630","<b>מדוע פניך רעים</b>: נחמי' ב, ב."],["8538","631","<b>צהבו פניו דר\"א</b>: ראה ירושלמי שבת פ\"ח, ה\"א. ראה גם מאמרי אדה\"א קונטרסים ע' שדמ. וש\"נ. ש\"א יב, ב. לקמן פ' יתרו רסז, ג. ויקהל תמ, ג."],["8539","632","<b>צהבו פניו דר'</b>: חולין ז, ב."],["8540","633","<b>כעובדא דאספסיינוס</b>: גיטין נו, ב. ראה גם מאמרי אדה\"ז תקס\"ה ח\"א ע' קעז. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370121\" data-slug=\"torah-or\" data-id=\"3901370121\">תו\"א וישלח כו, א</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670192\" data-slug=\"torat-chaim\" data-id=\"2300670192\">תו\"ח לך צה, ד</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680388\" data-slug=\"torat-chaim\" data-id=\"2300680388\">וישלח קפז, ג</a>. ש\"א יד, ב. מאמרי אדה\"א שמות ח\"א ע' קיט. ולהעיר מלקמן פ' ויקהל תכב, ב. וש\"נ."],["8541","634","<b>שמועה טובה תדשן עצם</b>: משלי טו, ל."],["8542","635","<b>דברה תורה כלשון בנ\"א</b>: ברכות לא, ב. וראה <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670114\" data-slug=\"torat-chaim\" data-id=\"2300670114\">תו\"ח וירא צח, ב</a>."],["8543","636","<b>ישמח ה' במעשיו</b>: תהלים קד, לא."],["8544","637","<b>חכמת אדם תאיר פניו</b>: קהלת ח, א."],["8545","638","<b>וישמחו ב\"ך ישרא\"ל מקדשי</b>: נוסח ברכת היום דיו\"ט הוא: כל ישראל — ראה גם לקמן פ' תצוה שמג, ג [ושם הוגה מגוכתי\"ק]. מאמרי אדה\"א הנחות תקע\"ז ע' שסז. וש\"נ."]]],[2300540953,"מפני שהגיע שמחתם במהו\"ע ית' ממש בבחי' העלא' דאו\"ח למעלה ממש, ועי\"ז הי' השיר דמשה ג\"כ בבחי' התכללות דאו\"י ואו\"ח יחד דוקא. וזהו אשירה לה' מלמטה למעלה בשיר ורינה שלמעלה מן הטעם ודעת למעלה גם משמחה דתו\"מ כי הי' בהם בחי' שמח' הנפש עצמה בלא טעם ודעת כלל לפי שהיו שמחי' במהו\"ע ית' שקדושתו למעלה גם מקדושת התו\"מ כנ\"ל (וע\"כ א' זה אלי לנוכח כמו בעוה\"ב ממש כמ\"ש שם נשמחה בו ממש כנ\"ל), וע\"כ ע\"י השיר הזה דוקא הוא שנמשך מן ההעלם לגילוי מפנימי' ועצמו' דא\"ס בשם הוי' דתו\"מ במ\"ת שהוא בחי' או\"י שאחר או\"ח, שממקום שעלה שם משם דוקא חוזר ונמשך, כי כפי ההעלא' כך ההמשכה, והיינו שהי' קי\"ס דוקא הכנה למ\"ת והוא במ\"ש אשירה להוי' כי גאה גאה פי' אשירה לשם הוי' שיהי' נמשך מהעלם העצמו' להיות בבחי' גילוי ממש וד\"ל.\n<b>ומעתה</b> יש להבין הטעם שא' אשירה לה' כי גאה גאה דוקא כו', דהנה מבואר למעלה בשרש ענין קי\"ס שהי' בחי' גילוי ההעלם שנהפך מים ליבשה שבחי' סובב הכללי שנק' מח' הכללי' הי' בבחי' גילוי דממלא בלבד כנ\"ל בענין עושה פלא כו', שיש בזה ב' מדרגות שמים ושה\"ש טה\"ע וטה\"ת<sup data-n=\"8546\">639</sup>, דהיינו מחשבה הכללי' שבאה לגילוי להיות כלל אל הפרט שנק' מקיף לאבי\"ע לבד או לז\"א<sup data-n=\"8547\">640</sup> שני' כו' נק' טה\"ת וכמו מח' הכללית באדם להרגיש א\"ע מראש לרגל כו' (וזהו שאמר והי' העולם<sup data-n=\"8548\">641</sup> בכללו' כנ\"ל), והב' טה\"ע שנק' שה\"ש שנק' מקיף למקיף זה עכ\"פ כנ\"ל, וזהו מ\"ש בע\"ח ששיער בעצמו<sup data-n=\"8549\">642</sup> בכח ובהעלם מה שעתיד להיות בפועל שהוא גילוי הרצון ומח' הכללי' הנ\"ל שז\"ש גליף גליפו בטה\"ע<sup data-n=\"8550\">643</sup> ולכך נק' שה\"ש להיותו רק בבחי' מקיף בהעלם למח' הכללי' הנ\"ל שגם הוא בהכרח בא לפ\"ע הגילוי דמח' א' הזאת אלא ששוה ומשוה לעומ\"ר ועומ\"ת דשמים הנק' טה\"ת כו' כמו שטה\"ת מקיף לבחי' הפרט שנק' ממלא כו', וע\"כ א' דגם שה\"ש לא יכלכלוך<sup data-n=\"8551\">644</sup> כי גם הוא נק' גבול בערך לגבי בחי' עילת כל העילות שנק' סדכ\"ס דלמחת\"ב כלל אפי' בחי' טה\"ע הנ\"ל כי <span data-k=\"pg\">רנג</span> ּ אינו רק מה ששיער בעצמו בכח מה שעתיד להיות כו' עכ\"פ. וכמו\"כ יובן במ\"ש המלך המרומם לבדו מאז שזהו מל' דא\"ס<sup data-n=\"8552\">645</sup> עצמו כמו שעלה במח' העצמי' אנא<sup data-n=\"8553\">647</sup> אמלוך<sup data-n=\"8554\">646</sup> כו' שהוא בחי' אותיות דטה\"ע הנ\"ל, ובל' רז\"ל היינו מה שהי' הוא ושמו בלבד, וע\"ז או' יהא ש\"ר מברך<sup data-n=\"8555\">648</sup> כו' כידוע, וכמ\"ש נכון כסא\"ך<sup data-n=\"8556\">649</sup> מאז, רק שמתצמצם להיות [מלכותך] מל' כ\"ע<sup data-n=\"8557\">650</sup> שזהו בבחי' מקיף דטה\"ת הנ\"ל שע\"ז א' ה' מלך גיאות לבש<sup data-n=\"8558\">651</sup> כידוע, והיינו ב' מדרגות דהתנשאו' מצד",[["8546","639","<b>שמים ושה\"ש טה\"ע וטה\"ת</b>: ראה מאמרי אדה\"א שמות ח\"ב ע' שצה. וש\"נ. לקמן פ' תרומה שטו, ג. תצוה שלא, ד. ויקהל תלא, ד. תלג, א. פקודי תנב, ג."],["8547","640","<b>לז\"א</b>: או: לו\"א."],["8548","641","<b>שאמר והי' העולם</b>: נוסח ברוך שאמר."],["8549","642","<b>מ\"ש בע\"ח ששיער בעצמו</b>: נסמן לעיל פ' בא קב, א."],["8550","643","<b>גליף גליפו בטה\"ע</b>: זהר בראשית טו, א."],["8551","644","<b>שה\"ש לא יכלכלוך</b>: מל\"א ח, כז."],["8552","645","<b>המלך המרומם. . מל' דא\"ס</b>: ברכת יוצר. ראה גם לעיל פ' בא צ, א. וש\"נ."],["8553","647","<b>אנא אמלוך</b>: ראה מאמרי אדה\"ז תקס\"ח ח\"א ע' ז: ”וכמ\"ש בזהר בפי' וימלוך אנא אמלוך\". הנסמן במאמרי אדה\"א דברים ח\"ג ע' תתצד."],["8554","646","<b>מל' דא\"ס. . אנא אמלוך</b>: ראה גם מאמרי אדה\"א במדבר ח\"א ע' קעה. קונטרסים ע' שיג. וש\"נ. ש\"א נה, ב ובהערה 22."],["8555","648","<b>יהא ש\"ר מברך</b>: נוסח הקדיש. ראה גם לקמן רכג, א, פ' תצוה שכו, א. ויקהל שפח, ד. ש\"א ח, ב הערה 26."],["8556","649","<b>נכון כסא\"ך</b>: תהלים צג, ב."],["8557","650","<b>[מלכותך] מל' כ\"ע</b>: נסמן לעיל קמב, ב."],["8558","651","<b>ה' מלך גיאות לבש</b>: תהלים צג, א."]]],[2300540960,"עצמו שנק' מלך מרומ\"ם לבד\"ו והתנשא\"ו' מימו\"ע לבד. אך ב' מדרגות הללו דטה\"ע וטה\"ת שנק' שמים ושה\"ש (שנק' עלמין סתימין או נפלא[ו]\"ת<sup data-n=\"8559\">*652</sup> גם מהם הוא סתום ונעלם שנק' מפני זה [בשם] סדכ\"ס כנ\"ל עד שבחי' ההעלם דסתימין הנ\"ל שוה לפניו עם בחי' הגילוי ממש, ע\"כ יכול להיות גם מבחי' ההעלם דמקיף למקיף דשה\"ש לבא בבחי' גילוי ממש כמו בקי\"ס שנהפך הים ליבשה (דזהו ים הקדמוני שנק' ימא עילאה והן המ\"ע<sup data-n=\"8560\">652</sup> שמעל השמים כמ\"ש ורוח אלקים מרחפ\"ת<sup data-n=\"8561\">653</sup> ע\"פ המים הללו ורקיע המבדיל<sup data-n=\"8562\">654</sup> זהו בחי' טה\"ת הנ\"ל וד\"ל) מאחר דגם בחי' שה\"ש שהוא טה\"ע הנ\"ל מקיף למקיף עכ\"פ ששייך לבחי' השפע' להיות מקור הראשון למה שיהי' בגילוי, א\"כ לקמי' אור העצמו' ממש כלא חשיב גם הוא עד שיכול להיות בבחי' גילוי כמ\"ש הים ראה וינוס כו', כמו גם בהעלם הרצון המוחלט בעצם הנפש באדם לבנות בנין שלגבי מהו\"ע ממש אין זה תופס מקום כלל ושוה לפניו העלם הרצון שבעצמות עם מה שיבא בגילוי ממנו בכלל ובפרט כו' וד\"ל (וא\"כ לא יתכן לקרות למה ששיער הרצון בעצמו בכח כנ\"ל בשם התנשאו' שמצד עצמו ממש, מאחר שמהו\"ע ית' ממש מובדל בערך לגמרי גם מבחי' ההעלם דרצון זה, ומה שנק' מל' דא\"ס היינו לגבי ההשתלשלו' דקו\"ח שבא מהעלם דמח' אנא אמלוך להיות בכלל ופרט כנ\"ל, אבל מל' דא\"ס שמצד עצמו ממש הרי הוא בבחי' עצמו' דא\"ס ממש והוא מה שאין לו שיעור למעלה כו' (משא\"כ בחי' טה\"ע דשה\"ש מאחר שמקיף למקיף הכללי הנ\"ל עכ\"פ יש בהכרח גם בו בחי' מעלה ומטה שנק' עומ\"ר ועומ\"ת רק שהוא למעלה מעומ\"ר ועומ\"ת דשמים תתאין (והוא ההפרש בין ב' מיני עיגולים דסמ\"ך כמשי\"ת בסמוך) דלא כדלעיל בענין שה\"ש כו' וד\"ל).\n<b>והנה</b> בקי\"ס נהפך בחי' ההעלם לגילוי כנ\"ל היינו גם בחי' טה\"ע דשה\"ש נהפך להיות בבחי' גילוי והוא מל' דא\"ס שנק' מל\"ך מרומ\"ם עכ\"פ נעשה בבחי' גילוי כמו בחי' מל' דאצי' בבריאה עד מל' דעשי' שנק' יבשה על ד\"א<sup data-n=\"8563\">655</sup> בדיבור כמו העלם עצמו' הרצון [ש]הוא הכלול בעצם הנפש בכ\"ח כנ\"ל שנעשה בבחי' גילוי, א\"כ מוכרח לומר שהי' זה מצד גילוי דעצמו' א\"ס מבחי' ההעלם דעצמו' ממש שלמעלה גם ממקיף למקיף כנ\"ל (שהוא התנשאו' שמצד עצמו) שזה הי' במ\"ת שירד ה' כו' וא' אנכי מי שאנכי שנק' סדכ\"ס כנ\"ל (ולע\"ל יתגלה, וז\"ש כימי כו' אראנו נפלאות כו' וגם גילוי העלם הזה בא בהכרח ממהו\"ע ית' ממש שלמעלה גם מבחי' התנשאות זו שמצד עצמו ממש כמ\"ש למעלה דגם זה שאין לו שיעור למעלה ולמטה נק' בחי'",[["8559","*652","<b>נפלא[ו]\"ת</b>: כנצ\"ל: נפלא[ו]\"ת)."],["8560","652","<b>ים הקדמוני. . המ\"ע</b>: נסמן לעיל פ' שמות מד, א."],["8561","653","<b>ורוח אלקים מרחפ\"ת</b>: בראשית א, ב."],["8562","654","<b>ורקיע המבדיל</b>: בראשית שם, ו. ז."],["8563","655","<b>על ד\"א</b>: בגהט: ליתא. ו: הניח מקום פנוי."]]],[2300540966,"מעלה ומטה כו', והיינו שנתגלה מבחי' ההעלם דעצמותו ממש שנק' חשך סתרו או ערפל<sup data-n=\"8564\">*656</sup> <span data-k=\"pg\">508</span> ּ והוא סמ\"ך העליון (כמשי\"ת). וזהו כי גאה גאה דהיינו בחי' סדכ\"ס הנ\"ל שנק' אדון הנפלאו\"ת דשמים ושה\"ש לא יכלכלוהו שיתגלה במ\"ת והעוה\"ב שע\"ז א' שם נשמחה בו ממש וכן זה אלי ממש כנ\"ל. וזהו אשירה להוי' שיבא מבחי' ההעלם דעצמותו ממש לגילוי במ\"ת כמו שהי' בקי\"ס בבחי' ההעלאה דאו\"ח דבנ\"י למעלה במהו\"ע ית' ממש שמפני זה נהפך ההעלם לגילוי כנ\"ל, וזהו הטעם דכי גא\"ה גא\"ה למעלה מבחי' גיאות והתנשאות דשמים ושה\"ש הנ\"ל (שהוא התנשאו' שמצד עצמו ממש שמתלבש בתו\"מ דוקא כמ\"ש ועו\"ז מלך משפט אהב כו', וכמו י\"פ דמלכיות בר\"ה<sup data-n=\"8565\">656</sup> שזהו מלך הקדוש ומלך המשפט<sup data-n=\"8566\">657</sup> שאו' מי\"פ דתנ\"ך דוקא וכמ\"ש בי מלכים ימלוכ\"ו<sup data-n=\"8567\">658</sup> והיינו אמרו לפני מלכיות<sup data-n=\"8568\">659</sup> שתמליכוני עליכם דוקא בקבלת עומ\"ש דתו\"מ דוקא וד\"ל). וזהו ה' מלך גיאות לבש בב' מקיפים הנ\"ל, לבש ה' עוז דתורה דוקא והוא מ\"ש נכון כסאך מאז כו' שזהו כסא המל' דתורה שיתגלה בעוה\"ב), וע\"כ א' אשירה לה' כי גאה גאה דוקא דגם שבחי' או\"ח דתשו' דבנ\"י עלה למעלה יותר מאו\"י דתו\"מ כנ\"ל, וא\"כ האיך הי' יכול להיות התגברות דאו\"י דתו\"מ דמשה על בחי' או\"ח דתשו' דבנ\"י. אך לפי שבקי\"ס נתגלה מבחי' כי גאה גאה הנ\"ל (שזהו גילוי ההעלם דעצמו' ממש כמו מגלה עמוקות מני חש\"ך דחשמ\"ל העליון כו') והעלא' דאו\"ח דתשו' <sup data-n=\"8569\">660</sup>לא עלה רק לבחי' ההעלם דאור העצמו' שנק' עלי' והתנשאו' שמצד עצמו, ואמנם שרש התו\"מ הוא בבחי' פנימי' ועצמו' דא\"ס ממש ע\"כ נעשה גם [מ]בחי' ההעלם דעצמו' בחי' גילוי בקי\"ס דוקא, וע\"כ הי' קי\"ס דוקא הכנה למ\"ת שירד ה' וא' אנכי מי שאנכי [ד]לא ידע לי' בר איהו בלחודוהי שזהו הנק' נורא תהלות עושה פלא ונפלאות הנ\"ל ע\"כ נעשה בחי' ההעלם [דעצמו'] דאו\"ח בבחי' גילוי דאו\"י דתו\"מ כמו שיהי' בעוה\"ב ממש שיתגלה מהעלמו העצמו' הנ\"ל, וכמ\"ש עד יעבו\"ר עם זו קנית<sup data-n=\"8570\">661</sup> כו', וכן אהיה אשר אהי' אנא זמין לאתגלאה<sup data-n=\"8571\">662</sup> בימות המשיח שאין זה רק גילוי ההעלם דנפלאות הנ\"ל מסדכ\"ס, ואהי' הב' הוא גילוי ההעלם דעצמו' ממש שנק' סדכ\"ס דגם הוא יבא לגילוי מפני גילוי אור העצמו' דא\"ס ממש. וזהו אשירה להוי' דתו\"מ שבעצמו' ממש שיבא מהעלם העצמות לגילוי, כי גא\"ה גא\"ה להשפיל גיאים לעשות מהעלם גילוי בקי\"ס כנ\"ל, דהא בהא תליא והכל א' כנ\"ל וד\"ל (וא\"כ יש כאן שמים",[["8564","*656","<b>חשך סתרו או ערפל</b>: נסמן לקמן קעט, ג."],["8565","656","<b>י\"פ דמלכיות בר\"ה</b>: ראה לעיל פ' בא צז, א. וש\"נ."],["8566","657","<b>מלך הקדוש ומלך המשפט</b>: ברכות יב, ב."],["8567","658","<b>בי מלכים ימלוכ\"ו</b>: משלי ח, טו."],["8568","659","<b>אמרו לפני מלכיות</b>: ר\"ה טז, סע\"א. לד, ב."],["8569","660","<b>לא</b>: ו: עילאה."],["8570","661","<b>עד יעבו\"ר עם זו קנית</b>: בשלח טו, טז."],["8571","662","<b>אהיה. . אנא זמין לאתגלאה</b>: שמות ג, יד. ראה זהר ויקרא יא, א. אחרי סה, ב."]]],[2300540972,"ושה\"ש טה\"ת וטה\"ע בחי' נפלאות וסדכ\"ס שנק' נור\"א תהלו\"ת שהוא התנשאות מצד עצמו כנ\"ל ומהו\"ע אור הא\"ס שלמעלה גם מבחי' סדכ\"ס שנתגלה במ\"ת ויתגלה בעוה\"ב וד\"ל).\n<b>וזהו</b> כי גאה גאה סוס ורוכבו רמה בים, דהנה מבואר למעלה שקי\"ס הי' הכנה למ\"ת ובמ\"ת כתי' כי תרכב על סוסיך מרכבותיך כו' משמע ב' מיני מרכבות<sup data-n=\"8572\">663</sup> דסוסי' לשון רבים וכתיב יביאו לבוש מל'<sup data-n=\"8573\">664</sup> אשר לבש כו' וסוס אשר רכב עליו [המלך] ואשר ניתן כתר מל' בראשו דמשמע סוס א', וכן לע\"ל א' ביום ההוא יהי' מציל[ו]ת הסוס<sup data-n=\"8574\">665</sup> קדש לה' וארז\"ל כל מה שהסוס רץ ומיצל<sup data-n=\"8575\">666</sup> כו', להיות ידוע ומבואר במ\"א <span data-k=\"pg\">רנד</span> ּ בענין סוס שהוא ב\"פ ס\"ג בב' סמכין והוי\"ו הוא המחברם יחד<sup data-n=\"8576\">*667</sup>, והענין הוא כידוע דיש ב' מיני מרכבות א' הנושא את הרוכב למעלה מעלה שזהו בבחי' גבורות דאו\"ח כמו שאו' והחיות נושאות את הכסא<sup data-n=\"8577\">667</sup> ונק' רוממי שדי<sup data-n=\"8578\">668</sup> כו' (ובדרז\"ל רוכב על כרוב קל<sup data-n=\"8579\">669</sup> שלו ושט בח\"י אלף עולמות שנא' רכב אלקי' רבותיים<sup data-n=\"8580\">670</sup> כו'), והב' מרכבה שבכחה להוריד את הרוכב למטה מטה ביותר כמו לירד מגובה ההר בעמק גדול כו', כך יש בחי' מרכבה למעלה שעל ידם<sup data-n=\"8581\">671</sup> יורד אור האלקי מגבוה לנמוך שהן בחי' חסדי' דאו\"י (וכמ\"ש בזהר<sup data-n=\"8582\">672</sup> בענין רתיכין ומשיריין<sup data-n=\"8583\">673</sup> כו'), ובמ\"ת היו ב' מיני מרכבות הללו דאו\"ח ואו\"י כלולים כא' ולכך א' כי תרכב על סוסיך ב' מיני סוס מרכבותיך ישועה ב' מיני מרכבות הנ\"ל, והיינו ב' מיני אותיות שנק' סוסי' א' שהן בבחי' ההעלאה וההסתר להעלות ולהסתיר בהעלם אחר העלם למעלה מעלה כו' שנק' סדכ\"ס (והוא בחי' ההתנשאות שמצד עצמו עד אין שיעור למעלה כנ\"ל, וע\"ז א' כבוד אלק\"י' הסת\"ר דב\"ר<sup data-n=\"8584\">674</sup> ונק' סת\"ר עליו\"ן וכן נק' צ\"ל שד\"י<sup data-n=\"8585\">675</sup>, אבל מ\"ש ה' צל\"ך<sup data-n=\"8586\">676</sup> וכה\"ג א' כי יצפנני בסוכ\"ו<sup data-n=\"8587\">677</sup> כו' בסתר אהלו או מ\"ש ובצ\"ל ידי כסיתיך<sup data-n=\"8588\">678</sup> כו' [ש]זהו אהל דתורה (כמשי\"ת), והוא כמו בחי' פנימי' [ו]סודו\"ת התורה שנק' סוד ה' שע\"ז א' הנסתרות לה' אלקינו<sup data-n=\"8589\">679</sup> ונק' נסתרו\"ת ונפלאו\"ת וכה\"ג (ובכלל נק' ח\"ס שכל הנעלם מכל רעיון והשגה וזהו אמון מופל\"א ומוצנ\"ע<sup data-n=\"8590\">680</sup> כו' והוא תורה הקדומה שא' בה ואהי' אצלו אמון כו'). והב' אותיות שמביאי' לבחי' ירידה והמשכה מן ההעלם לגילוי למטה מטה דוקא וכאותיות התורה הנגלות לנו לשמור ולעשות<sup data-n=\"8591\">681</sup> כו' וכמ\"ש ואתא מרבבות קדש<sup data-n=\"8592\">682</sup> כו' (ולמעלה היינו מה שנק' התורה",[["8572","663","<b>מרכבותיך. . ב' מיני מרכבות</b>: ראה בסמוך בפנים. ש\"א צ, ב ואילך."],["8573","664","<b>יביאו לבוש מל'</b>: אסתר ו, ח."],["8574","665","<b>ביום ההוא יהי' מציל</b> [ו]<b>ת הסוס</b>: זכרי' יד, כ [ושם: על מצילות — ראה לקמן קפב, ג]."],["8575","666","<b>כל מה שהסוס רץ ומיצל </b>[א: ומציל]: ראה פסחים נ, א. לקמן קפב, ג."],["8576","*667","<b>והוי\"ו הוא המחברם יחד</b>: ראה ש\"א שער הפורים עב, ב."],["8577","667","<b>והחיות נושאות את הכסא</b>: ראה בחיי תרומה כה, י בשם הפדר\"א ספ\"ד. הנסמן במאמרי אדה\"א בראשית ע' שעג."],["8578","668","<b>רוממי שדי</b>: ברכת יוצר. ראה גם מאמרי אדה\"ז תקס\"ט ס\"ע קנב, ואילך. שע\"ת לג, א. מאמרי אדה\"א שמות כאן (ע' קכג) וש\"נ. לקמן פ' תצוה שכח, ג. פקודי תנט, א."],["8579","669","<b>רוכב על כרוב קל</b>: ע\"ז ג, ב."],["8580","670","<b>רכב אלקי' רבותיים</b>: תהלים סח, יח."],["8581","671","<b>שעל ידם</b>: ו: שע\"י שעל ידה."],["8582","672","<b>בזהר</b>: ו: בבה\"ז. ובש\"א (שבהערה 663) צא, א: בזהר פ' בשלח."],["8583","673","<b>רתיכין ומשיריין</b>: זהר בשלח מח, ב. ביאוה\"ז שם לט, ד ואילך. מאמרי אדה\"א קונטרסים ע' תקפ. וש\"נ."],["8584","674","<b>כבוד אלק\"י' הסת\"ר דב\"ר</b>: משלי כה, ב."],["8585","675","<b>סת\"ר עליו\"ן. . צ\"ל שד\"י</b>: ע\"פ תהלים צא, א."],["8586","676","<b>ה' צל\"ך</b>: תהלים קכא, ה."],["8587","677","<b>כי יצפנני בסוכ\"ו</b>: תהלים כז, ה."],["8588","678","<b>ובצ\"ל ידי כסיתיך</b>: נסמן להלן הערה 706."],["8589","679","<b>הנסתרות לה' אלקינו</b>: נצבים כט, כח. ראה גם לקמן קפב, ד."],["8590","680","<b>אמון מופל\"א ומוצנ\"ע</b>: ראה ב\"ר בתחלתו. תו\"א לב, א ובהנסמן במ\"מ לשם (מהדורת תנש\"א). ת\"ז רתמ\"ב. פרדס (שער עה\"כ) מערכת אמון. מאו\"א בערכו סצ\"ה. ספר הליקוטים להאריז\"ל תרומה כו, א."],["8591","681","<b>הנגלות לנו לשמור ולעשות</b>: נסמן לעיל פ' בא קיד, ב."],["8592","682","<b>ואתא מרבבות קודש</b>: נסמן לעיל ב, ד."]]],[2300540977,"הקדומה בשם מש\"ל הקדמוני כמו יריד' עומק הנעלם של השכל במשלים כמשלי שלמה וכה\"ג), לפי שבמ\"ת א' וירד ה' על ה\"ס<sup data-n=\"8593\">683</sup> שירד עם המרכבה שלו, כמ\"ש כי תרכב על סוסי\"ך כו'. וז\"ש וסו\"ס אשר רכב עליו המלך סו\"ס א' היינו שנכללו ב' מיני מרכבו' דסוסי\"ך דהעלם וגילוי שהוא בחי' סתים וגליא דתורה יחד להיות בבחי' סוס א' לבד, והענין הוא שהיא בחי' התגברות דאו\"י על או\"ח ונעשה גם מבחי' ההעלם דסדכ\"ס עצמו בבחי' גילוי והוא מ\"ש אנכי מי שאנכי דלמחת\"ב כלל הוא הוי' אלקיך ממש בתו\"מ הנגלי' דוקא כו' וד\"ל.\n<b>וביאור</b> הענין יובן ע\"פ הנ\"ל בענין כי גא\"ה גא\"ה דב' מקיפים דשמים ושה\"ש טה\"ת וטה\"ע נק' לבוש גיאות שמתלבש בצמצום, כי גם מה ששיער בעצמו בכח<sup data-n=\"8594\">684</sup> כו' או מח' דאנ\"א אמלו\"ך שנק' מל\"ך מרומ\"ם לבד\"ו שנקרא מקיף למקיף עכ\"פ ואין להם ערך לגבי סדכ\"ס שנק' התנשאו' שמצד עצמו (כנ\"ל דמה ששיער בעצמו בכח לא יתכן לקרותו התנשאות מצד עצמו כו'), ובחי' התנשאות זו שמצד עצמו נק' כתר<sup data-n=\"8595\">685</sup> עליון כנ\"ל הוא נק' מקיף דאו\"ח למעלה מעלה בהעלם אחר העלם כנ\"ל שהוא בחי' מרכבה הנושא לרוכב לתכלית הרוממות כו' (וכמו אלכה [ו]אשובה אל מקומי<sup data-n=\"8596\">686</sup> בגלות דאסתלק לעילא לעילא וכמ\"ש אתה אל מסתת\"ר<sup data-n=\"8597\">687</sup> (ובתורה הוא <span data-k=\"pg\">510</span> ּ שנק' אמו\"ן מוצנ\"ע בסודות התורה בחי' סתים דח\"ס שנק' פל\"א כו') כמ\"ש אלביש שמים קדרות וכאהל\"י קד\"ר כיריעות שלמה<sup data-n=\"8598\">688</sup> (כמשי\"ת). וזהו סמ\"ך התחתון דסו\"ס בחי' ס\"ג בחי' חשמ\"ל העליון<sup data-n=\"8599\">689</sup> דישת חש\"ך סתר\"ו<sup data-n=\"8600\">690</sup> ונק' ערפ\"ל אשר שם האלקי'<sup data-n=\"8601\">691</sup> בבחי' ההסתר וההעלם דוקא כמ\"ש כבוד אלק\"י' הסת\"ר דב\"ר כו' כנ\"ל כעיגול אות הסמ\"ך<sup data-n=\"8602\">692</sup> שאין לו התיישבות למטה כלל וכלל אלא עולה למעלה להעלים ולהסתיר העצמו' וכמו ורוח אלקי' מרחפת כו' נוגע ואינו נוגע<sup data-n=\"8603\">693</sup> כו' (ונק' מגדל הפורח באויר<sup data-n=\"8604\">694</sup> כו'), והסמ\"ך העליון הוא בחי' אותיות התורה שנק' ג\"כ לבוש מסתיר כמ\"ש עוטה אור כשלמה<sup data-n=\"8605\">695</sup> כאותיות שבכתב שמלובש בהן השכל וכמו משלי שלמה וכנ\"ל דהתורה נק' משל הקדמוני כו'), אמנם עי\"ז הוא בא לגילוי מהעלם דעצמו' הנק' סדכ\"ס והיינו בחי' מרכבה הב' הנ\"ל שבכחה להוריד הרוכב למטה מטה שזהו בחי' הנגלה שבתורה כשא' אנכי כו' שהוא בחי' מקיף דאו\"י מלמעלה למטה כו', ובמ\"ת הרי ירד ה' על ה\"ס וא' אנכי כו' בבחי' יחוד והתכללו' דאו\"י ואו\"ח לפי שירד בחי' מהו\"ע ית' שלמעלה מבחי' ההסתר וההעלם דבחי' ההתנשאו' שמצד עצמו, ונעשה בחי' העלם זה בגילוי והוא בבחי' אותיות",[["8593","683","<b>וירד ה' על ה\"ס</b>: יתרו יט, כ. ראה פסיקתא דר\"כ פסקא יב (בחודש השלישי), ד\"ה אנכי (הא') ובהנסמן בהערות לשם."],["8594","684","<b>בכח</b>: ו: ליתא."],["8595","685","<b>כתר</b>: או: סת\"ר."],["8596","686","<b>אלכה [ו]אשובה אל מקומי</b>: נסמן לעיל פ' שמות לט, א."],["8597","687","<b>אתה אל מסתת\"ר</b>: ישעי' מה, טו."],["8598","688","<b>וכאהל\"י קד\"ר כיריעות שלמה</b>: שה\"ש א, ה."],["8599","689","<b>חשמ\"ל העליון</b>: נסמן לעיל פ' שמות א, ג הערה 43."],["8600","690","<b>דישת חש\"ך סתר\"ו</b>: תהלים יח, יב."],["8601","691","<b>ערפ\"ל אשר שם האלקי'</b>: יתרו כ, יח."],["8602","692","<b>כעיגול אות הסמ\"ך</b>: ראה מאמרי אדה\"ז תקס\"ב ח\"א ע' קנט."],["8603","693","<b>ורוח. . נוגע ואינו נוגע</b>: נסמן לעיל פ' שמות מו, א."],["8604","694","<b>מגדל הפורח באויר</b>: חגיגה טו, ב. סנהדרין קו, ב."],["8605","695","<b>עוטה אור כשלמה</b>: תהלים קד, ב."]]],[2300540982,"התו' שהוא בא' אנכי כו' הוא ה' אלקיך, וזהו ענין הוי\"ו שמחבר סמ\"ך העליון עם סמ\"ך התחתון. ומ\"ש אהי' אשר אהי' בעוה\"ב היינו שיתגלה גם מהעלמו העצמי' דהיינו גם ממה שמלובש עכשיו באותיות התורה והמצות כו' (שנק' מש\"ל הקדמונ\"י עכ\"פ שאע\"פ שנק' נגלות לנו במעשה, אבל בזה עצמו מתלבש מהו\"ע ית' בהעלם ולבוש וכמו ה' צל\"ך ובצ\"ל יד\"י כסיתי\"ך שהוא דברי אשר שמתי כו') שנק' היכלא עילא' שהן ד\"א שלו שנתפס מהו\"ע ממש בו (כמשי\"ת) (וזהו שרמז במ\"ש יביאו לבוש מל' [ב]בחי' מל' דא\"ס שהוא בחי' התנשאו' שמצד עצמו שלבש בו המלך במ\"ת דוקא שהוא לבוש דתו\"מ שהוא קבלת עומ\"ש שבמצות כשא' נעשה כו', שלמעלה ממל' שמים דלעילא שנק' שה\"ש וגם מבחי' התנשאו' שמצד עצמו שנק' המלך המרומם לבדו מאז כמ\"ש נכון כסאך מאז כו' שבתורה א' בי מלכים ימלוכ\"ו גם התנשאות שמצד עצמו כו', וראי' מי\"פ דתנ\"ך שתמליכוני עליכם דוקא כנ\"ל, וסוס אשר רכב כו' והיינו ב' מרכבות הנ\"ל דסתים וגליא דתורה דאו\"ח ואו\"י שמתחברי' יחד (ולפי דגם מה שאוא\"ס למעלה כו' שזהו עלי' וירידה דב' סמכי\"ן הנ\"ל שוין לפניו גם עומ\"ר ועומ\"ת הללו ועכ\"ז בהתכללם יחד נק' סו\"ס שניתן כתר מל' בראשו והוא כתר מל' דתו\"מ שהוא אשר יתגלה בעוה\"ב מהעלמו העצמי כנ\"ל, וזהו וי\"ו דסוס המחבר וד\"ל).\n<b>וראי'</b> לזה ממ\"ש השמים כסא\"י והארץ כו' איזה בי\"ת אשר תבנו לי<sup data-n=\"8606\">696</sup> כו' דהיינו גם בחי' שה\"ש הנ\"ל שנק' כסאי לבחי' מל' דא\"ס שנק' מלך מרומ\"ם כו' שנתלבש ע\"י צמצום כמ\"ש ה' מלך גיאות לבש כנ\"ל, ומאחר דגם שה\"ש לא יכלכלוהו ע\"כ א' איזה בית אשר כו' דגם שבבית והיכל אדם נתפ\"ס בד\"א שלו <span data-k=\"pg\">רנה</span> ּ שנק' מקומו של אדם<sup data-n=\"8607\">697</sup> כידוע שזהו מבחי' מקיף דמקיף (כמ\"ש במ\"א בענין מזון לבוש בי\"ת (שנדפס בסידור<sup data-n=\"8608\">698</sup> ), אבל גם [ב]בחי' מקיף למקיף נק' בחי' גבול ומדה כמו שה\"ש שלא יכלכלוהו דאור א\"ס למעלה עד אין שיעור כו' שזהו סדכ\"ס בחי' התנשאו' שמצד עצמו כנ\"ל שנק' סתר עליון הנ\"ל בחי' סמך התחתון בחי' מקיף דאו\"ח כו' וכמא' הוא מקומו ש\"ע<sup data-n=\"8609\">699</sup> בבחי' מקיף [ומקיף] למקיף דשה\"ש הנ\"ל ואין העולם מקומ\"ו שיהי' נתפס כמו בד\"א דאדם שהוא מבחי' מקיף דיחידה<sup data-n=\"8610\">700</sup> (כמשי\"ת) שהרי א' למחת\"ב כלל אפי' מח' ורצון הנעלם שבעצמו' שנק' טה\"ע ששיער בעצמו כו', ומ\"ש הנה ה' יוצא ממקומ\"ו<sup data-n=\"8611\">701</sup> וכן ברוך כבוד ה' ממקומו<sup data-n=\"8612\">702</sup> (או בבחי' העלאה א' אלכה [ו]אשובה אל מקומי כנ\"ל) זהו מ\"ש ישת חש\"ך סתר\"ו שנק' סתר עליון או ערפ\"ל שהוא בחי' סדכ\"ס בחי' התנשאו' שמצד עצמו כנ\"ל,",[["8606","696","<b>השמים כסא\"י. . לי</b>: ישעי' סו, א."],["8607","697","<b>בד\"א. . שנק' מקומו של אדם</b>: ראה אנציק' תלמודית בערכו. וש\"נ."],["8608","698","<b>מקיף דמקיף. . שנדפס בסידור</b>: ראה שם שער התפלה כ, ב. כא, א."],["8609","699","<b>הוא מקומו ש\"ע</b>: נסמן לעיל קנ, ד."],["8610","700","<b>בד\"א דאדם. . מקיף דיחידה</b>: ראה גם לקמן (קפ, ב. ג) בפנים. רה, ד. פ' תרומה שיז, ד. ויקהל תיט, ד. מאמרי אדה\"א דברים ח\"ד ע' א'שעו. וש\"נ. קונטרסים ע' יא. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670510\" data-slug=\"torat-chaim\" data-id=\"2300670510\">תו\"ח נח נו, א</a>."],["8611","701","<b>הנה ה' יוצא ממקומ\"ו</b>: ישעי' כו, כא."],["8612","702","<b>ברוך כבוד ה' ממקומו</b>: יחזקאל ג, יב."]]],[2300540987,"ועכ\"ז הרי צמצם שכינתו בין ב' בדי הארון<sup data-n=\"8613\">703</sup> בהיכל ק\"ק שנק' בית והיכל להיות נתפס בו מהו\"ע ית' ממש שם ונק' מקום מנוחתי<sup data-n=\"8614\">704</sup> כו', היינו מצד שבארון ולוחות הי' בחי' גילוי אור העצמו' דא\"ס ממש שמתלבש באותיות התורה שבא לגילוי מהעלמו העצמי כנ\"ל שנק' מקיף דאו\"י כנ\"ל שהוא סמ\"ך העליון כמו לבוש דאור תו\"מ למטה כמ\"ש ה' צלך ובצל ידי כו' והוא הטעם שנעשה היכל ק\"ק מקומו ממש להיות נתפס שם בגילוי כו', ועכשיו ד\"א של הלכה במקום היכל ק\"ק<sup data-n=\"8615\">705</sup> וכמ\"ש ואשים דברי בפיך ובצ\"ל ידי<sup data-n=\"8616\">706</sup> כו', וכן ה' צלך שה' יושב ושונה כנגדו<sup data-n=\"8617\">707</sup> [כ]שנים שיושבי' ולומדים יחד בהיכל א' דאורייתא היכלא עילאה דקוב\"ה<sup data-n=\"8618\">708</sup> (כמ\"ש במ\"א ע\"פ מי יתנך כאח לי כו' למען אחיי<sup data-n=\"8619\">709</sup> כו'<sup data-n=\"8620\">710</sup> וד\"ל, וזהו כאשר ירבו המקטרגי' על האדם יתחבא בהיכל ואהל דתורה שלא ישיגוהו שם כמ\"ש כי יצפנני בסוכו ביו\"ם רע\"ה יסתירני בסתר אהלו כו', וז\"ש אתה סת\"ר לי<sup data-n=\"8621\">711</sup> כו' וכן יושב בסתר<sup data-n=\"8622\">712</sup> כו' (וכן מ\"ש ואתה מרום<sup data-n=\"8623\">713</sup> כו' יעקב משמש במרום<sup data-n=\"8624\">714</sup> כמ\"ש במ\"א).\n<b>וזהו</b> ג\"כ עיקר ענין יו\"כ שא' כי בענן אראה<sup data-n=\"8625\">715</sup> על הכפורת דוקא, דענן זה זהו בחי' מקיף ולבוש שמתלבש בו מבחי' פנימי' מהו\"ע ית' ובו דוקא מתגלה לבנ\"י כמ\"ש כי בענן ארא\"ה להיות מזה המשכת המקיפי' דסוכות בסכ\"ך שנק' צילא דמהימנותא<sup data-n=\"8626\">716</sup> וכן<sup data-n=\"8627\">717</sup> ענין ענני כבוד שהיו במדבר, וכן במשה א' הנה בא אליך<sup data-n=\"8628\">718</sup> בעב הענן כו' שכל התגלות אור העצמו' דא\"ס לעיני כל בנ\"י הכל הי' ע\"י הענן דוקא כמבואר בכל המקומות, וגם בי\"ג מדה\"ר (בפ' תשא) א' וירד ה' בענן<sup data-n=\"8629\">719</sup> כו', וכ\"ש במשכן דכתי' ויכס הענן את א\"מ<sup data-n=\"8630\">720</sup> כו' ובהעלות הענן<sup data-n=\"8631\">721</sup> כו' כי ענן ה' על המשכן יומם<sup data-n=\"8632\">722</sup> כו', אך לאחר חטא בני אהרן בקרבתם לפני ה'<sup data-n=\"8633\">723</sup> וימותו א' ה' למשה דבר אל אהרן ואל יבא<sup data-n=\"8634\">724</sup> בכל עת אל הקדש כו' אל פני הכפורת אשר על הארון ולא ימות כי בענן אראה כו' שזה אינו אלא ביו\"כ<sup data-n=\"8635\">725</sup> דוקא כשנכנס כה\"ג להיכל ק\"ק, ועכשיו ד\"א של הלכה כמו לבוש דענן שבו יתגלה פנימי'",[["8613","703","<b>צמצם שכינתו. . הארון</b>: נסמן לעיל פ' בא צט, ב."],["8614","704","<b>בהיכל. . מקום מנוחתי</b>: רמב\"ם הל' ביהב\"ח פ\"א, ה\"ג. ושם הובא מתהלים קלב, יד. ישעי' סו, א (ראה רד\"ק שם. סנהדרין ז, א)."],["8615","705","<b>ד\"א של הלכה במקום היכל ק\"ק</b>: נסמן לעיל פ' בא צד, א."],["8616","706","<b>ואשים דברי בפיך ובצ\"ל ידי</b>: ישעי' נא, טז."],["8617","707","<b>ה' צלך שה' יושב ושונה כנגדו</b>: נסמן לעיל סה, ד."],["8618","708","<b>דאורייתא היכלא עילאה דקוב\"ה</b>: ראה זהר ויקהל ר, ע\"א."],["8619","709","<b>מי יתנך. . למען אחיי</b>: שה\"ש ח, א. ראה סידור שער הק\"ש עו, ד ואילך. אמ\"ב שם פמ\"ב. פמ\"ג. לקמן רלז, א. פ' ויקהל תכ, א."],["8620","710","<b>כו'</b>: אוצ\"ל: כו')."],["8621","711","<b>אתה סת\"ר לי</b>: תהלים לב, ז."],["8622","712","<b>יושב בסתר</b>: תהלים צא, א."],["8623","713","<b>ואתה מרום</b>: תהלים צב, ט."],["8624","714","<b>יעקב משמש במרום</b>: זהר ח\"ש קלג, א. ראה מאמרי אדה\"א דברים ח\"א ע' קמ. וש\"נ."],["8625","715","<b>כי בענן אראה</b>: אחרי טז, ב. ראה מאמרי אדה\"א דברים ח\"ג ע' א'קלא ואילך."],["8626","716","<b>צילא דמהימנותא</b>: ראה זהר אמור קג, א. סידור שער הסוכות רנז, א. מאמרי אדה\"א דברים ח\"ד ע' א'רל. ע' א'שלה."],["8627","717","<b>וכן</b>: ו: והן."],["8628","718","<b>הנה בא אליך</b>: יתרו יט, ט [בדילוג]. או: הנני — ראה מאמרי אדה\"א דברים ח\"ג ע' א'קלד. ח\"ד ע' א'רמד."],["8629","719","<b>בפ' תשא. . וירד ה' בענן</b>: לד, ה."],["8630","720","<b>ויכס הענן את א\"מ </b>[ אהל מועד]: פקודי מ, לד."],["8631","721","<b>ובהעלות הענן</b>: פקודי שם, לו."],["8632","722","<b>כי ענן ה' על המשכן יומם</b>: שם מ, לח."],["8633","723","<b>בקרבתם לפני ה'</b>: אחרי טז, א."],["8634","724","<b>דבר. . ואל יבא</b>: שם טז, ב [בדילוג]."],["8635","725","<b>שזה. . ביו\"כ</b>: ראה לקח טוב שם. רש\"י שם פסוק ג."]]],[2300540992,"ועצמו' מהו\"ע ית', וז\"ש יקרה היא מפנינים<sup data-n=\"8636\">726</sup> מכה\"ג שנכנס כו', והוא בחי' <span data-k=\"pg\">512</span> ּ לבוש ומקיף דאו\"י דאור התורה שיתגלה לע\"ל שא' עוטה אור כשלמה נוטה שמים כיריעה, שזהו ענין מ\"ש אפריו\"ן עשה לו המלך שלמה כו' וא' בזהר עשה לו לגרמי'<sup data-n=\"8637\">727</sup> כו' והן בחי' יריעות שלמה שהן בתכלית ההבהקה [ולבנונית] כו' (שזהו כאהלי קדר שנתברר מחשמ\"ל התחתו\"ן דנוג\"ה ע\"י ח\"ת דתורה שלמטה במצות גשמיות דוקא והוא שמלביש לנשמה שתעלה עד אין שיעור למעלה כמ\"ש ילכו מחי\"ל כו', וז\"ש במשה שנגש אל הערפ\"ל אשר שם כו' ודיוק<sup data-n=\"8638\">728</sup> במצות עיו\"ן דתורה שמדייק במילי דחכ' דאוריי' כמ\"ש יעש\"ה למחכ\"ה לו<sup data-n=\"8639\">729</sup> כמ\"ש בזהר ומבואר במ\"א שזהו סמ\"ך התחתון כנ\"ל, אבל מצות קריאה בדבור זהו מקיף דאו\"י כמ\"ש אנכי כנ\"ל, והא בהא תליא שע\"י הבירורי' דנוג\"ה למטה נהפך בחי' חש\"ך סתר\"ו הנ\"ל להאיר בגילוי מהעלם דעצמו' כמו בענן ארא\"ה דוקא כנ\"ל בוי\"ו דסו\"ס שיתחברו יחד כמו שהי' במ\"ת והוא העוה\"ב שיתגלה מהעלמו העצמי' לגמרי, ולא כמו שבתורתו של ר\"מ כ' כתנות או\"ר באל\"ף<sup data-n=\"8640\">730</sup> וכיריעו\"ת שלמה הנ\"ל שהרי א' אז ולא יכנף עוד<sup data-n=\"8641\">731</sup> כו' אפי' בלבוש זך דאור תורה כו', רק במ\"ת א' אפריון כו' שהוא בחי' חופ\"ה כמ\"ש כי על כל כבוד חופ\"ה<sup data-n=\"8642\">732</sup> שכולל ב' מקיפי' דאו\"ח ואו\"י הנ\"ל, וכמ\"ש ביום חתונתו זו מ\"ת שזהו<sup data-n=\"8643\">734</sup> אירוסין<sup data-n=\"8644\">733</sup> במקיף דחופ\"ה<sup data-n=\"8645\">735</sup> וקדושין<sup data-n=\"8646\">736</sup> וביום שמחת לבו בחי' נשואין לע\"ל<sup data-n=\"8647\">737</sup> בעוה\"ב וד\"ל (ועכ\"ז הרי גם במ\"ת הי' בבחי' ראי' במהו\"ע ית' ממש וכמ\"ש וכל העם רואים את הקולות<sup data-n=\"8648\">738</sup> וא' רואי' את הנשמע<sup data-n=\"8649\">739</sup> כו' וכמ\"ש פב\"פ דיבר ה' עמכם<sup data-n=\"8650\">740</sup> כו' כי באור פניך ממש נתת לנו<sup data-n=\"8651\">741</sup> כו', ומ\"ש בשמחת לבו קאי במ\"ת כנ\"ל במ\"ש שם נשמחה בו ממש כו').\n<b>(ויובן</b> כל הנ\"ל באופן אחר ע\"פ הידוע במ\"ש אך בצלם יתהלך איש<sup data-n=\"8652\">742</sup> שמ\"ם דצל\"ם הוא בחי' מקיף דיחידה שנק' מקיף למקיף ששורה על ד\"א של אדם למעלה מראשו (וכמ\"ש במ\"א בענין נשיאת כפים למעלה מן הראש כמ\"ש וישא אהרן<sup data-n=\"8653\">743</sup> כו'),",[["8636","726","<b>יקרה היא מפנינים</b>: משלי ג, טו. סוטה ד, ב. ראה מאמרי אדה\"א בראשית ע' ג וע' כ ואילך (ובהנסמן בריש המאמר שם)."],["8637","727","<b>אפריו\"ן עשה לו. . לגרמי'</b>: שה\"ש ג, ט. זהר בראשית כט, א. תרומה קכז, ב."],["8638","728","<b>ודיוק</b>: בו: והיינו."],["8639","729","<b>שמדייק. . יעש\"ה למחכ\"ה לו</b>: נסמן לעיל ח, ג."],["8640","730","<b>כתנות או\"ר באל\"ף</b>: נסמן לעיל פ' שמות ח, ב."],["8641","731","<b>ולא יכנף עוד</b>: ישעי' ל, כ."],["8642","732","<b>כי על כל כבוד חופ\"ה</b>: ראה גם לעיל ח, ד. וש\"נ."],["8643","734","<b>מ\"ת שזהו אירוסין</b>: ראה גם סידור דרושים לחתונה קלא, ג. ברכת נשואין קלח, ג. ד. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370202\" data-slug=\"torah-or\" data-id=\"3901370202\">תו\"א ויגש מד, ד</a>. מאמרי אדה\"א דרושי חתונה ח\"ב ע' תקצד. ע' תרב. ע' תרד. ע' תרכה. ע' תרל. אוה\"ת ראה ע' תרסז. לקמן רח, ג ובהערה 32."],["8644","733","<b>ביום חתונתו. . שזהו אירוסין</b>: ראה סידור דרושים לחתונה קלא, ב."],["8645","735","<b>במקיף דחופ\"ה</b>: א: כמקיף דחופה. ו: כמו בחופה."],["8646","736","<b>אירוסין. . דחופ\"ה וקדושין</b>: ראה גם מאמרי אדה\"א דרושי חתונה ח\"ב ע' תקצד. ע' תרד."],["8647","737","<b>נשואין לע\"ל</b>: ראה שמו\"ר ס\"פ טו. הנסמן בהערה 734."],["8648","738","<b>וכל העם רואים את הקולות</b>: יתרו כ, טו."],["8649","739","<b>רואי' את הנשמע</b>: רש\"י ומכילתא יתרו כ, טו. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300061131\" data-slug=\"likkutei-sichot\" data-id=\"1300061131\">לקו\"ש יתרו כרך ו ע' 120</a> בהערה ובהשמטה לשם בע' 416. ראה מאמרי אדה\"א במדבר ח\"ב ע' תרכו."],["8650","740","<b>פב\"פ דיבר ה' עמכם</b>: ואתחנן ה, ד."],["8651","741","<b>כי באור פניך. . נתת לנו</b>: סיום תפלת העמידה."],["8652","742","<b>אך בצלם יתהלך איש</b>: תהלים לט, ז. ראה מאמרי אדה\"א דברים ח\"ב ע' תצח ואילך ובהנסמן בריש המאמר שם."],["8653","743","<b>וישא אהרן</b>: ראה הנסמן לעיל פ' וארא עב, ב."]]],[2300540997,"וז\"ש אל יצא איש ממקומו<sup data-n=\"8654\">744</sup> כו', וצ\"ל דצלם הוא בחי' מקיף דחי' ששורה על הלבושי'<sup data-n=\"8655\">745</sup> והוא הנק' מזל\"א כידוע ואמנם מקיף דיחידה נק' צ\"ל צל\"ו (ובל' הגמ' נק' בבואה דבבואה<sup data-n=\"8656\">746</sup> וא' דבבוא' דבבבואה לית להו לשדי' ופרש\"י צל צל\"ו כמ\"ש במ\"א). אך זהו כמו שהנפש מלובשת באברי הגוף דבחי' נר\"נ שבה מלובשי' במוחא ולבא<sup data-n=\"8657\">747</sup> כו' בבחי' או\"פ בכלי שזהו בחי' צדי\"ק דצלם אבל המקיפי' דחי' ויחידה הן בהעלם בלתי מלובשי' בגוף כידוע, אך כמו שהנפש היא בלא גוף כלל הרי נהפוך הוא שבחי' המוחי' ומדות דנר\"נ וגם חיצוני' הכלים כלולים בהעלם דמקיף דחי' שנק' מזלא שמלבישה, ובחי' חיה נכללת ביחידה שהוא העלם עצמות הנפש ממש שכלולה בה גם [בחי'] המקיף דחי' שהוא הרצון ותענוג הנעלם כו', וכמו בשינה שאז הסתלקו' המוחי' ומדות דנר\"נ וגם הרצון ותענוג וגם החכ' כמו שהיא בבחי' העלם נכלל <span data-k=\"pg\">רנו</span> ּ הכל בבחי' יחידה (כמ\"ש במ\"א שזהו ג\"כ בחי' עיבור הולד במעי אמו שמלמדי' אותו כו' שמאיר בו בחי' מקיף דיחידה<sup data-n=\"8658\">748</sup> והכל כלול בו כו' (והיינו ענין הגלגולי' שעצם הנפש כמו שהיא מתלבשת בצומח וחי כו'), אך כאשר יורדת הנפש בגילוי מן ההעלם בגוף בנר\"נ שבה נשאר ב' מקיפים דחי' יחידה בהעלם ונק' צלם או צל כמו סר צלם<sup data-n=\"8659\">749</sup> כו' ומקיף דיחידה מתפשט בד\"א שלו כנ\"ל, ולפ\"ז הרי כמו שהנפש למעלה עיקר בחי' מקום שלה הוא למעלה בבחי' יחידה שלכך נק' יחידה להיותה אור [א'] פשוט ועצמי בלי התחלקות כלל אפי' בהעלם הרצון ותענוג וחכ' כו'. וזהו שא' דנפש בעשי' ורוח ביצי' ונשמה בבריאה וחי' באצי' ויחידה<sup data-n=\"8660\">750</sup> בכתר<sup data-n=\"8661\">751</sup> דאצי' כמו נשמת אדה\"ר שהי' כולל כל הנשמות<sup data-n=\"8662\">752</sup> קודם החטא היו רגליו בעשי' וראשו בבריאה<sup data-n=\"8663\">753</sup> ומקיף דחי' באצי' ויחידה במקור האצי', וכך הוא בכל נשמה בפרט וכמא' כל הנשמות חקוקות בכסא<sup data-n=\"8664\">754</sup> כו', ובכלל דכנ\"י א' שימני כחותם<sup data-n=\"8665\">755</sup> [על לבך] כו' דיוקני אשתאר בך<sup data-n=\"8666\">756</sup> ממש שהוא בחי' יחידה שנשארה דבוקה בך ממש, וע\"כ א' כולך יפה רעייתי<sup data-n=\"8667\">757</sup> כו' דאין פגם דנר\"נ מגיע בבחי' יחידה כלל וז\"ש מיד כלב יחידתי<sup data-n=\"8668\">758</sup> ועלי' א' בזהר ונפש כי תחטא תווהא<sup data-n=\"8669\">759</sup> הוא כידוע וד\"ל (וזהו שאו' נשמה שנתת בי טהור\"ה היא מבחי' טה\"ע<sup data-n=\"8670\">760</sup> שנק' שה\"ש כנ\"ל וירדה למטה להיות כלולה מבי\"ע בחי' נר\"נ בצלם אדם העליון וזהו בראת יצרת נפחת בי ואתה",[["8654","744","<b>אל יצא איש ממקומו</b>: בשלח טז, כט. ראה גם מאמרי אדה\"א קונטרסים ע' יב. נ\"ך ע' רמא. וש\"נ."],["8655","745","<b>מקיף דחי' ששורה על הלבושי'</b>: ראה ע\"ח (שער דרושי אבי\"ע) שמ\"ב, פ\"ג. פע\"ח (שער התפלה) ש\"א, פ\"ב. מאמרי אדה\"א קונטרסים ס\"ע יא ואילך. וש\"נ. לקמן פ' משפטים ש, ד. תצוה שנח, א. שנט, ד. שסו, א. שעד, ד. ויקהל תיט, א (דנר\"נ)."],["8656","746","<b>מקיף דיחידה נק' צ\"ל צל\"ו. . בבואה דבבואה</b>: יבמות קכב, א וברש\"י שם. ראה מאמרי אדה\"א דברים ח\"ב ע' תקמב ואילך."],["8657","747","<b>נר\"נ. . במוחא ולבא</b>: נסמן לעיל קמה, א."],["8658","748","<b>הולד. . שמלמדי' אותו. . דיחידה</b>: ראה נדה ל, ב. מאמרי אדה\"א בראשית ע' קיא. וש\"נ. לעיל פ' שמות לח, ד. לקמן פ' ויקהל שצט, סע\"ד. תב, ג."],["8659","749","<b>סר צלם</b>: שלח יד, ט."],["8660","750","<b>דנפש. . ויחידה</b>: נסמן לעיל פ' בא פט, ג."],["8661","751","<b>דנפש. . ויחידה בכתר</b>: ראה גם ת\"ז סתכ\"ב ובכס\"מ שם. ספר הגלגולים פ\"א. שער הגלגולים הקדמה א."],["8662","752","<b>אדה\"ר שהי' כולל כל הנשמות</b>: נסמן לעיל פ' שמות יז, א."],["8663","753","<b>אדה\"ר. . וראשו בבריאה</b>: נסמן לעיל פ' שמות מ, ב."],["8664","754","<b>כל הנשמות חקוקות בכסא</b>: במאמרי אדה\"א דברים (ח\"ב ע' תצט. וש\"נ) מובא בשם הגמ'. ראה ת\"ז תכ\"ב (סה, ב. סו, א)."],["8665","755","<b>שימני כחותם</b>: שה\"ש ח, ו."],["8666","756","<b>דיוקני אשתאר בך</b>: ראה זהר ויחי רמד, סע\"ב ואילך. (סבא) משפטים קיד, א."],["8667","757","<b>כולך יפה רעייתי</b>: ראה לעיל פ' וארא קו, ב. וש\"נ."],["8668","758","<b>מיד כלב יחידתי</b>: תהלים כב, כא."],["8669","759","<b>ונפש כי תחטא תווהא</b>: ויקרא ה, א. ראה זהר ויקרא יג, ב. טז, א. מאמרי אדה\"א הנחות תקע\"ז ע' שב. וש\"נ."],["8670","760","<b>נשמה. . טהור\"ה. . טה\"ע</b>: ברכת אלקי נשמה (מברכות ס, ב). ראה גם מאמרי אדה\"א דברים ח\"ב ס\"ע תנח ואילך. שע\"ת ל, ב. צה, ד. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670463\" data-slug=\"torat-chaim\" data-id=\"2300670463\">תו\"ח בראשית כז, סע\"ב</a> ובהערה 15."]]],[2300541002,"משמרה בקרבי מבחי' מ\"ם דצלם, וז\"ש אך בצלם דוקא יתהלך איש למטה בנר\"נ שבגוף שזהו מקיפי' דחי' יחידה, וזהו מצד שכל נשמה בפרט יש לה שרש למעלה בנר\"נ דבי\"ע וחי' יחידה דאצי' כידוע דכל הנשמות הן מל' כלים דז\"א<sup data-n=\"8671\">761</sup> פנימי אמצעי [ו]חיצון וא\"כ גם בנפש דעשי' יש בה כל ה' מדרגות דנר\"נ ח\"י<sup data-n=\"8672\">762</sup> גם בהיותה בגוף שנק' נפש בעשי' אך שרוח שלה ביצי' ונשמה שלה בבריאה כו' כנ\"ל, ובעלותה מן הגוף ע\"ז א' ג\"כ אך בצלם יתהלך איש שהולך למקורו הראשון ע\"י צלם דהיינו בחי' המקיף דיחידה שהיא עיקר<sup data-n=\"8673\">763</sup> מקומה והוא לבוש החשמ\"ל שמלבישה ומקיפה שמוליך לנשמה עד שרשה הראשון בעליו' הנשמות בג\"ע כידוע וד\"ל).\n<b>והדוגמא</b> מכ\"ז יובן ג\"כ בבחי' נר\"נ דאדם העליון דאצי' שבצלם אלקי' עשה וברא לנשמת אדם התחתון כידוע שבחי' נר\"נ מלובש באו\"כ כמ\"ש חכ' מוחא<sup data-n=\"8674\">764</sup> כו' ובחי' חי' יחידה הן ב' מקיפים דכת\"ר וכת\"ר שבכת\"ר, ובכלל הרי גם ז\"א דאצי' נק' אדם דעשי' בחי' אדם חיצוני וע\"י וא\"א אדם דיצי' וא\"ק אדם דבריאה<sup data-n=\"8675\">765</sup> [כ]אדה\"ר שנק' נשמת כל חי<sup data-n=\"8676\">766</sup> בכלל ובחי' חי' יחידה היינו ב' מקיפי' דטה\"ת וטה\"ע שנק' שמים ושה\"ש כנ\"ל, וזהו בצל\"ם יתהלך איש העליון בחי' מ\"ם דצלם כמו מקיף דיחידה באדם למטה שהוא בחי' טה\"ע כו' וד\"ל. אך זהו דוקא כמו שהארת אוא\"ס מתצמצם בקו\"ח להיות בבחי' מקור להשתלשלו' דא\"ק עד רגלי א\"ק בעשי'<sup data-n=\"8677\">768</sup> כו' שנק' חי העולמים<sup data-n=\"8678\">767</sup> בכללות, אבל קודם הצמצום שהי' הוא ושמו בלבד זהו כמו הנשמה בלא גוף כמא' אשתארו כגופא בלא<sup data-n=\"8679\">769</sup> כו' זהו בחי' <span data-k=\"pg\">514</span> ּ התנשאות שמצד עצמו הנ\"ל, שלמעלה גם מבחי' מקיף למקיף דטה\"ע ששיער בעצמו' הרצון כמא' שאין העולם מקומו כלל אפי' להיות במקיף למקיף, להיות שאין ערך כלל בין צמצום האור דא\"ס באבי\"ע לגבי אור העצמו' ממש עד שנק' יחי\"ד לבדו וכמו בחי' יחידה באדם כו' שזהו מקומו העצמי כו' כנ\"ל וד\"ל.\n<b>וז\"ש</b> השמים כסאי כו' שזהו בחי' שה\"ש כנ\"ל איזה בית אשר תבנו לי כו' שגם שבבית והיכל שורה בחי' מקיף למקיף בד\"א כנ\"ל, אבל מאחר שאין העולם מקומו כנ\"ל דגם שה\"ש",[["8671","761","<b>דכל הנשמות הן מל' כלים דז\"א</b>: ראה גם לקמן קצה, ב."],["8672","762","<b>בנפש דעשי'. . דנר\"נ ח\"י</b>: ראה ע\"ח (שער המוחין) ש\"כ, פ\"ה. (שער פנימיות וחצוניות) ש\"מ, דרוש יא."],["8673","763","<b>עיקר</b>: ו: ליתא."],["8674","764","<b>חכ' מוחא</b>: נסמן לעיל כח, ד."],["8675","765","<b>ז\"א דאצי'. . וא\"ק אדם דבריאה</b>: נסמן לעיל קמה, ג."],["8676","766","<b>נשמת כל חי</b>: תפלת שבת."],["8677","768","<b>רגלי א\"ק בעשי'</b>: ראה ע\"ח (דרוש עגו\"י) ש\"א, ענף ד. הנסמן במאמרי אדה\"א ויקרא ח\"א ע' טו."],["8678","767","<b>בקו\"ח. . שנק' חי העולמים</b>: נסמן לעיל קסא, א."],["8679","769","<b>אשתארו כגופא בלא</b>: ראה ת\"ז בהקדמה (יז, ב)."]]],[2300541007,"שנק' טה\"ע זהו כמו מקיף דיחידה שאינו אלא בהתלבשות הנשמה בגוף שאין לזה ערך כלל לגבי העלם עצמו' הנפש כמו שהיא במקומה למעלה שהוא בחי' יחידה עצמה ולמעלה זהו בחי' יחיד לבדו (שלמעלה גם מבחי' [ה]התנשאו' שמצ\"ע כנ\"ל בענין ב' סמכי\"ן הנ\"ל (וכמו בזמן הגלות שנק' דורמיטא<sup data-n=\"8680\">771</sup> בחי' שינה<sup data-n=\"8681\">770</sup> שאז אסתלק לעילא לעילא היינו כמו שהכל נכלל בבחי' יחידה עצמה כו' כמו בחי' עיבור הנ\"ל שע\"ז א' אלכה [ו]אשובה אל מקומ\"י העצמי שנק' יחיד ממש (ובדרך פרט הוא מארז\"ל בליל[יא] מאי עביד<sup data-n=\"8682\">772</sup> רוכב על כו' ושט כו' שזהו בחי' העלי' במהו\"ע ממש שאז אין כל ההשתל' תופס מקום כלל וכלל מטעם הנ\"ל, ולכך א' אין כמוך באלמים<sup data-n=\"8683\">773</sup> הן הן גבורותיו שגוים מרקדי'<sup data-n=\"8684\">774</sup> כו', וזהו כאהלי קד\"ר בלבוש ש\"ק וקדרות כיריעות שלמה בהאר' מקיף העליון ביותר הכל א'. וזהו שיהי' העוה\"ב בגילוי אור העצמו' דוקא שזה בא רק מסיב\"ת ההעלאה במקומו העצמי בזמן הגלות שנק' הסתר פנים כמ\"ש ביום ההו\"א אסתי\"ר פני<sup data-n=\"8685\">775</sup> כו' וכל שהעלי' למקום נעלה יותר משם יהי' הגילוי דוקא, וזהו הנה ה' יוצא ממקומ\"ו כו' וכן ברוך כבוד ה' ממקומ\"ו דוקא להיות לו ממש דירה בתחתונים וכמו בגילוי שכינה בין ב' בדי הארון דוקא שנק' ביתו והיכלו שנתפס מהו\"ע ממש בו שזהו עכשיו ד\"א של הלכה כנ\"ל והוא בחי' מקיף דאו\"י כנ\"ל, זהו מפני שבחי' מקיף דהעלם העצמו' ממש דוקא (כנשמה בלא גוף כנ\"ל) הוא שנמשך להיות בבחי' מקיף למקיף בהיכל ק\"ק דוקא שזהו בחי' סמ\"ך העליון כנ\"ל שיתגלה מהעלמו העצמי שזהו ממקומו העצמי כמו במ\"ת בא' אנכי כו' בהתלבשות באותיות כו' וכמו מש\"ל הקדמונ\"י כנ\"ל, וזהו בחי' מ\"ם דצלם שנעשה מהעלם העצמו' ממש הנק' יחיד לבדו כו'. וזהו כי בענ\"ן ארא\"ה ממש בענן דוקא כמו בענן ה' שמלא את המשכן [ו]כן בבהמ\"ק דשלמה שא' ה' אמר לשכון בערפ\"ל<sup data-n=\"8686\">776</sup> בנה בניתי בית זבול לך<sup data-n=\"8687\">777</sup> מכון לשבתך עולמי' אע\"פ ששה\"ש לא יכלכלוהו כו' וא' איזה בי\"ת כו' (כמו מקיף דחשמ\"ל שמלביש לנשמה למעלה במקומה שתרד למטה להיות מקיף דיחידה בד\"א של הלכה דוקא וזהו עליות הנשמות בג\"ע ע\"י דיבור דד\"ת שנמשך מצל המקיף דעצמו' א\"ס כמ\"ש ה' צל\"ך ובצ\"ל ידי כו' כנ\"ל וד\"ל).\n<b>וזהו</b> כי תרכב על סוסיך ב' מיני סו\"ס מבחי' מקיף דאו\"ח ומקיף דאו\"י כנ\"ל והן אותיות התורה במח' ודבור, שאותיות המח' הוא בבחי' <span data-k=\"pg\">רנז</span> ּ ההעלם דאו\"ח בעצמו' דוקא כמו מצות העיון והגיון המח' בתורה כנראה בחוש שאותיות המח' משוטטת בהעלם תוך העלם עד עצמות הנפש לעורר מקור הרצון וחכמה כו', ואותיות הדבור הוא בחי' או\"י שיורד מהעלם",[["8680","771","<b>דורמיטא</b>: נסמן לעיל פ' שמות לט, א."],["8681","770","<b>הגלות. . שינה</b>: נסמן לעיל פ' שמות לז, ד בהערה 4."],["8682","772","<b>בליל[יא] מאי עביד</b>: ראה ע\"ז ג, ב."],["8683","773","<b>אין כמוך באלמים</b>: נסמן לעיל פ' שמות יט, ג."],["8684","774","<b>הן הן גבורותיו שגוים מרקדי'</b>: ראה יומא סט, ב. יל\"ש נחמי' רמז תתרעא."],["8685","775","<b>ביום ההו\"א אסתי\"ר פני</b>: נסמן לעיל פ' שמות א, ג הערה 48."],["8686","776","<b>ה' אמר לשכון בערפ\"ל</b>: מל\"א ח, יב."],["8687","777","<b>בנה בניתי בית זבול לך</b>: מל\"א שם, יג."]]],[2300541012,"המקיף דעצמו' לגילוי דוקא וכמו הדיבור בד\"ת שא' ואשים דברי בפיך ובצל ידי כו', ולזה עיקר מצות ת\"ת בדיבור דוקא כמ\"ש ודברת בם<sup data-n=\"8688\">778</sup> כו' למען תהי' תורת ה' בפיך<sup data-n=\"8689\">779</sup> דוקא וכן א' לא בשמים היא<sup data-n=\"8690\">780</sup> לאמר מי יעלה לנו השמימה בחי' מקיף דשה\"ש הנ\"ל רק קרוב אליך הדבר בפיך<sup data-n=\"8691\">781</sup> כו' (כמ\"ש במ\"א) (ואע\"פ שמהבל הדיבור נעשה או\"מ<sup data-n=\"8692\">782</sup> דאו\"ח דוקא כמ\"ש במ\"א, זהו מצד בירור החשך דק\"נ דהבל דנה\"ט שעולה למעלה להיות לבוש דחשמ\"ל ומגן ומחסה לנשמה כו' והוא כשומר לנשמה מן החיצוני' כמ\"ש ואתה משמרה בקרבי כו' ועל ידה תעלה הנשמה [ל]ג\"ע בלבושי דכיא<sup data-n=\"8693\">783</sup> כמ\"ש בהתהלכך תנחה אותך<sup data-n=\"8694\">784</sup> בשכבך תשמור כו', אבל בחי' עצם אור דתורה של מעלה שנק' מקומו העצמי למעלה כנ\"ל זהו הבא באותיות הדבור שהוא דבר ה' ממש כמ\"ש ואשים דברי כו' בי' הדברות במ\"ת שע\"ז א' כי תרכב על סוסיך כו' שהוא מרכבה הב' הנ\"ל שמוריד הרוכב למטה דוקא כנ\"ל וד\"ל).\n<b>וזהו</b> סוס ורוכבו רמה בים, דהנה מבואר למעלה בעיקר קי\"ס שהי' הכנה למ\"ת דוקא שיהי' התגלות אור העצמו' דא\"ס ב\"ה באותיות התורה בבחי' התכללות דאו\"י ואו\"ח ב' מיני סוסים הנ\"ל שהן כמו מצות עיון ומצות קריאה באותיות דמו\"ד כנ\"ל, וזה נעשה ע\"י היפוך ים ליבשה בקי\"ס שנעשה מבחי' ההעלם גילוי שזהו מבחי' התנשאות שמצד עצמו שנק' סדכ\"ס כו' הוא שבא לגילוי להיות בבחי' יבשה (כמ\"ש ויולך ה' ברוח קדי\"ם עזה מרוח קדמונו ש\"ע<sup data-n=\"8695\">785</sup> שז\"ש ורוח אלקי' מרחפת כו' בחי' מקיף דאו\"ח הנ\"ל), שמוכרח לומר שהי' ההארה מבחי' מהו\"ע ית' ממש שלמעלה מבחי' העלם וגילוי דאו\"ח ואו\"י הנ\"ל שלפניו ממש נעשה ההעלם גילוי כנ\"ל (וכמו בענ\"ן אראה בענ\"ן המסתיר ארא\"ה דוקא כנ\"ל בסוס בב' מיני מרכבה שרכב עליו המלך במ\"ת כו') דקמי' מהו\"ע ממש אין בחי' מעלה ומטה כלל אפי' מה שעולה למעלה בהתנשאו' ולמטה כו' כנ\"ל). וזהו כי גאה גא\"ה שגאה ומתנשא גם על גיאות דהעלם התנשאו' דעצמו' שגם בחי' חשך סתרו הנ\"ל לא יחשיך ויהי' בגילוי, וכמו התלבשות ההעלם בגילוי אותיות דתורה, וכמו שיהי' לע\"ל בעוה\"ב אשר ע\"ז א' אשר אהי' כו' כנ\"ל, ולכך א' בקי\"ס זה אלי כו'<sup data-n=\"8696\">786</sup> לנוכח ממש כו', וע\"כ מזה הי' הכנה למ\"ת דוקא שהוא מ\"ש כי תרכב על סוסיך כו' כנ\"ל וד\"ל וע\"כ סוס ורוכבו רמה בים, דהנה ידוע בשרש פרעה דק\"נ שהוא בבחי' עור\"ף ואחוריי' דכת\"ר דקדוש\"ה וע\"כ הי' בו ג\"כ בחי' התנשאו' וגיאות ברוממו' העצמו' לומר לי יאורי ואני עשיתני כו' וכה\"ג, ולכך א' מי הוי' אשר אשמע בקולו להיות שרשו במנגד לבחי'",[["8688","778","<b>ודברת בם</b>: ואתחנן ו, ז."],["8689","779","<b>למען תהי' תורת ה' בפיך</b>: בא יג, ט."],["8690","780","<b>לא בשמים היא</b>: נצבים ל, יב."],["8691","781","<b>קרוב אליך הדבר בפיך</b>: נצבים שם, יד [בדילוג]."],["8692","782","<b>שמהבל הדיבור נעשה או\"מ</b>: ראה פע\"ח (שער התפלה) ש\"א, פ\"ד. שער (הציצית) ש\"ג, פ\"ב. ע\"ח שער הכללים ספי\"א. הנסמן במאמרי אדה\"א דברים ח\"ב ע' שפח. דרושי חתונה ח\"א ע' קעה. לעיל פ' שמות מט, א ובהנסמן שם. לקמן רלו, ד. פ' פקודי תס, א."],["8693","783","<b>בלבושי דכיא</b>: ראה גם לעיל פ' שמות ז, ג. וש\"נ."],["8694","784","<b>בהתהלכך תנחה אותך</b>: משלי ו, כב."],["8695","785","<b>ויולך. . מרוח קדמונו ש\"ע</b>: נסמן לעיל פ' בא קמג, ב."],["8696","786","<b>כו'</b>: ו: זה."]]],[2300541017,"ההעלם ואין דכתר דקדושה שהוא בשם אלקי' בהסתר להסתיר אור העצמו' ממש כמו אתה אל מסתתר כענין אלביש שמי\"ם קדרו\"ת ושק כו' <span data-k=\"pg\">516</span> ּ כמ\"ש במ\"א שהוא בחי' מקיף המסתיר ומעלים (וכמו בזמן הגלות כנ\"ל) ושם הוי' הוא בחי' גילוי האור הפנימי' ועצמו' אחר הצמצום וההסתר כידוע שמאיר בתו\"מ וע\"כ כל הניסים ונפלאות שעשה במצרים הי' רק שידעו כי אני הוי'<sup data-n=\"8697\">787</sup> כו' כמ\"ש במ\"א, וזהו בחי' סו\"ס דפרעה לנגד סו\"ס דקדושה הנ\"ל. והיינו ב' מיני אותיות דמו\"ד דבחי' העלם וגילוי דאו\"ח ואו\"י כנ\"ל שהן בק\"נ שהן ב' מיני סמ\"ך ג\"כ, א' בבחי' העלם שהן אותיות דמח' דק\"נ שהוא המעלה למעלה בעומק רום דכת\"ר דק\"נ כמרכבה שנושא לרוכב כו' שהוא בחי' עומק רע דכת\"ר דק\"נ כמבואר למעלה במח' דרע שעולה לעומ\"ר בנפש שבהעלם אחר העלם כו' כמחשבות און דרשע כמ\"ש יעזוב רשע כו'<sup data-n=\"8698\">788</sup> ואיש און מחשבותיו וכן כי יצר מחשבות לבו<sup data-n=\"8699\">789</sup> כו' (לנגד מח' בעומק בעיון דתו'<sup data-n=\"8700\">790</sup> הנ\"ל וכן על כל מח' טובה העולה בעומק טוב הנעלם כו'), וזהו סמ\"ך התחתון דסו\"ס פרעה. והב' סמ\"ך העליון הוא בחי' ירידה והמשכה מן ההעלם דעומ\"ר למטה בגילוי הדבור ובמעשה בפו\"מ שמגלה כל העלם דעמ\"ר כנ\"ל, כריבוי ההוללות וליצנות בניבול פה כו' שהוא מרכבה דק\"נ להוריד הנפש למטה מטה בשאול תחתי\"ת, והוא בחי' עמ\"ר ועמ\"ת דק\"נ שנק' סוס פרעה והרוכב הוא בחי' התנשאו' וגיאות בעצמות הנפש בעמ\"ר במו\"ד ומעשה כמו אם תגביהי כנשר<sup data-n=\"8701\">791</sup> כו' (כמו והתברך בלבבו לאמר בשרירו\"ת לב\"י אל\"ך<sup data-n=\"8702\">792</sup> כו') כמרכבה שמנשא ומרומם לרוכב כו'.\n<b>אך</b> הנה בקי\"ס א' סוס ורוכבו רמה בים לשון רוממות ולשון השלכה כנ\"ל והכל א' דבחי' הרוממות דסוס ורוכבו דפרעה הוא שעשה בהם ההשלכה למטה כמ\"ש צללו כעופרת כו', והטעם הוא כי גאה גאה כו', לפי שבקי\"ס הי' גילוי האור דבחי' גיאות והתנשאו' שמצ\"ע הנ\"ל הנק' סדכ\"ס כו' ע\"כ השפיל גיאים כמו שמתרגם גיאה על גיוותנייא כו', להיות ידוע דגם דבחי' שרש התנשאו' וגיאות דפרעה הוא בכת\"ר דק\"נ כנ\"ל ע\"כ א' לי יאורי ואני כו' שהוא התנשאות מצד עצמו כדוגמא דהתנשאות העצמו' דקדושה, אבל באמת אין בהתנשאו' זו שום ממשות כלל וכלל שהרי נק' חוצפא בעלמא מלכותא בלא תג\"א<sup data-n=\"8703\">793</sup> כו' כמ\"ש כל הגוים כאין נגדו כאפס<sup data-n=\"8704\">794</sup> ותהו ממש נחשבו כו' להיות שרשם רק מחיצוני' ואחוריי' דאחוריי' דכתר דקדושה הנופל למטה כמ\"ש הן גוים כמר מדלי<sup data-n=\"8705\">795</sup> וכשחק מאזנים כו', וע\"כ מיד בהגלות נגלות עליהם בחי' התנשאו' עצמו' דמל' דא\"ס הנ\"ל ממילא יפלו מהתנשאו' שלהם כמו כי",[["8697","787","<b>שידעו כי אני הוי'</b>: ראה לעיל פ' שמות כ, ב. וש\"נ."],["8698","788","<b>יעזוב רשע כו' </b>[ו: דרכו]: ישעי' נז, ז."],["8699","789","<b>כי יצר מחשבות לבו</b>: בראשית ו, ה [ושם: וכל יצר — אמנם הלשון שבפנים מובא בקהלת זוטא פ\"ב פסוק כג]."],["8700","790","<b>בעומק בעיון דתו'</b>: א: בעומק בענין דתו\"מ. ו: בעיון דתו'."],["8701","791","<b>אם תגביהי </b>[או: תגביה]<b> כנשר</b>: נסמן לעיל פ' שמות ל, ג."],["8702","792","<b>והתברך. . אל\"ך</b>: נצבים כט, יח [בדילוג]."],["8703","793","<b>מלכותא בלא תג\"א</b>: נסמן לעיל פ' בא קכז, ב."],["8704","794","<b>כל הגוים כאין נגדו כאפס</b>: ישעי' מ, יז [ושם: מאפס]."],["8705","795","<b>הן גוים כמר מדלי</b>: ישעי' מ, טו."]]],[2300541022,"סר צלם כו' (שהוא מקיף דכת\"ר דק\"נ, לפי שבחי' מקיף למקיף שנק' בבוא\"ה דבבוא\"ה לית להו שהוא בחי' התנשאו' עצמיות לית להו כי אין ואפס הם בעצם ומתבטלי' ממציאותם בגילוי [בחי'] מקיף דמקיף דקדושה שהוא בחי' כת\"ר שבכת\"ר הפנימי (רק בהסתלקו' בחי' התנשאו' העצמו' דקדושה למעלה כנ\"ל אז יש להם מקום להתנשאו' כענין אלביש שמים קדרו\"ת כמו בזמן הגלות הנ\"ל, ועכ\"ז מי לא ייראך מלך הגוים<sup data-n=\"8706\">796</sup> וכן מלך אלקי' על גוים<sup data-n=\"8707\">797</sup> כו' כמ\"ש במ\"א לפי שבבחי' רוממות והתנשאות למעלה בהעלם יכולים גם הם לקבל דקמ\"י' כחשיכ\"ה כאור\"ה כנ\"ל, אבל בקי\"ס הרי הי' דוקא בחי' התגלות מן ההעלם דהתנשאו' ורוממו' העצמו' <span data-k=\"pg\">רנח</span> ּ למטה כמו שאנו או' מלכותך ראו בניך<sup data-n=\"8708\">798</sup> מלכותך דוקא<sup data-n=\"8709\">799</sup> מפני שהוא בוקע הים לפני משה לעשות מבחי' ההעלם גילוי כנ\"ל וד\"ל), ואדרבה הי' מגביה ומרומם אותם למעלה מעלה בבחי' מקיף למקיף הנ\"ל, ולא שיקבלו גם הם יניקה אלא כדי שיפלו משם למטה כי לא יוכלו לעמוד שם כלל, כמו שמצינו בכמה מקומות שמנשא לע\"ש דק\"נ כדי שיפלו כמו התנשאות דהמן שהי' רק בשביל מפלתו כאסתר שא' יבא המלך והמן היום<sup data-n=\"8710\">800</sup> כו', וכהתנשאו' דסנחרב ונבוכדנאצר שמגיאות שלהם הי' סיבת היריד' שלהם דוקא כמ\"ש אם תגביהי כנשר כו' משם אורידך דוקא כמו [בשאון] הגלים שמשפילם כו' וכך הי' גיאות והתנשאות דפרעה לומר לי יאורי כו', והיינו ברדפם בים שהעלם כ\"כ ברוממות והתנשאות כמ\"ש אמר אויב ארדוף אשיג<sup data-n=\"8711\">801</sup> כו' שמזה הי' דוקא ההשלכה שקפאו תהומות צללו כעופרת כו' וכ\"ז מצד שאין להתנשאו' העצמות שלהם קיום כלל בעלותם למעלה דוקא מטעם הנ\"ל וד\"ל (וכמ\"ש בע\"ח דמעמד ומצב דהיכלות דק\"נ<sup data-n=\"8712\">802</sup> הוא בין האו\"פ ובין המקיפים דקדושה פניהם אל האו\"פ ואחוריהם אל המקיף כי לא יוכלו לקבל מאו\"מ שמתבטלים שם לגמרי כו', וז\"ש וישקף ה' על מחנה מצרים כו'), וזהו סו\"ס ורוכבו רמ\"ה בים רוממות והשלכה כא' משום דהא בהא תליא כנ\"ל וד\"ל.\n<b>(ואע\"פ</b> שמבואר למעלה [ש]בחי' רוממות והתנשאות דעצמו' ממש שם שוין לפניו בחי' עומ\"ר ועומ\"ת שמים וגם שה\"ש כו' עד ששוה שם הרחמי' על העליון יותר כמו על התחתון יותר כו' וא\"כ למה הי' תופס מקום גיאות דסוס ורוכבו דפרעה להשפיל גיאי' כו', זהו דוקא בבחי' הסתלקו' ועילוי ברוממות העצמו' למעלה (כמו אלכ\"ה אשוב\"ה אל מקומ\"י כו' בזמן הגלות), אבל כאשר מתגלה בחי' התנשאו' זו שמצ\"ע למטה בגילוי מן ההעלם כנ\"ל זהו הסיבה להיות משפיל גיאי' ומגביה שפלים<sup data-n=\"8713\">803</sup> דוקא שזהו להפוך מעליון לתחתון ומתחתון לעליון",[["8706","796","<b>מי לא ייראך מלך הגוים</b>: ירמי' י, ז."],["8707","797","<b>מלך אלקי' על גוים</b>: תהלים מז, ט. ראה גם מאמרי אדה\"א דברים ח\"ד ע' א'תו."],["8708","798","<b>שאנו או' מלכותך ראו בניך</b>: בתפלת ערבית."],["8709","799","<b>דוקא</b>: ו: ממש."],["8710","800","<b>יבא המלך והמן היום</b>: אסתר ה, ד. ראה מאמרי אדה\"א נ\"ך ע' שעא, וע' תקיא (ובהנסמן בראשי המאמרים שם)."],["8711","801","<b>אמר אויב ארדוף אשיג</b>: בשלח טו, ט."],["8712","802","<b>דמעמד ומצב דהיכלות דק\"נ</b>: ראה גם לעיל פ' שמות כג, ד. וש\"נ. כה, ב."],["8713","803","<b>משפיל גיאי' ומגביה שפלים</b>: ע\"פ נוסח התפלה (עזרת אבותינו)."]]],[2300541027,"דגם שכלא חשיב לגבי הרוממו' דעליון אדרבה היא הנותנת שישפיל לגיאי' למטה ולהגביה שפלים לעשות מעומ\"ר עומ\"ת ומעומ\"ת עומ\"ר כמו שמהפכי' העיגולי' להיות הנמוך גבוה וגבוה נמוך כו', כמו כי רם ה' ושפל יראה דוקא דהכל ענין וטעם א' למה שמשפיל גיאי' ומגביה שפלים דהא בהא [תליא] דבשפלות הגיאי' יגביה השפלים דוקא כו' וד\"ל, וכמו מלך המרומם בעצמו ביותר עד שכלא חשיב לגמרי כל רוממות והתנשאות השרים ומלכי' זולתו כשפלי' ממש, אבל בראותו התנשאו' וגיאות שלהם אז דוקא ישפיל א\"ע להשפיל גיאי' ולהגביה שפלים דוקא להראות שרם ונשגב מהכל ע\"כ יעשה משפל גבוה ומגבוה שפל כו', וזהו כי גאה גאה על הגיאי' דוקא להשפילם ולהגביה שפלים, כמו ישראל שהיו בתכלית השפלות בלב נשבר בים כנ\"ל הגביהם, והשפיל גיאות דפרעה ורכבו ופרשיו כו', וכך בכל זמן שישראל בשפלות ואוה\"ע ברוממות כשמנשאי' א\"ע דוקא כמו סנחרב וכה\"ג אז משפיל גיאים ומגביה שפלים כו', וכמ\"ש וברוב גאונך<sup data-n=\"8714\">804</sup> תהרוס קמיך כו' שאע\"פ שכלא חשיב גיאותם משפיל א\"ע להיות גיאה על גיוותניא להשפילם מטעם הנ\"ל וד\"ל).\n<b>ושרש</b> הענין הוא לפי שבקי\"ס הי' האור מלמעלה ממקור ההשתל' דקו\"ח כו' שנק' נור\"א תהלו\"ת אדון הנפלאות כנ\"ל ששם בחי' העלם וגילוי שוין ממש עד שנהפך ההעלם עצמו <span data-k=\"pg\">518</span> ּ לגילוי כמ\"ש הים ראה וינוס כו' והיינו דגם בחי' סדכ\"ס נהפך לגילוי שזהו גם בחי' התנשאות שמצד עצמו כו', לפי שבבחי' מהו\"ע ית' ממש אין שם בחי' מעלה ומטה כלל, דמה שאוא\"ס למעלה כו' זהו רק בחי' חו\"ג שבו בלבד כנ\"ל, וע\"כ בחי' ב' אותיות דמו\"ד העלם וגילוי שוין שם, ולזאת הי' הכנה למ\"ת שירד ה' כו' שיהי' גילוי ההעלם דעצמו' ממש למטה כמו למעלה ממש לפי שמעלה ומטה שוין ממש (וכמו שיהי' בעוה\"ב שיהי' התגלות אוא\"ס למטה כמו למעלה ממש). ולזאת א' כי גאה גא\"ה דהיינו ששוה ומשוה בחי' גיאות העליון דבחי' ההעלם עם גיאות התחתון דבחי' הגילוי שגם למטה הוא רם ונשגב לבדו כמו שהוא למעלה ממש משום דמעלה ומטה שוין (כמו לע\"ל שיהי' בחי' גילוי פחד ה' מהדר גאון עוזו על כל הברואי' שלמטה כמו למעלה ממש כמ\"ש ובאו במערות צורים כו' מפני פח\"ד ה' והדר גאונו<sup data-n=\"8715\">805</sup> כמו שאו' ושמ\"ך נור\"א על כל מה שבראת למטה כמו למעלה ממש שהוא בחי' נור\"א תהלו\"ת הנ\"ל וכמו לא ירעו ולא ישחיתו<sup data-n=\"8716\">806</sup> כו' וגר זאב עם כבש וארי' כבקר<sup data-n=\"8717\">807</sup> כו' וכה\"ג (וכמו דוגמא לזה הי' בגילוי אלקות בארון אלקי' שנשאו הפרות<sup data-n=\"8718\">808</sup> שהי' בפרות הגשמיי' אותו הביטול במציאות דמרכבה עליונה דפני שור ממש, לפי שאין חילוק כלל בין רוחניות לגשמיות ובין עליון לתחתון לגבי גילוי עצמות אור האלקי' דבחי' מל' דאצי' כמו שהוא ממש טרם",[["8714","804","<b>וברוב גאונך</b>: בשלח טו, ז."],["8715","805","<b>ובאו. . והדר גאונו</b>: נסמן לעיל קנד, ד."],["8716","806","<b>לא ירעו ולא ישחיתו</b>: ישעי' יא, ט. סה, כה."],["8717","807","<b>וגר זאב. . כבקר</b>: ישעי' יא, ו [בדילוג]."],["8718","808","<b>בארון אלקי' שנשאו הפרות</b>: נסמן לעיל פ' וארא עד, א הערה 106."]]]]});
